begin;

create temporary table imported_question_batch2_seed (
  id uuid primary key,
  certification_code text not null,
  lesson_slug text not null,
  question_type text not null,
  question_text text not null,
  difficulty text not null,
  explanation text not null,
  is_published boolean not null,
  source_reference text not null,
  source_order integer not null
) on commit drop;

create temporary table imported_question_option_batch2_seed (
  id uuid primary key,
  question_id uuid not null,
  option_text text not null,
  is_correct boolean not null,
  explanation text not null,
  display_order integer not null
) on commit drop;

insert into imported_question_batch2_seed (
  id, certification_code, lesson_slug, question_type, question_text,
  difficulty, explanation, is_published, source_reference, source_order
)
values
  ('63000000-0000-4000-8000-000000000001', 'az-900', 'application-insights', 'single_choice', 'O que e o Application Insights no Azure?', 'easy', 'Application Insights e um recurso do Azure Monitor especializado em gerenciamento de desempenho de aplicacoes (APM), permitindo coletar telemetria sobre requisicoes, tempos de resposta, excecoes e dependencias de aplicacoes em execucao, ajudando equipes a identificar e diagnosticar problemas rapidamente.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 1),
  ('63000000-0000-4000-8000-000000000002', 'az-900', 'application-insights', 'single_choice', 'Qual tipo de dado o Application Insights tipicamente coleta de uma aplicacao monitorada?', 'easy', 'O Application Insights coleta telemetria detalhada sobre a aplicacao monitorada, incluindo taxas de requisicao, tempos de resposta, taxas de excecao e chamadas a dependencias externas, permitindo uma visao abrangente da saude e do desempenho da aplicacao.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 2),
  ('63000000-0000-4000-8000-000000000003', 'az-900', 'application-insights', 'single_choice', 'Como o Application Insights costuma ser habilitado em uma aplicacao?', 'easy', 'O Application Insights pode ser habilitado por meio de instrumentacao via SDK adicionado ao codigo da aplicacao ou, em muitos cenarios e linguagens suportadas, por auto-instrumentacao, que permite coletar telemetria sem grandes alteracoes no codigo existente.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 3),
  ('63000000-0000-4000-8000-000000000004', 'az-900', 'application-insights', 'single_choice', 'Uma empresa de e-commerce quer identificar problemas de desempenho em sua aplicacao web antes que os clientes comecem a reclamar de lentidao. Qual abordagem, usando Application Insights, melhor atende a essa necessidade?', 'medium', 'Configurar o Application Insights para coletar telemetria continuamente e definir alertas automaticos baseados em metricas de desempenho, como tempo de resposta elevado ou aumento na taxa de excecoes, permite que a equipe identifique e corrija problemas de forma proativa, antes que os clientes sejam significativamente afetados.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 4),
  ('63000000-0000-4000-8000-000000000005', 'az-900', 'application-insights', 'single_choice', 'Uma equipe de desenvolvimento quer entender como os usuarios navegam por um aplicativo, identificando quais funcionalidades sao mais utilizadas e em que ponto os usuarios abandonam o fluxo de compra. Qual recurso do Application Insights e mais adequado para essa analise?', 'medium', 'O rastreamento de eventos personalizados e a criacao de funis de usuario no Application Insights permitem registrar acoes especificas realizadas pelos usuarios e analisar sua jornada dentro da aplicacao, ajudando a identificar em que etapas ocorrem abandonos, como durante um fluxo de compra.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 5),
  ('63000000-0000-4000-8000-000000000006', 'az-900', 'application-insights', 'single_choice', 'Uma aplicacao composta por varios microsservicos esta apresentando lentidao, mas a equipe nao sabe qual servico especifico esta causando o atraso nas respostas. Qual recurso do Application Insights ajuda a identificar visualmente as dependencias entre os componentes e onde ocorrem gargalos?', 'medium', 'O Mapa de Aplicativos (Application Map) do Application Insights exibe visualmente as dependencias entre os diferentes componentes de uma arquitetura, como microsservicos e bancos de dados, destacando pontos de lentidao ou falha, o que ajuda a equipe a identificar rapidamente a origem de um problema de desempenho.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 6),
  ('63000000-0000-4000-8000-000000000007', 'az-900', 'application-insights', 'single_choice', 'Uma equipe de operacoes deseja ser notificada automaticamente sempre que a taxa de excecoes de uma aplicacao ultrapassar um limite considerado anormal, sem precisar verificar manualmente os logs a cada poucos minutos. Qual recurso do Application Insights atende diretamente a essa necessidade?', 'medium', 'A configuracao de alertas baseados em metricas no Application Insights permite que a equipe seja notificada automaticamente quando um limite predefinido, como a taxa de excecoes, e ultrapassado, eliminando a necessidade de verificacao manual constante dos logs da aplicacao.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 7),
  ('63000000-0000-4000-8000-000000000008', 'az-900', 'application-insights', 'single_choice', 'Comparando o Application Insights com o Azure Monitor de forma mais ampla, qual afirmacao descreve corretamente a relacao entre os dois?', 'medium', 'O Application Insights e um recurso do Azure Monitor especializado no monitoramento de aplicacoes, coletando telemetria detalhada sobre desempenho e comportamento, enquanto o Azure Monitor, de forma mais ampla, abrange o monitoramento de infraestrutura, redes e outros recursos de plataforma do Azure.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 8),
  ('63000000-0000-4000-8000-000000000009', 'az-900', 'application-insights', 'single_choice', 'Uma empresa esta decidindo se deve habilitar o Application Insights apenas em producao ou tambem em ambientes de teste e homologacao. Qual analise e mais adequada para embasar essa decisao?', 'hard', 'Habilitar o Application Insights em ambientes de teste e homologacao, alem da producao, pode ajudar a identificar problemas de desempenho antes que a aplicacao seja liberada para os usuarios finais, mas a equipe deve considerar o volume adicional de telemetria gerado e seu impacto na analise dos dados.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 9),
  ('63000000-0000-4000-8000-000000000010', 'az-900', 'application-insights', 'single_choice', 'Uma equipe percebe que, apos configurar alertas de excecao no Application Insights, esta recebendo um numero excessivo de notificacoes, muitas delas relacionadas a erros esperados e de baixo impacto, tornando dificil identificar os problemas realmente criticos. Qual ajuste melhor resolve esse problema?', 'hard', 'Revisar e ajustar os criterios e limites dos alertas configurados no Application Insights, filtrando erros esperados e de baixo impacto, e configurando notificacoes apenas para condicoes que realmente indiquem problemas criticos, e a abordagem mais adequada para reduzir o excesso de notificacoes sem perder a capacidade de deteccao de problemas relevantes.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 10),
  ('63000000-0000-4000-8000-000000000011', 'az-900', 'authentication-vs-authorization', 'single_choice', 'O que e autenticacao no contexto de seguranca e identidade?', 'easy', 'Autenticacao e o processo de verificar a identidade de um usuario, dispositivo ou sistema, confirmando que ele e realmente quem afirma ser, geralmente por meio de credenciais como nome de usuario e senha, certificados digitais ou biometria.', true, 'Microsoft Learn - Modulo ''Describe Azure identity, access, and security'' - unidade ''Authentication vs authorization'' (AZ-900)', 11),
  ('63000000-0000-4000-8000-000000000012', 'az-900', 'authentication-vs-authorization', 'single_choice', 'O que e autorizacao no contexto de seguranca e identidade?', 'easy', 'Autorizacao e o processo que ocorre apos a autenticacao, determinando quais recursos, dados ou acoes um usuario ou sistema ja identificado tem permissao para acessar ou realizar dentro de um ambiente, com base em politicas e permissoes definidas.', true, 'Microsoft Learn - Modulo ''Describe Azure identity, access, and security'' - unidade ''Authentication vs authorization'' (AZ-900)', 12),
  ('63000000-0000-4000-8000-000000000013', 'az-900', 'authentication-vs-authorization', 'single_choice', 'Qual e a relacao correta entre autenticacao e autorizacao em um fluxo tipico de acesso a um sistema?', 'easy', 'Em um fluxo tipico de acesso a um sistema, a autenticacao ocorre primeiro, verificando a identidade do usuario por meio de credenciais. Somente apos essa verificacao, a autorizacao determina quais recursos e acoes especificas esse usuario tem permissao para acessar ou executar.', true, 'Microsoft Learn - Modulo ''Describe Azure identity, access, and security'' - unidade ''Authentication vs authorization'' (AZ-900)', 13),
  ('63000000-0000-4000-8000-000000000014', 'az-900', 'authentication-vs-authorization', 'single_choice', 'Um usuario consegue fazer login com sucesso em um sistema corporativo, informando seu nome de usuario e senha corretos, mas recebe uma mensagem informando que nao tem permissao para acessar um relatorio financeiro especifico. Qual conceito explica essa situacao?', 'medium', 'O cenario descreve uma falha de autorizacao: o usuario foi autenticado com sucesso, comprovando sua identidade por meio de credenciais validas, mas nao possui as permissoes necessarias para acessar o relatorio financeiro especifico, o que e determinado pelo processo de autorizacao.', true, 'Microsoft Learn - Modulo ''Describe Azure identity, access, and security'' - unidade ''Authentication vs authorization'' (AZ-900)', 14),
  ('63000000-0000-4000-8000-000000000015', 'az-900', 'authentication-vs-authorization', 'single_choice', 'Uma empresa deseja implementar autenticacao multifator (MFA) para aumentar a seguranca do acesso de seus funcionarios aos sistemas corporativos. Qual conceito, entre autenticacao e autorizacao, essa medida esta diretamente reforcando?', 'medium', 'A autenticacao multifator (MFA) reforca diretamente o processo de autenticacao, exigindo que o usuario comprove sua identidade por meio de mais de um fator, como senha combinada com um codigo enviado ao celular, reduzindo o risco de acesso indevido caso a senha seja comprometida.', true, 'Microsoft Learn - Modulo ''Describe Azure identity, access, and security'' - unidade ''Authentication vs authorization'' (AZ-900)', 15),
  ('63000000-0000-4000-8000-000000000016', 'az-900', 'authentication-vs-authorization', 'single_choice', 'Uma organizacao configura permissoes especificas para que apenas o departamento financeiro possa acessar determinados relatorios sensiveis dentro de um sistema, mesmo que outros funcionarios tenham contas validas e consigam fazer login normalmente. Qual conceito de seguranca esta sendo aplicado nesse cenario?', 'medium', 'O cenario descreve a aplicacao do conceito de autorizacao, ja que o sistema define quais usuarios, mesmo apos autenticados com sucesso, tem permissao para acessar recursos especificos, como relatorios financeiros restritos ao departamento financeiro.', true, 'Microsoft Learn - Modulo ''Describe Azure identity, access, and security'' - unidade ''Authentication vs authorization'' (AZ-900)', 16),
  ('63000000-0000-4000-8000-000000000017', 'az-900', 'authentication-vs-authorization', 'single_choice', 'Uma equipe de seguranca esta revisando os controles de acesso de uma aplicacao e percebe que qualquer funcionario autenticado consegue visualizar dados de todos os departamentos, mesmo sem necessidade relacionada ao seu cargo. Qual acao, relacionada ao conceito de autorizacao, melhor corrige esse problema?', 'medium', 'Definir permissoes de acesso baseadas em funcao (role-based access control), restringindo a visualizacao de dados de acordo com o departamento e o cargo de cada funcionario, e a acao mais adequada para corrigir o excesso de acesso identificado, aplicando o principio de menor privilegio dentro do conceito de autorizacao.', true, 'Microsoft Learn - Modulo ''Describe Azure identity, access, and security'' - unidade ''Authentication vs authorization'' (AZ-900)', 17),
  ('63000000-0000-4000-8000-000000000018', 'az-900', 'authentication-vs-authorization', 'single_choice', 'Comparando autenticacao e autorizacao, qual afirmacao descreve corretamente a diferenca principal entre os dois conceitos?', 'medium', 'A diferenca principal entre os dois conceitos e que a autenticacao verifica quem o usuario e, geralmente por meio de credenciais, enquanto a autorizacao, que ocorre apos a autenticacao, determina quais recursos, dados ou acoes especificas esse usuario tem permissao para acessar ou realizar.', true, 'Microsoft Learn - Modulo ''Describe Azure identity, access, and security'' - unidade ''Authentication vs authorization'' (AZ-900)', 18),
  ('63000000-0000-4000-8000-000000000019', 'az-900', 'authentication-vs-authorization', 'single_choice', 'Uma empresa relata um incidente em que um funcionario, apos ter suas credenciais comprometidas por um ataque de phishing, conseguiu acessar sistemas aos quais nao deveria ter acesso, mesmo com autenticacao multifator habilitada apenas parcialmente na organizacao. Qual analise e mais adequada sobre as causas desse incidente?', 'hard', 'O incidente descrito envolve tanto uma possivel fragilidade na autenticacao, ja que a autenticacao multifator nao estava habilitada em todos os pontos de acesso, quanto uma possivel falha nas politicas de autorizacao, que permitiram que o funcionario acessasse sistemas alem do necessario para sua funcao, evidenciando a importancia de reforcar ambos os controles.', true, 'Microsoft Learn - Modulo ''Describe Azure identity, access, and security'' - unidade ''Authentication vs authorization'' (AZ-900)', 19),
  ('63000000-0000-4000-8000-000000000020', 'az-900', 'authentication-vs-authorization', 'single_choice', 'Uma equipe de arquitetura esta projetando o controle de acesso de uma nova aplicacao corporativa que sera utilizada por funcionarios de diferentes departamentos, com niveis distintos de sensibilidade de dados. Qual estrategia combinando autenticacao e autorizacao melhor atende a esse cenario?', 'hard', 'Combinar autenticacao robusta, como autenticacao multifator, com autorizacao baseada em funcao, e a estrategia mais adequada para garantir tanto a verificacao confiavel da identidade dos usuarios quanto o controle apropriado de acesso aos dados, assegurando que cada departamento acesse apenas as informacoes relevantes para sua atuacao.', true, 'Microsoft Learn - Modulo ''Describe Azure identity, access, and security'' - unidade ''Authentication vs authorization'' (AZ-900)', 20),
  ('63000000-0000-4000-8000-000000000021', 'az-900', 'azure-advisor', 'single_choice', 'O que e o Azure Advisor?', 'easy', 'O Azure Advisor e um servico gratuito que analisa continuamente a configuracao e o uso dos recursos do Azure de uma assinatura, oferecendo recomendacoes personalizadas em cinco categorias principais: custo, seguranca, confiabilidade, desempenho e excelencia operacional.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 21),
  ('63000000-0000-4000-8000-000000000022', 'az-900', 'azure-advisor', 'single_choice', 'Em quais categorias principais o Azure Advisor costuma organizar suas recomendacoes?', 'easy', 'O Azure Advisor organiza suas recomendacoes em cinco categorias principais: custo, ajudando a identificar oportunidades de economia; seguranca, apontando vulnerabilidades; confiabilidade; desempenho; e excelencia operacional, com boas praticas de gerenciamento dos recursos.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 22),
  ('63000000-0000-4000-8000-000000000023', 'az-900', 'azure-advisor', 'single_choice', 'Qual e uma caracteristica importante das recomendacoes fornecidas pelo Azure Advisor?', 'easy', 'Uma caracteristica importante do Azure Advisor e que suas recomendacoes sao personalizadas, baseadas na analise real da configuracao e do padrao de uso dos recursos da assinatura do Azure do cliente, tornando-as relevantes para o ambiente especifico de cada organizacao.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 23),
  ('63000000-0000-4000-8000-000000000024', 'az-900', 'azure-advisor', 'single_choice', 'Uma empresa percebe que sua fatura mensal do Azure tem aumentado significativamente e suspeita que existam recursos subutilizados ou ociosos em sua assinatura. Qual ferramenta pode ajudar a identificar essas oportunidades de otimizacao de custo?', 'medium', 'O Azure Advisor analisa continuamente o uso dos recursos de uma assinatura do Azure e pode identificar recursos subutilizados ou ociosos, recomendando acoes como redimensionamento ou desativacao, o que ajuda a empresa a identificar oportunidades de otimizacao de custo.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 24),
  ('63000000-0000-4000-8000-000000000025', 'az-900', 'azure-advisor', 'single_choice', 'Uma equipe de seguranca deseja identificar rapidamente configuracoes de recursos do Azure que possam representar vulnerabilidades, sem precisar revisar manualmente cada recurso individualmente. Qual categoria de recomendacao do Azure Advisor e mais relevante para essa necessidade?', 'medium', 'A categoria de seguranca do Azure Advisor e especificamente voltada a identificacao de configuracoes de recursos que possam representar vulnerabilidades ou riscos, sugerindo acoes para mitiga-los, o que atende diretamente a necessidade da equipe de seguranca.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 25),
  ('63000000-0000-4000-8000-000000000026', 'az-900', 'azure-advisor', 'single_choice', 'Uma empresa recebe uma recomendacao do Azure Advisor sugerindo a distribuicao de uma aplicacao critica entre multiplas zonas de disponibilidade para reduzir o risco de indisponibilidade. A qual categoria de recomendacao essa sugestao provavelmente pertence?', 'medium', 'Recomendacoes relacionadas a distribuicao de aplicacoes entre multiplas zonas de disponibilidade, com o objetivo de reduzir o risco de indisponibilidade diante de falhas localizadas, pertencem tipicamente a categoria de confiabilidade do Azure Advisor.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 26),
  ('63000000-0000-4000-8000-000000000027', 'az-900', 'azure-advisor', 'single_choice', 'Comparando o Azure Advisor com uma auditoria manual completa realizada por uma equipe de consultoria externa, qual afirmacao descreve corretamente uma vantagem do Azure Advisor?', 'medium', 'Uma vantagem do Azure Advisor em comparacao a auditorias manuais pontuais e que ele analisa continuamente os recursos da assinatura de forma automatizada e gratuita, oferecendo recomendacoes atualizadas regularmente, sem a necessidade de agendar auditorias especificas com equipes externas.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 27),
  ('63000000-0000-4000-8000-000000000028', 'az-900', 'azure-advisor', 'single_choice', 'Uma equipe de TI acompanha regularmente a pontuacao do Azure Advisor Score, que resume numericamente o quanto os recursos da assinatura seguem as recomendacoes de custo, seguranca, confiabilidade, desempenho e excelencia operacional. Qual e a principal utilidade dessa pontuacao para a equipe?', 'medium', 'O Azure Advisor Score resume numericamente, em cada categoria, o quanto os recursos de uma assinatura seguem as recomendacoes do Azure Advisor, servindo como um indicador que a equipe pode acompanhar ao longo do tempo para medir o progresso das melhorias implementadas.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 28),
  ('63000000-0000-4000-8000-000000000029', 'az-900', 'azure-advisor', 'single_choice', 'Uma empresa recebe diversas recomendacoes do Azure Advisor em diferentes categorias, mas possui recursos limitados de equipe para implementar todas de uma vez. Qual abordagem e mais adequada para priorizar as acoes recomendadas?', 'hard', 'Diante de recursos limitados, a abordagem mais adequada e avaliar o impacto potencial de cada recomendacao do Azure Advisor, priorizando aquelas relacionadas a riscos de seguranca criticos e a oportunidades significativas de economia, tratando recomendacoes de menor impacto em um momento posterior.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 29),
  ('63000000-0000-4000-8000-000000000030', 'az-900', 'azure-advisor', 'single_choice', 'Uma organizacao segue rigorosamente todas as recomendacoes do Azure Advisor, mas ainda sofre um incidente de seguranca causado por uma pratica de configuracao que nao foi identificada pela ferramenta. Qual conclusao e mais adequada sobre as limitacoes do Azure Advisor nesse contexto?', 'hard', 'O Azure Advisor e uma ferramenta valiosa que oferece recomendacoes automatizadas baseadas em padroes conhecidos de configuracao, mas nao substitui uma estrategia abrangente de seguranca, que deve incluir revisoes especializadas, monitoramento continuo e boas praticas complementares as recomendacoes automatizadas da ferramenta.', true, 'Microsoft Learn - Modulo ''Describe monitoring tools in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 30),
  ('63000000-0000-4000-8000-000000000031', 'az-900', 'azure-arc', 'single_choice', 'O que e o Azure Arc?', 'easy', 'O Azure Arc e um servico que estende as capacidades de gerenciamento do Azure a recursos localizados fora do Azure, incluindo servidores on-premises, maquinas virtuais em outras nuvens e ambientes de borda, permitindo gerencia-los de forma unificada por meio das ferramentas do Azure.', true, 'Microsoft Learn - Modulo ''Describe hybrid and multicloud options in Azure'' - unidade ''Azure Arc'' (AZ-900)', 31),
  ('63000000-0000-4000-8000-000000000032', 'az-900', 'azure-arc', 'single_choice', 'Qual e um dos principais objetivos do Azure Arc?', 'easy', 'Um dos principais objetivos do Azure Arc e fornecer um unico ponto de gerenciamento e governanca para recursos distribuidos em ambientes hibridos e multicloud, permitindo aplicar politicas, monitoramento e outras capacidades do Azure a recursos que nao estao fisicamente hospedados no Azure.', true, 'Microsoft Learn - Modulo ''Describe hybrid and multicloud options in Azure'' - unidade ''Azure Arc'' (AZ-900)', 32),
  ('63000000-0000-4000-8000-000000000033', 'az-900', 'azure-arc', 'single_choice', 'Quais tipos de recursos podem ser gerenciados por meio do Azure Arc?', 'easy', 'O Azure Arc permite estender o gerenciamento do Azure a diversos tipos de recursos, incluindo servidores fisicos ou virtuais on-premises, maquinas virtuais hospedadas em outras nuvens e clusters Kubernetes em diferentes ambientes, unificando sua governanca e monitoramento.', true, 'Microsoft Learn - Modulo ''Describe hybrid and multicloud options in Azure'' - unidade ''Azure Arc'' (AZ-900)', 33),
  ('63000000-0000-4000-8000-000000000034', 'az-900', 'azure-arc', 'single_choice', 'Uma empresa possui servidores fisicos em seu proprio datacenter, alem de recursos hospedados no Azure e em outro provedor de nuvem. Ela deseja aplicar politicas de governanca e monitoramento de forma consistente em todos esses ambientes, sem precisar utilizar ferramentas completamente diferentes para cada um. Qual servico atende diretamente a essa necessidade?', 'medium', 'O Azure Arc estende as capacidades de gerenciamento e governanca do Azure a recursos localizados fora do Azure, incluindo servidores on-premises e recursos em outras nuvens, permitindo aplicar politicas, monitoramento e outras ferramentas do Azure de forma consistente em todos esses ambientes.', true, 'Microsoft Learn - Modulo ''Describe hybrid and multicloud options in Azure'' - unidade ''Azure Arc'' (AZ-900)', 34),
  ('63000000-0000-4000-8000-000000000035', 'az-900', 'azure-arc', 'single_choice', 'Uma equipe de TI deseja aplicar a mesma politica de conformidade, como exigir criptografia em disco, tanto para maquinas virtuais hospedadas no Azure quanto para servidores fisicos localizados no datacenter proprio da empresa. Qual abordagem, utilizando Azure Arc, atende a essa necessidade?', 'medium', 'Registrar os servidores on-premises no Azure Arc permite que eles sejam representados como recursos do Azure, possibilitando aplicar as mesmas politicas de governanca, como as do Azure Policy, de forma consistente tanto a maquinas virtuais no Azure quanto a servidores fisicos localizados no datacenter proprio da empresa.', true, 'Microsoft Learn - Modulo ''Describe hybrid and multicloud options in Azure'' - unidade ''Azure Arc'' (AZ-900)', 35),
  ('63000000-0000-4000-8000-000000000036', 'az-900', 'azure-arc', 'single_choice', 'Uma empresa de varejo possui lojas fisicas com servidores locais para processamento de dados de ponto de venda, alem de utilizar recursos na nuvem publica do Azure para analise de dados centralizada. Qual beneficio do Azure Arc e mais relevante para unificar o gerenciamento desses ambientes distintos?', 'medium', 'O beneficio mais relevante do Azure Arc nesse cenario e a capacidade de gerenciar de forma unificada tanto os servidores locais das lojas fisicas quanto os recursos hospedados na nuvem publica do Azure, utilizando as mesmas ferramentas, politicas e praticas de governanca do Azure em ambos os ambientes.', true, 'Microsoft Learn - Modulo ''Describe hybrid and multicloud options in Azure'' - unidade ''Azure Arc'' (AZ-900)', 36),
  ('63000000-0000-4000-8000-000000000037', 'az-900', 'azure-arc', 'single_choice', 'Comparando o gerenciamento de recursos por meio do Azure Arc com o gerenciamento tradicional de servidores on-premises usando ferramentas locais isoladas, qual afirmacao esta correta?', 'medium', 'O Azure Arc permite aplicar de forma consistente politicas de governanca, monitoramento e outras ferramentas do Azure a recursos on-premises, o que geralmente e mais dificil de alcancar utilizando ferramentas locais isoladas e desconectadas entre diferentes ambientes e datacenters.', true, 'Microsoft Learn - Modulo ''Describe hybrid and multicloud options in Azure'' - unidade ''Azure Arc'' (AZ-900)', 37),
  ('63000000-0000-4000-8000-000000000038', 'az-900', 'azure-arc', 'single_choice', 'Uma empresa possui um cluster Kubernetes em execucao em outro provedor de nuvem e deseja aplicar as mesmas politicas de configuracao e seguranca do Azure Policy a esse cluster, junto com os demais clusters que ja possui no Azure. Qual recurso do Azure Arc atende a essa necessidade?', 'medium', 'Registrar o cluster Kubernetes externo como um recurso Arc-enabled Kubernetes permite que a empresa aplique politicas do Azure Policy e outras ferramentas de governanca do Azure de forma consistente, tanto para os clusters nativos do Azure quanto para o cluster em execucao em outro provedor de nuvem.', true, 'Microsoft Learn - Modulo ''Describe hybrid and multicloud options in Azure'' - unidade ''Azure Arc'' (AZ-900)', 38),
  ('63000000-0000-4000-8000-000000000039', 'az-900', 'azure-arc', 'single_choice', 'Uma empresa multinacional possui recursos distribuidos entre o Azure, outro provedor de nuvem publica e diversos datacenters proprios em diferentes paises. A equipe de TI quer aplicar uma unica politica de seguranca, exigindo configuracoes minimas em todos esses recursos, com visibilidade centralizada do nivel de conformidade. Qual abordagem, utilizando Azure Arc, melhor atende a esse cenario complexo?', 'hard', 'Registrar os recursos elegiveis de outros provedores de nuvem e dos datacenters proprios no Azure Arc permite que a empresa aplique politicas de seguranca do Azure Policy de forma consistente e obtenha visibilidade centralizada do nivel de conformidade em todos os ambientes, mesmo distribuidos entre diferentes provedores e paises.', true, 'Microsoft Learn - Modulo ''Describe hybrid and multicloud options in Azure'' - unidade ''Azure Arc'' (AZ-900)', 39),
  ('63000000-0000-4000-8000-000000000040', 'az-900', 'azure-arc', 'single_choice', 'Uma equipe esta avaliando se deve registrar servidores on-premises criticos no Azure Arc, considerando que isso envolve estabelecer conectividade entre esses servidores e o Azure para habilitar determinados recursos de gerenciamento. Qual analise e mais adequada para embasar essa decisao?', 'hard', 'A equipe deve avaliar cuidadosamente os beneficios de gerenciamento unificado proporcionados pelo Azure Arc frente as implicacoes de conectividade e seguranca envolvidas em conectar servidores criticos ao Azure, aplicando controles adequados, como segmentacao de rede e politicas de acesso restritivas, para proteger essa comunicacao.', true, 'Microsoft Learn - Modulo ''Describe hybrid and multicloud options in Azure'' - unidade ''Azure Arc'' (AZ-900)', 40),
  ('63000000-0000-4000-8000-000000000041', 'az-900', 'azure-cli', 'single_choice', 'O que e o Azure CLI?', 'easy', 'O Azure CLI (Command-Line Interface) e uma ferramenta de linha de comando multiplataforma, disponivel para Windows, macOS e Linux, que permite criar, configurar e gerenciar recursos do Azure por meio de comandos digitados, sendo util para automacao e scripts.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 41),
  ('63000000-0000-4000-8000-000000000042', 'az-900', 'azure-cli', 'single_choice', 'Em quais sistemas operacionais o Azure CLI pode ser utilizado?', 'easy', 'O Azure CLI e uma ferramenta multiplataforma, podendo ser instalada e utilizada em sistemas operacionais Windows, macOS e Linux, alem de estar disponivel diretamente no Azure Cloud Shell, sem necessidade de instalacao local.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 42),
  ('63000000-0000-4000-8000-000000000043', 'az-900', 'azure-cli', 'single_choice', 'Qual e uma vantagem de utilizar o Azure CLI para gerenciar recursos do Azure, em comparacao ao uso exclusivo do portal grafico?', 'easy', 'Uma vantagem significativa de utilizar o Azure CLI e a possibilidade de automatizar tarefas repetitivas por meio de scripts, executando varios comandos de forma sequencial e programada, o que e mais dificil de realizar de forma eficiente utilizando apenas o portal grafico do Azure.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 43),
  ('63000000-0000-4000-8000-000000000044', 'az-900', 'azure-cli', 'single_choice', 'Uma equipe de DevOps precisa criar dezenas de maquinas virtuais com configuracoes semelhantes de forma repetida, como parte de um pipeline de implantacao automatizado. Qual abordagem e mais adequada para essa necessidade?', 'medium', 'Utilizar scripts com o Azure CLI para automatizar a criacao de multiplas maquinas virtuais e a abordagem mais adequada para um cenario de pipeline de implantacao automatizado, garantindo consistencia, repetibilidade e reducao de erros manuais em comparacao a criacao individual pelo portal grafico.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 44),
  ('63000000-0000-4000-8000-000000000045', 'az-900', 'azure-cli', 'single_choice', 'Um administrador de TI precisa executar rapidamente uma unica consulta simples para listar todos os grupos de recursos existentes em uma assinatura do Azure, sem necessidade de automacao complexa. Qual abordagem e mais adequada para essa tarefa pontual?', 'medium', 'Para uma tarefa pontual e simples, como listar os grupos de recursos existentes em uma assinatura, executar um comando direto do Azure CLI no terminal ou no Azure Cloud Shell e suficiente e eficiente, sem necessidade de criar scripts complexos ou pipelines de automacao.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 45),
  ('63000000-0000-4000-8000-000000000046', 'az-900', 'azure-cli', 'single_choice', 'Uma equipe de infraestrutura deseja garantir que a criacao de recursos no Azure siga exatamente os mesmos passos em diferentes ambientes, como desenvolvimento, teste e producao, evitando divergencias causadas por configuracoes manuais feitas por diferentes pessoas. Qual pratica, envolvendo o Azure CLI, ajuda a atingir esse objetivo?', 'medium', 'Criar scripts de automacao com o Azure CLI, versionados em um repositorio de codigo, e uma pratica que ajuda a garantir que a criacao de recursos siga exatamente os mesmos passos em diferentes ambientes, como desenvolvimento, teste e producao, reduzindo divergencias causadas por configuracoes manuais.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 46),
  ('63000000-0000-4000-8000-000000000047', 'az-900', 'azure-cli', 'single_choice', 'Comparando o uso do Azure CLI com o uso exclusivo do portal grafico do Azure para tarefas repetitivas e em grande escala, qual afirmacao esta correta?', 'medium', 'Para tarefas repetitivas e em grande escala, o Azure CLI tende a ser mais eficiente do que o uso exclusivo do portal grafico, pois permite automatizar a execucao de comandos por meio de scripts, reduzindo o tempo e o risco de erro em comparacao a repetir manualmente as mesmas acoes.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 47),
  ('63000000-0000-4000-8000-000000000048', 'az-900', 'azure-cli', 'single_choice', 'Uma equipe de automacao precisa que a saida dos comandos do Azure CLI seja facilmente processada por outro script, em vez de apenas exibida de forma legivel para um humano no terminal. Qual caracteristica do Azure CLI atende a essa necessidade?', 'medium', 'O Azure CLI permite formatar a saida dos comandos executados em formatos estruturados, como JSON, o que facilita o processamento automatizado dessa saida por outros scripts e ferramentas, em vez de depender apenas da exibicao padrao em texto legivel para humanos.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 48),
  ('63000000-0000-4000-8000-000000000049', 'az-900', 'azure-cli', 'single_choice', 'Uma equipe esta decidindo se deve padronizar o provisionamento de recursos do Azure exclusivamente por meio do portal grafico ou investir tempo em criar e manter scripts de Azure CLI para essas tarefas. Qual analise e mais adequada para essa decisao, considerando um cenario com dezenas de ambientes semelhantes a serem provisionados regularmente?', 'hard', 'Para um cenario com dezenas de ambientes semelhantes provisionados regularmente, investir tempo em criar e manter scripts de Azure CLI tende a reduzir erros manuais e o tempo total gasto ao longo do tempo, apesar do investimento inicial necessario para desenvolve-los, tornando essa abordagem mais vantajosa do que depender exclusivamente do portal grafico.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 49),
  ('63000000-0000-4000-8000-000000000050', 'az-900', 'azure-cli', 'single_choice', 'Um administrador executa, por engano, um comando do Azure CLI que exclui um grupo de recursos inteiro em producao, causando indisponibilidade de varios servicos criticos. Qual pratica, relacionada ao uso do Azure CLI, poderia ter ajudado a prevenir ou mitigar esse incidente?', 'hard', 'Adotar praticas como testar comandos criticos em ambientes de nao producao antes de executa-los em producao, utilizar parametros de confirmacao para operacoes destrutivas e restringir permissoes de exclusao de recursos a um numero reduzido de pessoas autorizadas sao medidas que ajudam a prevenir ou mitigar incidentes como exclusoes acidentais de recursos criticos.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 50),
  ('63000000-0000-4000-8000-000000000051', 'az-900', 'azure-cloud-shell', 'single_choice', 'O que e o Azure Cloud Shell?', 'easy', 'O Azure Cloud Shell e um ambiente de shell interativo, acessivel diretamente pelo navegador a partir do portal do Azure, que permite executar comandos do Azure CLI ou do Azure PowerShell para gerenciar recursos, sem a necessidade de instalar nenhuma ferramenta localmente.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 51),
  ('63000000-0000-4000-8000-000000000052', 'az-900', 'azure-cloud-shell', 'single_choice', 'Quais linguagens de shell o Azure Cloud Shell tipicamente oferece suporte?', 'easy', 'O Azure Cloud Shell oferece suporte tanto ao ambiente Bash quanto ao PowerShell, permitindo que o usuario escolha o ambiente de linha de comando com o qual esta mais familiarizado para gerenciar recursos do Azure.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 52),
  ('63000000-0000-4000-8000-000000000053', 'az-900', 'azure-cloud-shell', 'single_choice', 'Qual e uma caracteristica pratica do Azure Cloud Shell em relacao a instalacao de ferramentas?', 'easy', 'Uma caracteristica pratica do Azure Cloud Shell e que ele ja vem com ferramentas como Azure CLI e Azure PowerShell pre-instaladas e configuradas, dispensando a necessidade de o usuario instalar ou configurar manualmente essas ferramentas em seu ambiente local antes de comecar a gerenciar recursos.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 53),
  ('63000000-0000-4000-8000-000000000054', 'az-900', 'azure-cloud-shell', 'single_choice', 'Um administrador precisa gerenciar rapidamente recursos do Azure a partir de um computador publico, em uma biblioteca, sem permissao para instalar softwares adicionais nesse computador. Qual ferramenta atende diretamente a essa necessidade?', 'medium', 'O Azure Cloud Shell pode ser acessado diretamente pelo navegador, a partir de qualquer computador com acesso a internet, sem exigir a instalacao de nenhuma ferramenta adicional, o que o torna ideal para cenarios como o de um computador publico sem permissao para instalacao de softwares.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 54),
  ('63000000-0000-4000-8000-000000000055', 'az-900', 'azure-cloud-shell', 'single_choice', 'Uma equipe de suporte tecnico precisa alternar rapidamente entre comandos de Bash e PowerShell durante uma mesma sessao de trabalho, sem precisar configurar dois ambientes completamente separados em suas maquinas locais. Qual caracteristica do Azure Cloud Shell atende a essa necessidade?', 'medium', 'O Azure Cloud Shell permite que a equipe alterne entre os ambientes Bash e PowerShell diretamente dentro da mesma sessao, sem a necessidade de configurar dois ambientes completamente separados em suas maquinas locais, o que agiliza o trabalho de suporte tecnico que utiliza ambos os tipos de comando.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 55),
  ('63000000-0000-4000-8000-000000000056', 'az-900', 'azure-cloud-shell', 'single_choice', 'Uma organizacao deseja que novos funcionarios da equipe de infraestrutura consigam comecar a executar comandos basicos de gerenciamento do Azure em seu primeiro dia de trabalho, mesmo antes de terem seus computadores corporativos totalmente configurados com todas as ferramentas necessarias. Qual solucao, baseada no Azure Cloud Shell, atende a essa necessidade?', 'medium', 'Orientar os novos funcionarios a acessar o Azure Cloud Shell diretamente pelo navegador permite que eles comecem a executar comandos basicos de gerenciamento do Azure em seu primeiro dia de trabalho, mesmo antes de terem seus computadores corporativos totalmente configurados com todas as ferramentas necessarias instaladas localmente.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 56),
  ('63000000-0000-4000-8000-000000000057', 'az-900', 'azure-cloud-shell', 'single_choice', 'Comparando o Azure Cloud Shell com uma instalacao local do Azure CLI em um computador pessoal, qual afirmacao esta correta em relacao a portabilidade?', 'medium', 'O Azure Cloud Shell tende a oferecer maior portabilidade em comparacao a uma instalacao local do Azure CLI, pois pode ser acessado de qualquer dispositivo com navegador e conexao a internet, autenticado com a conta do usuario, sem depender de uma instalacao especifica em um unico computador.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 57),
  ('63000000-0000-4000-8000-000000000058', 'az-900', 'azure-cloud-shell', 'single_choice', 'Um usuario cria e edita alguns arquivos de script dentro de uma sessao do Azure Cloud Shell e deseja que esses arquivos continuem disponiveis na proxima vez que ele acessar o Cloud Shell, mesmo apos encerrar a sessao atual. Qual recurso do Azure Cloud Shell permite essa persistencia de arquivos entre sessoes?', 'medium', 'O Azure Cloud Shell utiliza um compartilhamento do Azure Files, montado automaticamente na primeira vez que o usuario configura o Cloud Shell, para armazenar arquivos de forma persistente, garantindo que scripts e outros arquivos criados permanecam disponiveis em sessoes futuras.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 58),
  ('63000000-0000-4000-8000-000000000059', 'az-900', 'azure-cloud-shell', 'single_choice', 'Uma equipe esta avaliando se deve depender exclusivamente do Azure Cloud Shell para todas as tarefas de automacao de longo prazo de uma organizacao, incluindo pipelines de implantacao continuos que precisam ser executados de forma agendada e sem intervencao humana. Qual analise e mais adequada sobre essa decisao?', 'hard', 'Para pipelines de implantacao continuos e agendados, que precisam ser executados sem intervencao humana, ferramentas de automacao dedicadas, como pipelines de integracao e entrega continua (CI/CD) que utilizam o Azure CLI ou SDKs de forma programatica, tendem a ser mais adequadas do que depender de sessoes interativas do Azure Cloud Shell, que e voltado principalmente para uso interativo pontual.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 59),
  ('63000000-0000-4000-8000-000000000060', 'az-900', 'azure-cloud-shell', 'single_choice', 'Uma empresa observa que diferentes funcionarios estao utilizando o Azure Cloud Shell com permissoes de acesso muito amplas, o que aumenta o risco de acoes indevidas em recursos criticos da organizacao. Qual medida, relacionada ao uso do Azure Cloud Shell, melhor mitiga esse risco?', 'hard', 'Aplicar o principio de menor privilegio, concedendo aos funcionarios apenas as permissoes de acesso estritamente necessarias para o desempenho de suas funcoes, e a medida mais adequada para mitigar o risco de acoes indevidas em recursos criticos, independentemente de a ferramenta utilizada ser o Azure Cloud Shell ou outra forma de acesso ao Azure.', true, 'Microsoft Learn - Modulo ''Explore Azure administration and management tools'' (Percurso: Describe Azure management and governance, AZ-900)', 60),
  ('63000000-0000-4000-8000-000000000061', 'az-900', 'azure-cost-factors', 'single_choice', 'Qual dos fatores a seguir influencia diretamente o custo de um recurso no Azure?', 'easy', 'O tipo de recurso contratado, como maquina virtual, banco de dados ou armazenamento, junto com sua configuracao especifica, como tamanho, desempenho e capacidade, e um dos principais fatores que influenciam diretamente o custo de um recurso no Azure.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 61),
  ('63000000-0000-4000-8000-000000000062', 'az-900', 'azure-cost-factors', 'single_choice', 'Como a regiao geografica escolhida para hospedar um recurso pode influenciar seu custo no Azure?', 'easy', 'O custo de recursos semelhantes no Azure pode variar entre diferentes regioes geograficas, devido a fatores como custos operacionais locais, impostos, infraestrutura e demanda especifica de cada regiao, o que faz com que o mesmo tipo de recurso possa ter precos diferentes dependendo de onde e hospedado.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 62),
  ('63000000-0000-4000-8000-000000000063', 'az-900', 'azure-cost-factors', 'single_choice', 'Como o volume de dados transferidos (trafego de rede) pode influenciar o custo de uso do Azure?', 'easy', 'O volume de dados transferidos, especialmente a saida de dados (egress) de uma regiao para a internet ou entre diferentes regioes do Azure, e um fator que pode gerar custos adicionais, geralmente proporcionais a quantidade de dados efetivamente transferida.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 63),
  ('63000000-0000-4000-8000-000000000064', 'az-900', 'azure-cost-factors', 'single_choice', 'Uma empresa esta comparando o custo de hospedar uma aplicacao em duas regioes diferentes do Azure e percebe que os precos de recursos semelhantes nao sao identicos entre essas regioes. Qual fator melhor explica essa diferenca de preco?', 'medium', 'Diferencas nos custos operacionais, impostos locais e infraestrutura entre diferentes regioes geograficas do Azure sao fatores que influenciam o preco final cobrado ao cliente, o que explica por que recursos semelhantes podem ter custos diferentes dependendo da regiao escolhida para hospeda-los.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 64),
  ('63000000-0000-4000-8000-000000000065', 'az-900', 'azure-cost-factors', 'single_choice', 'Uma empresa contrata uma maquina virtual com uma configuracao de alto desempenho, incluindo mais nucleos de processamento e memoria, em comparacao a uma configuracao basica que atenderia igualmente bem as necessidades da aplicacao. Qual impacto essa escolha provavelmente tera no custo mensal do servico?', 'medium', 'Escolher uma configuracao de maquina virtual com mais nucleos de processamento e memoria, quando uma configuracao basica atenderia igualmente bem as necessidades da aplicacao, provavelmente resultara em um aumento no custo mensal do servico, ja que o preco de recursos computacionais geralmente esta relacionado a sua capacidade e desempenho.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 65),
  ('63000000-0000-4000-8000-000000000066', 'az-900', 'azure-cost-factors', 'single_choice', 'Uma equipe de TI percebe que sua conta do Azure esta gerando custos elevados de transferencia de dados, apos identificar que uma aplicacao envia grandes volumes de dados de uma regiao do Azure diretamente para usuarios finais na internet. Qual fator de custo esta relacionado a esse cenario?', 'medium', 'O cenario descrito esta relacionado ao fator de custo de saida de dados (egress), que ocorre quando dados sao transferidos de uma regiao do Azure para a internet, geralmente gerando cobranca proporcional ao volume de dados efetivamente transferido para fora do Azure.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 66),
  ('63000000-0000-4000-8000-000000000067', 'az-900', 'azure-cost-factors', 'single_choice', 'Comparando o custo de manter recursos ativos continuamente 24 horas por dia versus utiliza-los apenas durante o horario comercial, com desligamento programado fora desse periodo, qual afirmacao esta correta?', 'medium', 'Manter recursos ativos apenas durante o horario comercial, com desligamento programado fora desse periodo, tende a reduzir o custo total em comparacao a mante-los ativos continuamente 24 horas por dia, ja que muitos recursos no Azure sao cobrados proporcionalmente ao tempo em que permanecem em execucao.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 67),
  ('63000000-0000-4000-8000-000000000068', 'az-900', 'azure-cost-factors', 'single_choice', 'Uma empresa sabe, com boa previsibilidade, que utilizara um determinado numero de maquinas virtuais continuamente pelos proximos tres anos, sem grande variacao nesse periodo. Qual fator de custo relacionado a compromissos de longo prazo pode ajudar a reduzir o custo total dessas maquinas virtuais em comparacao ao pagamento sob demanda?', 'medium', 'Para cargas de trabalho previsiveis de longo prazo, a utilizacao de instancias reservadas permite que a empresa se comprometa a utilizar uma determinada capacidade por um periodo predefinido, como um ou tres anos, em troca de um desconto significativo em relacao ao preco pago sob demanda.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 68),
  ('63000000-0000-4000-8000-000000000069', 'az-900', 'azure-cost-factors', 'single_choice', 'Uma empresa esta avaliando os fatores de custo de uma nova aplicacao que sera hospedada no Azure, considerando o tipo de recurso, a regiao escolhida, o volume esperado de transferencia de dados e o tempo de atividade necessario. Qual abordagem e mais adequada para estimar o custo total dessa aplicacao de forma realista?', 'hard', 'Analisar de forma combinada todos os fatores relevantes que influenciam o custo, como o tipo de recurso escolhido, a regiao geografica, o volume esperado de transferencia de dados e o tempo de atividade necessario, utilizando ferramentas de estimativa de custo disponibilizadas pelo Azure, e a abordagem mais adequada para obter uma projecao realista do custo total da aplicacao.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 69),
  ('63000000-0000-4000-8000-000000000070', 'az-900', 'azure-cost-factors', 'single_choice', 'Uma equipe de arquitetura esta comparando duas opcoes de design para uma nova aplicacao: a primeira concentra todos os componentes em uma unica regiao, com trafego interno minimo entre servicos; a segunda distribui os componentes entre multiplas regioes, o que gera trafego significativo de transferencia de dados entre elas. Qual analise e mais adequada para avaliar o impacto de custo dessas duas opcoes?', 'hard', 'E necessario avaliar o custo adicional de transferencia de dados entre regioes gerado pela segunda opcao, frente aos beneficios de resiliencia ou desempenho que a distribuicao geografica pode trazer, comparando esse cenario com a opcao mais simples e de menor trafego, que concentra os componentes em uma unica regiao, para tomar uma decisao de arquitetura financeiramente informada.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 70),
  ('63000000-0000-4000-8000-000000000071', 'az-900', 'azure-cost-management', 'single_choice', 'O que e o Azure Cost Management?', 'easy', 'O Azure Cost Management e um conjunto de ferramentas do Azure que permite monitorar, analisar e controlar os gastos com recursos da nuvem, oferecendo relatorios, orcamentos e alertas que ajudam as organizacoes a manter seus custos sob controle.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 71),
  ('63000000-0000-4000-8000-000000000072', 'az-900', 'azure-cost-management', 'single_choice', 'O que e um orcamento (budget) dentro do Azure Cost Management?', 'easy', 'Um orcamento (budget) dentro do Azure Cost Management e um limite de gastos definido pelo usuario para um periodo especifico, como um mes, que pode ser utilizado para monitorar despesas e disparar alertas automaticos quando os gastos se aproximam ou ultrapassam esse limite predefinido.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 72),
  ('63000000-0000-4000-8000-000000000073', 'az-900', 'azure-cost-management', 'single_choice', 'Qual e uma funcionalidade tipica oferecida pelo Azure Cost Management para ajudar na analise de gastos?', 'easy', 'Uma funcionalidade tipica do Azure Cost Management e a disponibilizacao de relatorios e paineis visuais que detalham os gastos por recurso, grupo de recursos, marca (tag) ou periodo especifico de tempo, ajudando as organizacoes a entender melhor onde seus recursos financeiros estao sendo consumidos.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 73),
  ('63000000-0000-4000-8000-000000000074', 'az-900', 'azure-cost-management', 'single_choice', 'Uma empresa quer ser notificada automaticamente sempre que os gastos mensais de uma assinatura do Azure ultrapassarem 80% do orcamento planejado, para que a equipe financeira possa agir antes que o limite total seja atingido. Qual funcionalidade do Azure Cost Management atende diretamente a essa necessidade?', 'medium', 'A criacao de um orcamento (budget) no Azure Cost Management, com um alerta configurado para disparar quando os gastos atingirem 80% do valor definido, permite que a equipe financeira seja notificada automaticamente antes que o limite total do orcamento seja atingido, possibilitando acoes preventivas.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 74),
  ('63000000-0000-4000-8000-000000000075', 'az-900', 'azure-cost-management', 'single_choice', 'Uma empresa possui diversos projetos hospedados na mesma assinatura do Azure e deseja entender quanto cada projeto especifico esta gastando individualmente, mesmo compartilhando a mesma assinatura. Qual pratica, relacionada ao Azure Cost Management, melhor atende a essa necessidade?', 'medium', 'Aplicar marcas (tags) consistentes, como o nome do projeto, nos recursos utilizados por cada projeto permite que a empresa filtre e analise os gastos por projeto diretamente nos relatorios do Azure Cost Management, mesmo que todos compartilhem a mesma assinatura do Azure.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 75),
  ('63000000-0000-4000-8000-000000000076', 'az-900', 'azure-cost-management', 'single_choice', 'Uma equipe financeira percebe, ao analisar os relatorios do Azure Cost Management, que um determinado grupo de recursos apresenta um custo muito acima do esperado em comparacao aos meses anteriores. Qual acao, utilizando as ferramentas do Azure Cost Management, ajuda a investigar a causa desse aumento?', 'medium', 'Utilizar os relatorios detalhados de analise de custos do Azure Cost Management para identificar quais recursos especificos dentro do grupo contribuiram para o aumento observado, comparando os gastos de periodos anteriores, e a acao mais adequada para investigar a causa raiz do aumento de custo identificado.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 76),
  ('63000000-0000-4000-8000-000000000077', 'az-900', 'azure-cost-management', 'single_choice', 'Comparando o uso de orcamentos (budgets) com alertas automaticos e a analise manual periodica de faturas do Azure, qual afirmacao esta correta sobre a deteccao de gastos inesperados?', 'medium', 'Orcamentos com alertas automaticos tendem a detectar gastos inesperados de forma mais rapida do que a analise manual periodica de faturas, ja que notificam a equipe automaticamente assim que um limite predefinido e atingido ou se aproxima, sem depender de uma revisao manual programada com menor frequencia.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 77),
  ('63000000-0000-4000-8000-000000000078', 'az-900', 'azure-cost-management', 'single_choice', 'Uma empresa com varios departamentos compartilhando a mesma assinatura do Azure deseja repassar internamente (fazer chargeback) os custos de nuvem para cada departamento, com base no uso real de cada um. Qual pratica, dentro do Azure Cost Management, viabiliza esse tipo de repasse interno de custos?', 'medium', 'Aplicar marcas (tags) consistentes que identifiquem o departamento responsavel em cada recurso permite que a empresa gere relatorios de custo segmentados por departamento diretamente no Azure Cost Management, viabilizando o repasse interno (chargeback) dos custos com base no uso real de cada area.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 78),
  ('63000000-0000-4000-8000-000000000079', 'az-900', 'azure-cost-management', 'single_choice', 'Uma empresa esta decidindo como estruturar seus orcamentos no Azure Cost Management: criar um unico orcamento global para toda a assinatura ou criar multiplos orcamentos menores, segmentados por grupo de recursos ou projeto. Qual analise e mais adequada para essa decisao?', 'hard', 'Para assinaturas com multiplos projetos ou grupos de recursos, estruturar multiplos orcamentos segmentados tende a oferecer maior visibilidade sobre os gastos, permitindo identificar mais rapidamente qual area especifica esta gerando gastos acima do esperado, em comparacao a depender de um unico orcamento global que agrega todos os custos da assinatura.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 79),
  ('63000000-0000-4000-8000-000000000080', 'az-900', 'azure-cost-management', 'single_choice', 'Uma organizacao configurou alertas de orcamento no Azure Cost Management, mas percebe que, mesmo apos varios meses recebendo alertas de que o limite foi ultrapassado, nenhuma acao concreta e tomada pela equipe responsavel, e os gastos continuam a crescer sem controle. Qual conclusao e mais adequada sobre essa situacao?', 'hard', 'O problema nao esta na ferramenta em si, que esta cumprindo corretamente sua funcao de notificar sobre o orcamento ultrapassado, mas sim na ausencia de um processo organizacional adequado que garanta que essas notificacoes de fato gerem acoes concretas por parte da equipe responsavel pelo controle financeiro dos recursos.', true, 'Microsoft Learn - Modulo ''Describe cost management in Azure'' (Percurso: Describe Azure management and governance, AZ-900)', 80),
  ('63000000-0000-4000-8000-000000000081', 'az-900', 'azure-datacenters', 'single_choice', 'O que e uma regiao (region) no contexto da infraestrutura do Azure?', 'easy', 'Uma regiao (region) no Azure e um conjunto de datacenters implantados dentro de um perimetro de latencia definido e conectados por uma rede dedicada de baixa latencia, oferecendo aos clientes a possibilidade de hospedar seus recursos proximos a seus usuarios finais.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 81),
  ('63000000-0000-4000-8000-000000000082', 'az-900', 'azure-datacenters', 'single_choice', 'O que sao zonas de disponibilidade (availability zones) dentro de uma regiao do Azure?', 'easy', 'Zonas de disponibilidade sao locais fisicos unicos e isolados dentro de uma regiao do Azure, cada um equipado com energia, refrigeracao e rede independentes, permitindo que aplicacoes sejam distribuidas entre elas para aumentar a resiliencia contra falhas localizadas em um unico datacenter.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 82),
  ('63000000-0000-4000-8000-000000000083', 'az-900', 'azure-datacenters', 'single_choice', 'O que e um par de regioes (region pair) no Azure?', 'easy', 'Um par de regioes (region pair) no Azure e a associacao entre duas regioes especificas, geralmente dentro da mesma geografia, definida previamente pela Microsoft, frequentemente utilizada para replicacao de dados e estrategias de recuperacao de desastres entre regioes.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 83),
  ('63000000-0000-4000-8000-000000000084', 'az-900', 'azure-datacenters', 'single_choice', 'Uma empresa deseja aumentar a resiliencia de sua aplicacao critica contra a falha de um unico datacenter, sem necessariamente distribuir a aplicacao entre regioes geograficas distantes. Qual conceito de infraestrutura do Azure atende diretamente a essa necessidade?', 'medium', 'A utilizacao de multiplas zonas de disponibilidade dentro da mesma regiao, distribuindo a aplicacao entre locais fisicos distintos com energia, refrigeracao e rede independentes, protege contra a falha de um unico datacenter, sem exigir a distribuicao da aplicacao entre regioes geograficas distantes.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 84),
  ('63000000-0000-4000-8000-000000000085', 'az-900', 'azure-datacenters', 'single_choice', 'Uma organizacao com operacoes na Europa precisa hospedar dados de clientes proximos a eles, atendendo a requisitos de latencia e, possivelmente, de residencia de dados. Qual decisao de infraestrutura do Azure e mais relevante para atender a essa necessidade?', 'medium', 'A escolha cuidadosa da regiao do Azure onde os recursos serao hospedados, considerando a proximidade geografica com os clientes europeus, e a decisao de infraestrutura mais relevante para atender a requisitos de latencia reduzida e, dependendo do caso, de residencia de dados dentro de uma determinada geografia.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 85),
  ('63000000-0000-4000-8000-000000000086', 'az-900', 'azure-datacenters', 'single_choice', 'Uma empresa esta projetando uma estrategia de recuperacao de desastres para sua aplicacao critica, desejando que, em caso de uma falha catastrofica que afete toda uma regiao do Azure, seus dados possam ser recuperados a partir de outra regiao geograficamente distante. Qual conceito do Azure e mais relevante para essa estrategia?', 'medium', 'O uso de pares de regioes (region pairs), que associam duas regioes distintas geralmente dentro da mesma geografia, e o conceito mais relevante para uma estrategia de recuperacao de desastres, permitindo replicar dados entre regioes distantes o suficiente para que uma falha catastrofica em uma regiao nao afete a outra.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 86),
  ('63000000-0000-4000-8000-000000000087', 'az-900', 'azure-datacenters', 'single_choice', 'Comparando a distribuicao de uma aplicacao entre multiplas zonas de disponibilidade dentro de uma unica regiao com a distribuicao entre multiplas regioes geograficas distintas, qual afirmacao esta correta em relacao ao tipo de protecao oferecida?', 'medium', 'A distribuicao entre zonas de disponibilidade dentro de uma unica regiao protege principalmente contra falhas localizadas em um unico datacenter, enquanto a distribuicao entre multiplas regioes geograficas distintas oferece um nivel adicional de protecao, cobrindo tambem cenarios de falhas que afetem uma regiao inteira, como desastres naturais.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 87),
  ('63000000-0000-4000-8000-000000000088', 'az-900', 'azure-datacenters', 'single_choice', 'Uma empresa do setor publico precisa garantir que os dados de seus cidadaos permanecam armazenados dentro de uma geografia especifica, devido a exigencias legais de residencia de dados do pais em que opera. Qual decisao de infraestrutura do Azure e mais relevante para atender a essa exigencia?', 'medium', 'Para atender a exigencias legais de residencia de dados, a decisao de infraestrutura mais relevante e a escolha cuidadosa da regiao do Azure onde os recursos e dados serao hospedados, garantindo que essa regiao esteja localizada dentro da geografia exigida pela legislacao aplicavel ao setor publico do pais em questao.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 88),
  ('63000000-0000-4000-8000-000000000089', 'az-900', 'azure-datacenters', 'single_choice', 'Uma empresa esta projetando a arquitetura de uma aplicacao financeira critica e precisa decidir entre tres opcoes: hospedar em uma unica zona de disponibilidade, distribuir entre multiplas zonas de disponibilidade na mesma regiao, ou distribuir entre multiplas regioes geograficas distintas. Qual analise e mais adequada para essa decisao, considerando diferentes niveis de risco tolerados?', 'hard', 'A empresa deve avaliar cuidadosamente o nivel de risco que esta disposta a tolerar para sua aplicacao financeira critica: distribuir entre multiplas zonas de disponibilidade protege contra a falha de um unico datacenter, enquanto distribuir entre multiplas regioes geograficas protege tambem contra falhas regionais completas, sendo que cada abordagem envolve diferentes niveis de complexidade arquitetural e custo, que devem ser ponderados junto ao risco aceitavel.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 89),
  ('63000000-0000-4000-8000-000000000090', 'az-900', 'azure-datacenters', 'single_choice', 'Uma equipe de arquitetura decide distribuir uma aplicacao entre duas regioes que nao formam um par de regioes (region pair) oficial definido pela Microsoft, por acreditar que a escolha geografica e mais conveniente para seus usuarios finais. Qual consideracao e mais relevante para essa equipe avaliar antes de finalizar essa decisao?', 'hard', 'Antes de finalizar a decisao, a equipe deve verificar se determinados recursos e garantias de recuperacao de desastres, tipicamente associados aos pares de regioes oficiais definidos pela Microsoft, estarao disponiveis ou nao para a combinacao especifica de regioes escolhida, avaliando se essa escolha atende adequadamente aos requisitos de resiliencia da aplicacao.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 90),
  ('63000000-0000-4000-8000-000000000091', 'az-900', 'azure-dns', 'single_choice', 'O que e o Azure DNS?', 'easy', 'O Azure DNS e um servico de hospedagem de dominios que permite hospedar e gerenciar registros DNS utilizando a infraestrutura global do Azure, traduzindo nomes de dominio amigaveis, como exemplo.com, em enderecos IP compreendidos pelos computadores.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure DNS'' (AZ-900)', 91),
  ('63000000-0000-4000-8000-000000000092', 'az-900', 'azure-dns', 'single_choice', 'Qual e a funcao basica de um sistema DNS, incluindo o Azure DNS?', 'easy', 'A funcao basica de um sistema DNS, incluindo o Azure DNS, e traduzir nomes de dominio amigaveis, como exemplo.com, em enderecos IP numericos que os computadores utilizam para se localizar e se comunicar na rede, tornando mais facil para pessoas acessarem sites e servicos por nomes memoraveis.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure DNS'' (AZ-900)', 92),
  ('63000000-0000-4000-8000-000000000093', 'az-900', 'azure-dns', 'single_choice', 'Qual e um beneficio de utilizar o Azure DNS para hospedar os registros de dominio de uma organizacao?', 'easy', 'Um beneficio de utilizar o Azure DNS e a possibilidade de gerenciar os registros DNS de um dominio utilizando as mesmas ferramentas, credenciais de acesso e faturamento ja utilizados para outros recursos do Azure, integrando a gestao de DNS ao restante da infraestrutura em nuvem da organizacao.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure DNS'' (AZ-900)', 93),
  ('63000000-0000-4000-8000-000000000094', 'az-900', 'azure-dns', 'single_choice', 'Uma empresa esta migrando seu site institucional para o Azure e deseja que o nome de dominio da empresa, como www.exemplo.com, continue direcionando os visitantes corretamente para o novo endereco IP da aplicacao hospedada no Azure. Qual servico e mais adequado para gerenciar essa configuracao de dominio?', 'medium', 'O Azure DNS e o servico mais adequado para gerenciar essa configuracao, pois permite hospedar e administrar os registros DNS do dominio da empresa, garantindo que o nome amigavel do site, como www.exemplo.com, direcione corretamente os visitantes para o endereco IP da aplicacao hospedada no Azure.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure DNS'' (AZ-900)', 94),
  ('63000000-0000-4000-8000-000000000095', 'az-900', 'azure-dns', 'single_choice', 'Uma empresa possui multiplos subdominios, como blog.exemplo.com e loja.exemplo.com, que precisam apontar para diferentes servicos hospedados no Azure. Qual pratica, utilizando o Azure DNS, permite gerenciar essa configuracao de forma organizada?', 'medium', 'Criar registros DNS especificos para cada subdominio, como blog.exemplo.com e loja.exemplo.com, dentro da mesma zona DNS gerenciada pelo Azure DNS, permite direcionar cada subdominio para o servico correspondente hospedado no Azure, mantendo a configuracao organizada e centralizada.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure DNS'' (AZ-900)', 95),
  ('63000000-0000-4000-8000-000000000096', 'az-900', 'azure-dns', 'single_choice', 'Uma equipe de TI percebe que, apos alterar o endereco IP de uma aplicacao hospedada no Azure, alguns usuarios ainda estao sendo direcionados temporariamente para o endereco IP antigo. Qual conceito relacionado ao DNS melhor explica esse comportamento temporario?', 'medium', 'O tempo de vida (TTL, ou Time To Live) dos registros DNS define por quanto tempo um registro pode permanecer armazenado em cache por sistemas e provedores de internet ao longo do caminho, o que explica por que alguns usuarios podem continuar sendo temporariamente direcionados para o endereco IP antigo ate que esse cache expire e seja atualizado.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure DNS'' (AZ-900)', 96),
  ('63000000-0000-4000-8000-000000000097', 'az-900', 'azure-dns', 'single_choice', 'Comparando o uso do Azure DNS com o uso de um provedor de DNS externo, independente do Azure, para hospedar os registros de dominio de uma aplicacao hospedada no Azure, qual afirmacao esta correta?', 'medium', 'Utilizar o Azure DNS pode oferecer maior integracao com outras ferramentas e recursos do Azure, como faturamento unificado e controle de acesso baseado nas mesmas politicas de identidade utilizadas para outros recursos, em comparacao a depender de um provedor de DNS completamente externo e desconectado do ecossistema do Azure.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure DNS'' (AZ-900)', 97),
  ('63000000-0000-4000-8000-000000000098', 'az-900', 'azure-dns', 'single_choice', 'Uma empresa precisa comprovar, perante um servico externo, que e realmente proprietaria de um determinado dominio, antes de poder utilizar certos recursos vinculados a esse dominio. Qual tipo de configuracao, feita no Azure DNS, e comumente utilizada para esse tipo de verificacao de propriedade de dominio?', 'medium', 'A criacao de um registro DNS do tipo TXT, contendo um valor especifico fornecido pelo servico externo que exige a verificacao, e uma pratica comum para comprovar que a empresa realmente controla o dominio em questao, sendo amplamente utilizada por diversos servicos que exigem esse tipo de validacao.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure DNS'' (AZ-900)', 98),
  ('63000000-0000-4000-8000-000000000099', 'az-900', 'azure-dns', 'single_choice', 'Uma empresa esta migrando seus registros DNS de um provedor externo para o Azure DNS, mas precisa garantir que essa transicao ocorra sem causar indisponibilidade para os usuarios que acessam seus servicos online. Qual estrategia e mais adequada para essa migracao?', 'hard', 'Planejar a migracao considerando o tempo de vida (TTL) dos registros DNS existentes, reduzindo-o previamente para acelerar a propagacao das mudancas, e validando cuidadosamente os novos registros no Azure DNS antes de finalizar a transicao, e a estrategia mais adequada para minimizar o risco de indisponibilidade durante a migracao entre provedores.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure DNS'' (AZ-900)', 99),
  ('63000000-0000-4000-8000-000000000100', 'az-900', 'azure-dns', 'single_choice', 'Uma organizacao percebe que, apos configurar incorretamente um registro DNS no Azure DNS, uma parte significativa dos usuarios ficou impossibilitada de acessar seu site por varias horas, mesmo apos a correcao imediata do erro. Qual fator, relacionado ao funcionamento do DNS, melhor explica a persistencia do problema mesmo apos a correcao?', 'hard', 'O tempo de vida (TTL) configurado previamente para o registro DNS incorreto pode ter feito com que sistemas, navegadores e provedores de internet ao longo do caminho mantivessem em cache a informacao incorreta por um determinado periodo, mesmo apos a correcao ser aplicada corretamente no Azure DNS, explicando a persistencia temporaria do problema para parte dos usuarios.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure DNS'' (AZ-900)', 100),
  ('63000000-0000-4000-8000-000000000101', 'az-900', 'azure-files', 'single_choice', 'O que e o Azure Files?', 'easy', 'O Azure Files e um servico de compartilhamento de arquivos totalmente gerenciado, hospedado na nuvem, que pode ser acessado por meio do protocolo SMB, entre outros, permitindo que multiplas maquinas, sejam elas na nuvem ou on-premises, acessem os mesmos arquivos simultaneamente.', true, 'Microsoft Learn - Modulo ''Describe Azure storage services'' (Percurso: Describe core Azure services, AZ-900)', 101),
  ('63000000-0000-4000-8000-000000000102', 'az-900', 'azure-files', 'single_choice', 'Qual protocolo e comumente utilizado para acessar compartilhamentos de arquivos criados no Azure Files?', 'easy', 'O Azure Files utiliza o protocolo SMB (Server Message Block), amplamente conhecido e compativel com sistemas operacionais Windows, Linux e macOS, para permitir que diferentes maquinas acessem os compartilhamentos de arquivos hospedados na nuvem, alem de outros protocolos suportados dependendo do cenario.', true, 'Microsoft Learn - Modulo ''Describe Azure storage services'' (Percurso: Describe core Azure services, AZ-900)', 102),
  ('63000000-0000-4000-8000-000000000103', 'az-900', 'azure-files', 'single_choice', 'Qual e um cenario tipico de uso do Azure Files em uma organizacao?', 'easy', 'Um cenario tipico de uso do Azure Files e compartilhar arquivos entre multiplas maquinas virtuais ou servidores on-premises, substituindo servidores de arquivos tradicionais mantidos localmente, com a vantagem de ser um servico totalmente gerenciado na nuvem, sem necessidade de manter hardware fisico dedicado.', true, 'Microsoft Learn - Modulo ''Describe Azure storage services'' (Percurso: Describe core Azure services, AZ-900)', 103),
  ('63000000-0000-4000-8000-000000000104', 'az-900', 'azure-files', 'single_choice', 'Uma empresa possui um servidor de arquivos tradicional local, que armazena documentos compartilhados entre os funcionarios de diferentes departamentos, e deseja migrar essa funcionalidade para a nuvem, mantendo a compatibilidade com o protocolo de compartilhamento ja utilizado pelos computadores dos funcionarios. Qual servico do Azure atende diretamente a essa necessidade?', 'medium', 'O Azure Files atende diretamente a essa necessidade, pois oferece um servico de compartilhamento de arquivos totalmente gerenciado na nuvem, compativel com o protocolo SMB amplamente utilizado por sistemas operacionais tradicionais, permitindo migrar a funcionalidade de um servidor de arquivos local sem grandes alteracoes na forma como os funcionarios acessam os documentos.', true, 'Microsoft Learn - Modulo ''Describe Azure storage services'' (Percurso: Describe core Azure services, AZ-900)', 104),
  ('63000000-0000-4000-8000-000000000105', 'az-900', 'azure-files', 'single_choice', 'Uma equipe de desenvolvimento distribuida em diferentes cidades precisa acessar os mesmos arquivos de configuracao compartilhados a partir de suas maquinas virtuais hospedadas no Azure, garantindo que todas as maquinas enxerguem exatamente a mesma versao atualizada dos arquivos. Qual abordagem, utilizando Azure Files, atende a essa necessidade?', 'medium', 'Criar um compartilhamento de arquivos no Azure Files e montar esse compartilhamento em todas as maquinas virtuais que precisam acessar os arquivos de configuracao garante que todas as maquinas enxerguem a mesma versao atualizada dos arquivos, funcionando como uma unica fonte de verdade centralizada, evitando inconsistencias entre copias locais.', true, 'Microsoft Learn - Modulo ''Describe Azure storage services'' (Percurso: Describe core Azure services, AZ-900)', 105),
  ('63000000-0000-4000-8000-000000000106', 'az-900', 'azure-files', 'single_choice', 'Uma empresa deseja reduzir a dependencia de servidores de arquivos fisicos mantidos em seu proprio datacenter, que exigem manutencao de hardware, backups manuais e atualizacoes de sistema operacional. Qual beneficio do Azure Files e mais relevante para essa necessidade especifica?', 'medium', 'Como o Azure Files e um servico totalmente gerenciado pela Microsoft, a empresa elimina a necessidade de gerenciar a infraestrutura fisica subjacente, incluindo manutencao de hardware, backups manuais e atualizacoes de sistema operacional, que antes eram necessarios para manter servidores de arquivos tradicionais em seu proprio datacenter.', true, 'Microsoft Learn - Modulo ''Describe Azure storage services'' (Percurso: Describe core Azure services, AZ-900)', 106),
  ('63000000-0000-4000-8000-000000000107', 'az-900', 'azure-files', 'single_choice', 'Comparando o Azure Files com um disco gerenciado (managed disk) anexado a uma unica maquina virtual, qual afirmacao esta correta em relacao ao compartilhamento simultaneo de arquivos entre multiplas maquinas?', 'medium', 'O Azure Files foi projetado especificamente para permitir que multiplas maquinas, sejam elas virtuais no Azure ou fisicas on-premises, acessem e compartilhem os mesmos arquivos simultaneamente, o que geralmente nao e o comportamento padrao de um disco gerenciado (managed disk) tradicional, tipicamente anexado a uma unica maquina virtual por vez.', true, 'Microsoft Learn - Modulo ''Describe Azure storage services'' (Percurso: Describe core Azure services, AZ-900)', 107),
  ('63000000-0000-4000-8000-000000000108', 'az-900', 'azure-files', 'single_choice', 'Uma empresa deseja garantir que os arquivos armazenados em seus compartilhamentos do Azure Files sejam protegidos contra exclusao acidental ou corrupcao, com a possibilidade de restaurar versoes anteriores dos arquivos quando necessario. Qual servico complementar do Azure atende diretamente a essa necessidade?', 'medium', 'O Azure Backup pode ser configurado para realizar copias de seguranca periodicas dos compartilhamentos do Azure Files, permitindo que a empresa restaure versoes anteriores dos arquivos em caso de exclusao acidental ou corrupcao, complementando a protecao oferecida pelo proprio servico de armazenamento.', true, 'Microsoft Learn - Modulo ''Describe Azure storage services'' (Percurso: Describe core Azure services, AZ-900)', 108),
  ('63000000-0000-4000-8000-000000000109', 'az-900', 'azure-files', 'single_choice', 'Uma empresa esta avaliando se deve migrar seu servidor de arquivos on-premises completamente para o Azure Files ou adotar uma abordagem hibrida, mantendo um cache local sincronizado com o Azure Files para os arquivos mais acessados, visando reduzir a latencia percebida pelos funcionarios em um escritorio com conexao de internet limitada. Qual analise e mais adequada para essa decisao?', 'hard', 'Diante de uma conexao de internet limitada no escritorio, a empresa deve considerar uma abordagem hibrida, com cache local sincronizado com o Azure Files para os arquivos mais acessados, avaliando cuidadosamente o equilibrio entre a simplicidade de uma migracao completa para a nuvem e o desempenho percebido pelos funcionarios ao acessar arquivos frequentemente utilizados no dia a dia.', true, 'Microsoft Learn - Modulo ''Describe Azure storage services'' (Percurso: Describe core Azure services, AZ-900)', 109),
  ('63000000-0000-4000-8000-000000000110', 'az-900', 'azure-files', 'single_choice', 'Uma organizacao percebe que, apos migrar seu servidor de arquivos para o Azure Files, alguns aplicativos legados internos, que dependem de recursos muito especificos de um sistema de arquivos local tradicional, apresentam comportamento inconsistente ao acessar os arquivos compartilhados. Qual conclusao e mais adequada sobre essa situacao?', 'hard', 'E possivel que determinados aplicativos legados, dependentes de recursos muito especificos de sistemas de arquivos locais tradicionais, exijam uma avaliacao cuidadosa de compatibilidade antes de uma migracao completa para o Azure Files, podendo necessitar de ajustes na aplicacao ou de uma abordagem alternativa, como manter esses casos especificos em um ambiente local, enquanto o restante da organizacao se beneficia da migracao.', true, 'Microsoft Learn - Modulo ''Describe Azure storage services'' (Percurso: Describe core Azure services, AZ-900)', 110),
  ('63000000-0000-4000-8000-000000000111', 'az-900', 'azure-functions', 'single_choice', 'O que e o Azure Functions?', 'easy', 'O Azure Functions e um servico de computacao serverless do Azure que permite executar pequenos trechos de codigo, chamados de funcoes, em resposta a eventos especificos, como uma requisicao HTTP ou a chegada de uma mensagem em uma fila, sem que o desenvolvedor precise provisionar ou gerenciar servidores.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure Functions'' (AZ-900)', 111),
  ('63000000-0000-4000-8000-000000000112', 'az-900', 'azure-functions', 'single_choice', 'Como o Azure Functions costuma cobrar pelo uso de seus recursos, em um dos modelos de plano mais comuns?', 'easy', 'No modelo de consumo, um dos planos mais comuns do Azure Functions, a cobranca e baseada na execucao real das funcoes, considerando fatores como o numero de execucoes, o tempo de processamento e a quantidade de memoria utilizada durante cada execucao.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure Functions'' (AZ-900)', 112),
  ('63000000-0000-4000-8000-000000000113', 'az-900', 'azure-functions', 'single_choice', 'Qual e um exemplo tipico de gatilho (trigger) que pode acionar a execucao de uma funcao no Azure Functions?', 'easy', 'Exemplos tipicos de gatilhos (triggers) que podem acionar a execucao de uma funcao no Azure Functions incluem uma requisicao HTTP recebida, a chegada de uma nova mensagem em uma fila de mensagens ou a adicao de um novo arquivo em um servico de armazenamento, entre diversos outros tipos de eventos suportados.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure Functions'' (AZ-900)', 113),
  ('63000000-0000-4000-8000-000000000114', 'az-900', 'azure-functions', 'single_choice', 'Uma empresa precisa processar imagens enviadas por usuarios apenas no momento em que um novo arquivo e adicionado a um servico de armazenamento, sem previsao de horarios fixos e com longos periodos sem qualquer novo envio. Qual abordagem, utilizando Azure Functions, atende diretamente a essa necessidade?', 'medium', 'Criar uma funcao no Azure Functions configurada com um gatilho de armazenamento, que e acionada automaticamente sempre que um novo arquivo e adicionado ao servico de armazenamento, permite processar as imagens apenas no momento em que elas sao efetivamente enviadas, sem necessidade de manter recursos ativos continuamente durante os longos periodos sem novos envios.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure Functions'' (AZ-900)', 114),
  ('63000000-0000-4000-8000-000000000115', 'az-900', 'azure-functions', 'single_choice', 'Uma equipe de desenvolvimento quer criar um pequeno endpoint de API que respondera a requisicoes HTTP ocasionais, sem previsao de trafego constante, evitando a complexidade de gerenciar servidores ou maquinas virtuais dedicadas para essa finalidade especifica. Qual abordagem e mais adequada para essa necessidade?', 'medium', 'Utilizar o Azure Functions com um gatilho HTTP permite que o codigo do endpoint seja executado automaticamente em resposta as requisicoes recebidas, sem a necessidade de provisionar ou gerenciar servidores dedicados, sendo uma abordagem adequada para cenarios de trafego ocasional e imprevisivel, como o descrito.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure Functions'' (AZ-900)', 115),
  ('63000000-0000-4000-8000-000000000116', 'az-900', 'azure-functions', 'single_choice', 'Uma aplicacao composta por diversas funcoes independentes no Azure Functions precisa compartilhar algumas configuracoes comuns, como cadeias de conexao com bancos de dados, entre todas as funcoes que fazem parte do mesmo aplicativo de funcoes (function app). Qual pratica e mais adequada para gerenciar essas configuracoes compartilhadas?', 'medium', 'Utilizar as configuracoes de aplicativo (application settings) do aplicativo de funcoes (function app), definidas de forma centralizada, permite que todas as funcoes que fazem parte do mesmo aplicativo acessem as mesmas configuracoes compartilhadas, como cadeias de conexao com bancos de dados, de forma consistente e facil de manter.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure Functions'' (AZ-900)', 116),
  ('63000000-0000-4000-8000-000000000117', 'az-900', 'azure-functions', 'single_choice', 'Comparando o Azure Functions com o uso de uma maquina virtual dedicada para executar uma pequena rotina de processamento que roda apenas poucas vezes por dia, qual afirmacao esta correta em relacao ao custo esperado?', 'medium', 'Para uma rotina que executa apenas poucas vezes por dia, o Azure Functions, no modelo de consumo, tende a ser mais economico, ja que a cobranca esta associada a execucao real da funcao, enquanto uma maquina virtual dedicada geralmente gera custo continuo, mesmo durante os longos periodos em que permanece ociosa entre as execucoes da rotina.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure Functions'' (AZ-900)', 117),
  ('63000000-0000-4000-8000-000000000118', 'az-900', 'azure-functions', 'single_choice', 'Uma empresa possui uma funcao critica no Azure Functions que precisa responder rapidamente a cada requisicao, sem apresentar atrasos perceptiveis causados pelo tempo de inicializacao de uma instancia que estava ociosa (conhecido como ''cold start''). Qual opcao de hospedagem do Azure Functions e mais adequada para reduzir esse tipo de atraso?', 'medium', 'O plano Premium do Azure Functions mantem instancias pre-aquecidas e prontas para responder as requisicoes, reduzindo significativamente o impacto do tempo de inicializacao (cold start) que pode ocorrer no plano de consumo padrao quando uma instancia esteve ociosa, sendo mais adequado para cenarios que exigem baixa latencia constante.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure Functions'' (AZ-900)', 118),
  ('63000000-0000-4000-8000-000000000119', 'az-900', 'azure-functions', 'single_choice', 'Uma equipe esta avaliando se deve utilizar o Azure Functions para uma carga de trabalho que precisa processar continuamente grandes volumes de dados, 24 horas por dia, com utilizacao consistente e previsivel de recursos computacionais. Qual analise e mais adequada para essa decisao?', 'hard', 'Para uma carga de trabalho que precisa processar continuamente grandes volumes de dados, com utilizacao consistente e previsivel 24 horas por dia, o custo do Azure Functions no modelo de consumo pode ser proporcionalmente maior do que o de outras opcoes de computo dimensionadas especificamente para uso continuo, tornando essencial comparar o custo total de cada abordagem antes de decidir.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure Functions'' (AZ-900)', 119),
  ('63000000-0000-4000-8000-000000000120', 'az-900', 'azure-functions', 'single_choice', 'Uma equipe de engenharia esta migrando uma arquitetura monolitica para um conjunto de pequenas funcoes independentes no Azure Functions, cada uma responsavel por uma tarefa especifica, como validacao de dados, envio de notificacoes e geracao de relatorios, acionadas por diferentes tipos de eventos. Qual beneficio arquitetural essa abordagem, baseada em Azure Functions, tende a proporcionar?', 'hard', 'A abordagem baseada em pequenas funcoes independentes no Azure Functions tende a proporcionar a possibilidade de desenvolver, implantar e escalar cada funcao de forma independente, conforme a demanda especifica de cada tarefa, como validacao de dados ou envio de notificacoes, alem de facilitar a manutencao isolada de cada componente, sem a necessidade de reimplantar todo o sistema monolitico a cada alteracao pontual.', true, 'Microsoft Learn - Modulo ''Describe Azure compute and networking services'' - unidade ''Azure Functions'' (AZ-900)', 120);

insert into imported_question_option_batch2_seed (
  id, question_id, option_text, is_correct, explanation, display_order
)
values
  ('74000000-0000-4000-8000-000000000001', '63000000-0000-4000-8000-000000000001', 'Um recurso do Azure Monitor voltado ao monitoramento de desempenho e disponibilidade de aplicacoes, coletando telemetria em tempo real.', true, 'Correta. Application Insights e um recurso de gerenciamento de desempenho de aplicacoes (APM) dentro do Azure Monitor, focado em monitorar aplicacoes em execucao.', 1),
  ('74000000-0000-4000-8000-000000000002', '63000000-0000-4000-8000-000000000001', 'Um servico de armazenamento de arquivos utilizado para backup de bancos de dados relacionais.', false, 'Incorreta. Armazenamento de arquivos para backup e funcao do Azure Files ou de servicos de backup, nao do Application Insights.', 2),
  ('74000000-0000-4000-8000-000000000003', '63000000-0000-4000-8000-000000000001', 'Uma ferramenta de linha de comando para gerenciar recursos do Azure.', false, 'Incorreta. Ferramentas de linha de comando, como Azure CLI, sao diferentes do Application Insights, que e um servico de monitoramento.', 3),
  ('74000000-0000-4000-8000-000000000004', '63000000-0000-4000-8000-000000000001', 'Um servico exclusivo para gerenciamento de identidades de usuarios corporativos.', false, 'Incorreta. Gerenciamento de identidades e funcao do Microsoft Entra ID, nao do Application Insights.', 4),
  ('74000000-0000-4000-8000-000000000005', '63000000-0000-4000-8000-000000000002', 'Apenas o numero de licencas de software instaladas nos servidores da empresa.', false, 'Incorreta. Licencas de software instaladas nao sao um tipo de telemetria coletado pelo Application Insights.', 1),
  ('74000000-0000-4000-8000-000000000006', '63000000-0000-4000-8000-000000000002', 'Telemetria como taxas de requisicao, tempos de resposta, taxas de excecao e dependencias externas da aplicacao.', true, 'Correta. O Application Insights coleta telemetria detalhada sobre o comportamento da aplicacao, incluindo requisicoes, desempenho e falhas.', 2),
  ('74000000-0000-4000-8000-000000000007', '63000000-0000-4000-8000-000000000002', 'Exclusivamente informacoes sobre a folha de pagamento dos funcionarios da equipe de desenvolvimento.', false, 'Incorreta. Informacoes de folha de pagamento nao tem relacao com a telemetria coletada por ferramentas de monitoramento de aplicacoes.', 3),
  ('74000000-0000-4000-8000-000000000008', '63000000-0000-4000-8000-000000000002', 'Apenas o layout visual das telas do aplicativo, sem qualquer dado de desempenho.', false, 'Incorreta. O foco do Application Insights e em dados de desempenho e comportamento, nao no layout visual das telas.', 4),
  ('74000000-0000-4000-8000-000000000009', '63000000-0000-4000-8000-000000000003', 'Exclusivamente por meio da compra de um servidor fisico dedicado ao monitoramento.', false, 'Incorreta. Nao e necessario comprar servidor fisico dedicado; a habilitacao ocorre por meio de instrumentacao de software.', 1),
  ('74000000-0000-4000-8000-000000000010', '63000000-0000-4000-8000-000000000003', 'Apenas trocando o sistema operacional dos servidores que hospedam a aplicacao.', false, 'Incorreta. Trocar o sistema operacional dos servidores nao tem relacao com a habilitacao do Application Insights.', 2),
  ('74000000-0000-4000-8000-000000000011', '63000000-0000-4000-8000-000000000003', 'Por meio de instrumentacao via SDK no codigo da aplicacao ou de auto-instrumentacao, sem necessidade de alterar significativamente o codigo em varias linguagens suportadas.', true, 'Correta. O Application Insights pode ser habilitado por instrumentacao via SDK ou por auto-instrumentacao, dependendo da linguagem e do ambiente de hospedagem.', 3),
  ('74000000-0000-4000-8000-000000000012', '63000000-0000-4000-8000-000000000003', 'Contratando exclusivamente uma equipe terceirizada para reescrever toda a aplicacao do zero.', false, 'Incorreta. Reescrever a aplicacao do zero nao e necessario nem e a forma padrao de habilitar o Application Insights.', 4),
  ('74000000-0000-4000-8000-000000000013', '63000000-0000-4000-8000-000000000004', 'Aguardar reclamacoes dos clientes por e-mail e so entao investigar manualmente os logs do servidor.', false, 'Incorreta. Aguardar reclamacoes e uma abordagem reativa, que nao permite identificar problemas antes que afetem os clientes.', 1),
  ('74000000-0000-4000-8000-000000000014', '63000000-0000-4000-8000-000000000004', 'Desativar completamente qualquer tipo de monitoramento para reduzir custos operacionais.', false, 'Incorreta. Desativar o monitoramento impediria justamente a deteccao proativa de problemas de desempenho.', 2),
  ('74000000-0000-4000-8000-000000000015', '63000000-0000-4000-8000-000000000004', 'Revisar manualmente o codigo-fonte da aplicacao uma vez por ano, sem qualquer telemetria em tempo real.', false, 'Incorreta. Uma revisao anual de codigo, sem telemetria em tempo real, nao permite identificar problemas de desempenho de forma proativa.', 3),
  ('74000000-0000-4000-8000-000000000016', '63000000-0000-4000-8000-000000000004', 'Configurar o Application Insights para coletar telemetria continuamente e criar alertas automaticos baseados em metricas de desempenho, como tempo de resposta elevado.', true, 'Correta. Configurar telemetria continua e alertas automaticos permite identificar problemas de desempenho antes que afetem significativamente os clientes.', 4),
  ('74000000-0000-4000-8000-000000000017', '63000000-0000-4000-8000-000000000005', 'O rastreamento de eventos personalizados e funis de usuario, que permitem registrar acoes especificas e analisar o comportamento ao longo da jornada do usuario.', true, 'Correta. O rastreamento de eventos personalizados e funis permite analisar como os usuarios interagem com a aplicacao e onde ocorrem abandonos no fluxo.', 1),
  ('74000000-0000-4000-8000-000000000018', '63000000-0000-4000-8000-000000000005', 'A configuracao de backup automatico do banco de dados da aplicacao.', false, 'Incorreta. Backup automatico de banco de dados nao esta relacionado a analise de comportamento de navegacao dos usuarios.', 2),
  ('74000000-0000-4000-8000-000000000019', '63000000-0000-4000-8000-000000000005', 'A criacao de uma nova regiao geografica para hospedar a aplicacao.', false, 'Incorreta. Criar uma nova regiao geografica nao tem relacao com a analise do comportamento de navegacao dos usuarios.', 3),
  ('74000000-0000-4000-8000-000000000020', '63000000-0000-4000-8000-000000000005', 'A instalacao de um novo sistema operacional nos servidores que hospedam a aplicacao.', false, 'Incorreta. A instalacao de um sistema operacional nao esta relacionada a analise de comportamento de usuarios em uma aplicacao.', 4),
  ('74000000-0000-4000-8000-000000000021', '63000000-0000-4000-8000-000000000006', 'A funcionalidade de backup manual dos arquivos de configuracao de cada microsservico.', false, 'Incorreta. Backup manual de arquivos de configuracao nao ajuda a identificar gargalos entre componentes de uma arquitetura de microsservicos.', 1),
  ('74000000-0000-4000-8000-000000000022', '63000000-0000-4000-8000-000000000006', 'O Mapa de Aplicativos (Application Map), que exibe visualmente as dependencias entre os componentes da aplicacao e destaca pontos de lentidao ou falha.', true, 'Correta. O Mapa de Aplicativos exibe visualmente as dependencias entre componentes, ajudando a identificar rapidamente onde ocorrem gargalos de desempenho.', 2),
  ('74000000-0000-4000-8000-000000000023', '63000000-0000-4000-8000-000000000006', 'A criacao de novos grupos de recursos para cada microsservico da aplicacao.', false, 'Incorreta. Criar novos grupos de recursos e uma tarefa organizacional que nao ajuda a identificar gargalos de desempenho entre servicos.', 3),
  ('74000000-0000-4000-8000-000000000024', '63000000-0000-4000-8000-000000000006', 'A alteracao do nome de exibicao da aplicacao no portal do Azure.', false, 'Incorreta. Alterar o nome de exibicao da aplicacao no portal nao tem qualquer relacao com a identificacao de gargalos de desempenho.', 4),
  ('74000000-0000-4000-8000-000000000025', '63000000-0000-4000-8000-000000000007', 'A criacao manual de um relatorio em planilha, atualizado uma vez por semana pela equipe.', false, 'Incorreta. Um relatorio manual e semanal nao oferece a notificacao automatica e em tempo real que a equipe precisa.', 1),
  ('74000000-0000-4000-8000-000000000026', '63000000-0000-4000-8000-000000000007', 'A remocao completa do Application Insights da aplicacao, simplificando a arquitetura.', false, 'Incorreta. Remover o Application Insights eliminaria justamente a capacidade de monitorar e alertar sobre problemas na aplicacao.', 2),
  ('74000000-0000-4000-8000-000000000027', '63000000-0000-4000-8000-000000000007', 'A configuracao de alertas baseados em metricas, que disparam notificacoes automaticas quando um limite predefinido, como a taxa de excecoes, e ultrapassado.', true, 'Correta. Alertas baseados em metricas notificam automaticamente a equipe quando um limite predefinido, como a taxa de excecoes, e ultrapassado.', 3),
  ('74000000-0000-4000-8000-000000000028', '63000000-0000-4000-8000-000000000007', 'A troca do provedor de nuvem utilizado pela aplicacao para outro fornecedor.', false, 'Incorreta. Trocar de provedor de nuvem nao resolve a necessidade especifica de notificacoes automaticas sobre taxas de excecao.', 4),
  ('74000000-0000-4000-8000-000000000029', '63000000-0000-4000-8000-000000000008', 'Application Insights e um produto totalmente independente, sem qualquer relacao com o Azure Monitor.', false, 'Incorreta. Application Insights nao e independente; ele e um recurso integrado ao Azure Monitor, e nao um produto separado.', 1),
  ('74000000-0000-4000-8000-000000000030', '63000000-0000-4000-8000-000000000008', 'Azure Monitor e um recurso especifico do Application Insights, voltado apenas ao monitoramento de rede.', false, 'Incorreta. A relacao e inversa: o Application Insights e um recurso dentro do Azure Monitor, e nao o contrario.', 2),
  ('74000000-0000-4000-8000-000000000031', '63000000-0000-4000-8000-000000000008', 'Os dois servicos sao identicos em funcionalidade, apenas com nomes comerciais diferentes.', false, 'Incorreta. Embora relacionados, os dois nao sao identicos; o Application Insights tem foco especifico em aplicacoes.', 3),
  ('74000000-0000-4000-8000-000000000032', '63000000-0000-4000-8000-000000000008', 'Application Insights e um recurso do Azure Monitor voltado especificamente ao monitoramento de aplicacoes, enquanto o Azure Monitor abrange um escopo mais amplo, incluindo infraestrutura e recursos de plataforma.', true, 'Correta. Application Insights e um recurso especializado do Azure Monitor, focado em aplicacoes, enquanto o Azure Monitor tem um escopo mais amplo.', 4),
  ('74000000-0000-4000-8000-000000000033', '63000000-0000-4000-8000-000000000009', 'Habilitar o Application Insights tambem em ambientes de teste e homologacao pode ajudar a identificar problemas de desempenho antes que a aplicacao chegue a producao, desde que a equipe considere o volume adicional de telemetria gerado.', true, 'Correta. Habilitar o monitoramento em ambientes de teste pode antecipar a deteccao de problemas, mas e importante considerar o volume de telemetria gerado.', 1),
  ('74000000-0000-4000-8000-000000000034', '63000000-0000-4000-8000-000000000009', 'O Application Insights so pode ser utilizado em ambientes de producao, sendo tecnicamente impossivel habilita-lo em outros ambientes.', false, 'Incorreta. Nao ha impedimento tecnico para habilitar o Application Insights em ambientes de teste ou homologacao, alem da producao.', 2),
  ('74000000-0000-4000-8000-000000000035', '63000000-0000-4000-8000-000000000009', 'Nao ha qualquer beneficio em monitorar ambientes de teste ou homologacao, pois problemas so podem ocorrer em producao.', false, 'Incorreta. Problemas de desempenho podem, sim, ser identificados em ambientes de teste e homologacao antes de afetarem a producao.', 3),
  ('74000000-0000-4000-8000-000000000036', '63000000-0000-4000-8000-000000000009', 'A decisao deve ser tomada exclusivamente com base na cor da interface do portal do Azure utilizada pela equipe.', false, 'Incorreta. Aspectos esteticos da interface do portal nao tem qualquer relacao com essa decisao tecnica de monitoramento.', 4),
  ('74000000-0000-4000-8000-000000000037', '63000000-0000-4000-8000-000000000010', 'Desativar completamente todos os alertas configurados, retornando a verificacao manual constante dos logs.', false, 'Incorreta. Desativar completamente os alertas eliminaria tambem a deteccao automatica de problemas realmente criticos.', 1),
  ('74000000-0000-4000-8000-000000000038', '63000000-0000-4000-8000-000000000010', 'Revisar e ajustar os criterios e limites dos alertas, filtrando erros esperados de baixo impacto e configurando notificacoes apenas para condicoes que realmente indiquem problemas criticos.', true, 'Correta. Ajustar os criterios e limites dos alertas permite reduzir ruido, filtrando erros de baixo impacto e focando em problemas realmente criticos.', 2),
  ('74000000-0000-4000-8000-000000000039', '63000000-0000-4000-8000-000000000010', 'Ignorar todas as notificacoes recebidas, assumindo que a maioria delas nao e relevante para a equipe.', false, 'Incorreta. Ignorar todas as notificacoes pode levar a equipe a nao perceber problemas criticos genuinos.', 3),
  ('74000000-0000-4000-8000-000000000040', '63000000-0000-4000-8000-000000000010', 'Trocar o Application Insights por um servico de armazenamento de arquivos, sem qualquer monitoramento ativo.', false, 'Incorreta. Um servico de armazenamento de arquivos nao substitui a funcao de monitoramento e alertas do Application Insights.', 4),
  ('74000000-0000-4000-8000-000000000041', '63000000-0000-4000-8000-000000000011', 'O processo de definir quais acoes um usuario ja autenticado pode realizar dentro de um sistema.', false, 'Incorreta. Definir quais acoes um usuario pode realizar descreve autorizacao, nao autenticacao.', 1),
  ('74000000-0000-4000-8000-000000000042', '63000000-0000-4000-8000-000000000011', 'O processo de criptografar todos os dados armazenados em um banco de dados na nuvem.', false, 'Incorreta. Criptografia de dados armazenados esta relacionada a protecao de dados, nao diretamente ao conceito de autenticacao.', 2),
  ('74000000-0000-4000-8000-000000000043', '63000000-0000-4000-8000-000000000011', 'O processo de verificar a identidade de um usuario ou sistema, confirmando que ele e realmente quem afirma ser.', true, 'Correta. Autenticacao e o processo de verificar a identidade de um usuario ou sistema, geralmente por meio de credenciais como senha ou biometria.', 3),
  ('74000000-0000-4000-8000-000000000044', '63000000-0000-4000-8000-000000000011', 'O processo de monitorar o desempenho de uma aplicacao ao longo do tempo.', false, 'Incorreta. Monitoramento de desempenho de aplicacoes e um conceito diferente, relacionado a ferramentas como o Application Insights.', 4),
  ('74000000-0000-4000-8000-000000000045', '63000000-0000-4000-8000-000000000012', 'O processo de verificar a identidade de um usuario por meio de senha ou biometria.', false, 'Incorreta. Verificar a identidade por meio de senha ou biometria descreve autenticacao, nao autorizacao.', 1),
  ('74000000-0000-4000-8000-000000000046', '63000000-0000-4000-8000-000000000012', 'O processo de criar uma nova conta de usuario em um sistema corporativo.', false, 'Incorreta. Criar uma nova conta de usuario e uma tarefa administrativa, diferente do conceito de autorizacao.', 2),
  ('74000000-0000-4000-8000-000000000047', '63000000-0000-4000-8000-000000000012', 'O processo de instalar atualizacoes de seguranca em servidores fisicos.', false, 'Incorreta. Instalar atualizacoes de seguranca em servidores fisicos nao esta relacionado ao conceito de autorizacao.', 3),
  ('74000000-0000-4000-8000-000000000048', '63000000-0000-4000-8000-000000000012', 'O processo de determinar quais recursos e acoes um usuario ja autenticado tem permissao para acessar ou realizar.', true, 'Correta. Autorizacao e o processo que determina quais recursos e acoes um usuario autenticado esta autorizado a acessar ou executar.', 4),
  ('74000000-0000-4000-8000-000000000049', '63000000-0000-4000-8000-000000000013', 'Primeiro ocorre a autenticacao, verificando a identidade do usuario; em seguida, ocorre a autorizacao, determinando o que esse usuario pode acessar.', true, 'Correta. O fluxo tipico envolve primeiro autenticar o usuario e, em seguida, autorizar o acesso a recursos especificos com base em suas permissoes.', 1),
  ('74000000-0000-4000-8000-000000000050', '63000000-0000-4000-8000-000000000013', 'Autorizacao sempre ocorre antes da autenticacao, sem excecoes.', false, 'Incorreta. A ordem tipica e inversa: primeiro ocorre a autenticacao, e somente depois a autorizacao.', 2),
  ('74000000-0000-4000-8000-000000000051', '63000000-0000-4000-8000-000000000013', 'Autenticacao e autorizacao ocorrem exatamente ao mesmo tempo, sendo indistinguiveis na pratica.', false, 'Incorreta. Embora relacionados, os dois processos sao distintos e geralmente ocorrem em etapas sequenciais.', 3),
  ('74000000-0000-4000-8000-000000000052', '63000000-0000-4000-8000-000000000013', 'Autenticacao e autorizacao sao termos sinonimos, referindo-se exatamente ao mesmo processo de seguranca.', false, 'Incorreta. Embora relacionados, autenticacao e autorizacao sao conceitos distintos, cada um com um proposito especifico.', 4),
  ('74000000-0000-4000-8000-000000000053', '63000000-0000-4000-8000-000000000014', 'Uma falha de autenticacao, pois o sistema nao reconheceu corretamente as credenciais do usuario.', false, 'Incorreta. O login foi realizado com sucesso, o que indica que a autenticacao funcionou corretamente nesse caso.', 1),
  ('74000000-0000-4000-8000-000000000054', '63000000-0000-4000-8000-000000000014', 'Uma falha de autorizacao, pois o usuario foi autenticado com sucesso, mas nao possui permissao para acessar aquele recurso especifico.', true, 'Correta. O usuario foi autenticado corretamente, mas a autorizacao para acessar o relatorio financeiro especifico nao foi concedida.', 2),
  ('74000000-0000-4000-8000-000000000055', '63000000-0000-4000-8000-000000000014', 'Um problema de conectividade de rede entre o usuario e o servidor da aplicacao.', false, 'Incorreta. O cenario descreve um problema de permissao apos login bem-sucedido, nao um problema de conectividade de rede.', 3),
  ('74000000-0000-4000-8000-000000000056', '63000000-0000-4000-8000-000000000014', 'Um erro de configuracao no certificado digital do servidor da aplicacao.', false, 'Incorreta. O cenario nao menciona qualquer problema relacionado a certificados digitais do servidor.', 4),
  ('74000000-0000-4000-8000-000000000057', '63000000-0000-4000-8000-000000000015', 'Autorizacao, pois a MFA determina quais recursos especificos o usuario podera acessar apos o login.', false, 'Incorreta. A MFA nao determina quais recursos o usuario pode acessar; essa e a funcao da autorizacao, nao da autenticacao multifator.', 1),
  ('74000000-0000-4000-8000-000000000058', '63000000-0000-4000-8000-000000000015', 'Nenhum dos dois conceitos, pois a MFA nao tem relacao com seguranca de identidade.', false, 'Incorreta. A MFA esta diretamente relacionada a seguranca de identidade, especificamente ao processo de autenticacao.', 2),
  ('74000000-0000-4000-8000-000000000059', '63000000-0000-4000-8000-000000000015', 'Autenticacao, pois a MFA adiciona uma camada extra de verificacao da identidade do usuario, alem da senha.', true, 'Correta. A autenticacao multifator reforca o processo de autenticacao, exigindo uma verificacao adicional da identidade do usuario.', 3),
  ('74000000-0000-4000-8000-000000000060', '63000000-0000-4000-8000-000000000015', 'Ambos os conceitos simultaneamente, sem qualquer distincao entre eles nesse caso especifico.', false, 'Incorreta. A MFA reforca especificamente a autenticacao, verificando a identidade, e nao diretamente a autorizacao de acesso a recursos.', 4),
  ('74000000-0000-4000-8000-000000000061', '63000000-0000-4000-8000-000000000016', 'Autenticacao, pois o foco esta na verificacao da identidade dos funcionarios do departamento financeiro.', false, 'Incorreta. O cenario nao trata da verificacao de identidade, mas sim de quais recursos usuarios ja autenticados podem acessar.', 1),
  ('74000000-0000-4000-8000-000000000062', '63000000-0000-4000-8000-000000000016', 'Criptografia de dados em repouso, pois os relatorios financeiros estao sendo protegidos por algoritmos criptograficos.', false, 'Incorreta. O cenario nao menciona criptografia de dados, mas sim controle de acesso baseado em permissoes.', 2),
  ('74000000-0000-4000-8000-000000000063', '63000000-0000-4000-8000-000000000016', 'Recuperacao de desastres, pois o objetivo e proteger os relatorios financeiros contra perda de dados.', false, 'Incorreta. O cenario nao trata de recuperacao de desastres, mas sim de controle de acesso a recursos especificos.', 3),
  ('74000000-0000-4000-8000-000000000064', '63000000-0000-4000-8000-000000000016', 'Autorizacao, pois o foco esta em definir quais usuarios, ja autenticados, tem permissao para acessar recursos especificos, como os relatorios financeiros.', true, 'Correta. O cenario descreve a definicao de permissoes de acesso a recursos especificos para usuarios ja autenticados, caracterizando autorizacao.', 4),
  ('74000000-0000-4000-8000-000000000065', '63000000-0000-4000-8000-000000000017', 'Definir permissoes de acesso baseadas em funcao (role-based access control), restringindo a visualizacao de dados de acordo com o departamento e o cargo de cada funcionario.', true, 'Correta. Definir permissoes baseadas em funcao restringe o acesso aos dados conforme o departamento e o cargo, corrigindo o excesso de acesso identificado.', 1),
  ('74000000-0000-4000-8000-000000000066', '63000000-0000-4000-8000-000000000017', 'Implementar autenticacao multifator para todos os funcionarios, sem alterar as permissoes de acesso aos dados.', false, 'Incorreta. A autenticacao multifator reforca a verificacao de identidade, mas nao resolve o problema de permissoes excessivas de acesso aos dados.', 2),
  ('74000000-0000-4000-8000-000000000067', '63000000-0000-4000-8000-000000000017', 'Trocar a senha de todos os funcionarios simultaneamente, sem qualquer alteracao nas permissoes de acesso.', false, 'Incorreta. Trocar senhas nao resolve o problema de permissoes excessivas de acesso a dados de outros departamentos.', 3),
  ('74000000-0000-4000-8000-000000000068', '63000000-0000-4000-8000-000000000017', 'Desativar completamente o login de todos os funcionarios, impedindo qualquer acesso a aplicacao.', false, 'Incorreta. Desativar o login de todos os funcionarios impediria o uso legitimo da aplicacao, nao sendo uma solucao adequada.', 4),
  ('74000000-0000-4000-8000-000000000069', '63000000-0000-4000-8000-000000000018', 'Autenticacao e autorizacao sao processos identicos, diferindo apenas no nome utilizado por diferentes fornecedores de nuvem.', false, 'Incorreta. Embora relacionados, autenticacao e autorizacao sao processos distintos, com propositos diferentes.', 1),
  ('74000000-0000-4000-8000-000000000070', '63000000-0000-4000-8000-000000000018', 'Autenticacao verifica quem o usuario e, enquanto autorizacao determina o que esse usuario tem permissao para fazer ou acessar.', true, 'Correta. Autenticacao verifica a identidade do usuario, enquanto autorizacao determina quais recursos e acoes esse usuario pode acessar.', 2),
  ('74000000-0000-4000-8000-000000000071', '63000000-0000-4000-8000-000000000018', 'Autenticacao determina o que o usuario pode fazer, enquanto autorizacao verifica quem o usuario e.', false, 'Incorreta. Essa e a inversao dos conceitos; autenticacao verifica identidade, e autorizacao determina permissoes de acesso.', 3),
  ('74000000-0000-4000-8000-000000000072', '63000000-0000-4000-8000-000000000018', 'Apenas a autorizacao e necessaria em sistemas modernos, tornando a autenticacao um conceito obsoleto.', false, 'Incorreta. Ambos os conceitos continuam sendo necessarios e complementares em sistemas modernos de seguranca.', 4),
  ('74000000-0000-4000-8000-000000000073', '63000000-0000-4000-8000-000000000019', 'O incidente ocorreu exclusivamente por uma falha na autenticacao multifator, sendo essa a unica causa relevante a ser investigada.', false, 'Incorreta. Embora a MFA parcial seja relevante, o acesso a sistemas indevidos tambem indica uma possivel falha nas politicas de autorizacao.', 1),
  ('74000000-0000-4000-8000-000000000074', '63000000-0000-4000-8000-000000000019', 'O incidente nao tem qualquer relacao com os conceitos de autenticacao ou autorizacao, sendo puramente um problema de rede.', false, 'Incorreta. O cenario descrito esta diretamente relacionado a falhas de autenticacao e autorizacao, e nao apenas a um problema de rede.', 2),
  ('74000000-0000-4000-8000-000000000075', '63000000-0000-4000-8000-000000000019', 'O incidente envolve tanto uma possivel fragilidade na autenticacao, dado que a MFA nao estava habilitada em todos os pontos, quanto uma possivel falha nas politicas de autorizacao, que permitiram acesso a sistemas alem do necessario para a funcao do funcionario.', true, 'Correta. O incidente envolve tanto fragilidades na autenticacao quanto possiveis falhas nas politicas de autorizacao, que permitiram acesso alem do necessario.', 3),
  ('74000000-0000-4000-8000-000000000076', '63000000-0000-4000-8000-000000000019', 'A unica solucao possivel para esse tipo de incidente e eliminar completamente o uso de senhas em toda a organizacao.', false, 'Incorreta. Eliminar completamente o uso de senhas nao e a unica solucao possivel; fortalecer MFA e revisar politicas de autorizacao tambem sao medidas relevantes.', 4),
  ('74000000-0000-4000-8000-000000000077', '63000000-0000-4000-8000-000000000020', 'Utilizar apenas autenticacao forte, com senha complexa, sem qualquer diferenciacao de permissoes entre os departamentos.', false, 'Incorreta. Apenas autenticacao forte, sem diferenciacao de permissoes, nao impede que usuarios acessem dados alem do necessario para sua funcao.', 1),
  ('74000000-0000-4000-8000-000000000078', '63000000-0000-4000-8000-000000000020', 'Utilizar apenas autorizacao baseada em funcao, sem qualquer mecanismo robusto de autenticacao para verificar a identidade dos usuarios.', false, 'Incorreta. Sem um mecanismo robusto de autenticacao, a identidade dos usuarios nao e verificada de forma confiavel antes da aplicacao das permissoes.', 2),
  ('74000000-0000-4000-8000-000000000079', '63000000-0000-4000-8000-000000000020', 'Eliminar completamente qualquer processo de login, permitindo acesso livre a todos os funcionarios da empresa.', false, 'Incorreta. Eliminar o processo de login comprometeria totalmente a seguranca da aplicacao, permitindo acesso nao controlado.', 3),
  ('74000000-0000-4000-8000-000000000080', '63000000-0000-4000-8000-000000000020', 'Combinar autenticacao robusta, como autenticacao multifator, com autorizacao baseada em funcao, garantindo que cada departamento tenha acesso apenas aos dados relevantes para sua atuacao.', true, 'Correta. Combinar autenticacao robusta com autorizacao baseada em funcao garante tanto a verificacao confiavel da identidade quanto o controle adequado de acesso aos dados.', 4),
  ('74000000-0000-4000-8000-000000000081', '63000000-0000-4000-8000-000000000021', 'Um servico gratuito que analisa a configuracao e o uso dos recursos do Azure, oferecendo recomendacoes personalizadas em areas como custo, seguranca e desempenho.', true, 'Correta. O Azure Advisor analisa os recursos do Azure e oferece recomendacoes personalizadas para melhorar custo, seguranca, confiabilidade, desempenho e excelencia operacional.', 1),
  ('74000000-0000-4000-8000-000000000082', '63000000-0000-4000-8000-000000000021', 'Uma ferramenta paga exclusivamente para criacao de novas maquinas virtuais no Azure.', false, 'Incorreta. O Azure Advisor nao e uma ferramenta de criacao de maquinas virtuais; ele oferece recomendacoes sobre recursos ja existentes.', 2),
  ('74000000-0000-4000-8000-000000000083', '63000000-0000-4000-8000-000000000021', 'Um servico de armazenamento de arquivos utilizado para hospedar documentos corporativos.', false, 'Incorreta. Armazenamento de arquivos e funcao do Azure Files, nao do Azure Advisor, que e uma ferramenta de recomendacoes.', 3),
  ('74000000-0000-4000-8000-000000000084', '63000000-0000-4000-8000-000000000021', 'Um aplicativo de mensagens instantaneas para comunicacao entre equipes de TI.', false, 'Incorreta. O Azure Advisor nao e um aplicativo de mensagens; e uma ferramenta de analise e recomendacao de recursos.', 4),
  ('74000000-0000-4000-8000-000000000085', '63000000-0000-4000-8000-000000000022', 'Apenas em uma unica categoria, relacionada exclusivamente ao design visual das interfaces dos aplicativos.', false, 'Incorreta. O Azure Advisor nao trata de design visual de interfaces; suas recomendacoes abrangem outras areas tecnicas e financeiras.', 1),
  ('74000000-0000-4000-8000-000000000086', '63000000-0000-4000-8000-000000000022', 'Custo, seguranca, confiabilidade, desempenho e excelencia operacional.', true, 'Correta. O Azure Advisor organiza suas recomendacoes em categorias como custo, seguranca, confiabilidade, desempenho e excelencia operacional.', 2),
  ('74000000-0000-4000-8000-000000000087', '63000000-0000-4000-8000-000000000022', 'Apenas em recomendacoes relacionadas exclusivamente a contratacao de novos funcionarios para a equipe de TI.', false, 'Incorreta. Contratacao de funcionarios nao e uma categoria de recomendacao do Azure Advisor, que foca em recursos tecnicos do Azure.', 3),
  ('74000000-0000-4000-8000-000000000088', '63000000-0000-4000-8000-000000000022', 'Exclusivamente em recomendacoes sobre a escolha de moveis para o escritorio da empresa.', false, 'Incorreta. Recomendacoes sobre moveis de escritorio nao tem qualquer relacao com o escopo do Azure Advisor.', 4),
  ('74000000-0000-4000-8000-000000000089', '63000000-0000-4000-8000-000000000023', 'Elas sao geradas aleatoriamente, sem qualquer relacao com os recursos reais utilizados pela assinatura do cliente.', false, 'Incorreta. As recomendacoes nao sao aleatorias; sao baseadas na analise real da configuracao e do uso dos recursos da assinatura.', 1),
  ('74000000-0000-4000-8000-000000000090', '63000000-0000-4000-8000-000000000023', 'Elas se aplicam exclusivamente a assinaturas do Azure localizadas em um unico pais especifico.', false, 'Incorreta. As recomendacoes do Azure Advisor nao sao restritas a um unico pais especifico.', 2),
  ('74000000-0000-4000-8000-000000000091', '63000000-0000-4000-8000-000000000023', 'Elas sao personalizadas, baseadas na analise real da configuracao e do padrao de uso dos recursos da assinatura do Azure do cliente.', true, 'Correta. As recomendacoes do Azure Advisor sao personalizadas, considerando a configuracao real e o padrao de uso dos recursos da assinatura.', 3),
  ('74000000-0000-4000-8000-000000000092', '63000000-0000-4000-8000-000000000023', 'Elas sao fornecidas apenas uma vez por ano, sem qualquer atualizacao ao longo do tempo.', false, 'Incorreta. O Azure Advisor analisa continuamente os recursos, atualizando suas recomendacoes regularmente, e nao apenas uma vez por ano.', 4),
  ('74000000-0000-4000-8000-000000000093', '63000000-0000-4000-8000-000000000024', 'Um servico de streaming de video contratado separadamente pela equipe de TI.', false, 'Incorreta. Um servico de streaming de video nao tem qualquer relacao com a analise de custos de recursos do Azure.', 1),
  ('74000000-0000-4000-8000-000000000094', '63000000-0000-4000-8000-000000000024', 'Um aplicativo de edicao de imagens utilizado pela equipe de marketing da empresa.', false, 'Incorreta. Um aplicativo de edicao de imagens nao esta relacionado a identificacao de recursos subutilizados no Azure.', 2),
  ('74000000-0000-4000-8000-000000000095', '63000000-0000-4000-8000-000000000024', 'A contratacao de uma nova linha telefonica para a equipe de suporte tecnico.', false, 'Incorreta. Contratar uma nova linha telefonica nao tem relacao com a otimizacao de custos de recursos na nuvem.', 3),
  ('74000000-0000-4000-8000-000000000096', '63000000-0000-4000-8000-000000000024', 'O Azure Advisor, que analisa o uso dos recursos e pode recomendar, por exemplo, o redimensionamento ou a desativacao de recursos subutilizados.', true, 'Correta. O Azure Advisor analisa o uso dos recursos da assinatura e pode identificar recursos subutilizados, recomendando acoes como redimensionamento.', 4),
  ('74000000-0000-4000-8000-000000000097', '63000000-0000-4000-8000-000000000025', 'A categoria de seguranca, que identifica configuracoes que podem representar riscos e sugere acoes para mitiga-los.', true, 'Correta. A categoria de seguranca do Azure Advisor e especificamente voltada a identificacao de vulnerabilidades e riscos de configuracao.', 1),
  ('74000000-0000-4000-8000-000000000098', '63000000-0000-4000-8000-000000000025', 'A categoria de excelencia operacional, focada exclusivamente em boas praticas de nomenclatura de recursos.', false, 'Incorreta. Excelencia operacional foca em boas praticas de gerenciamento, mas nao e a categoria mais especifica para vulnerabilidades de seguranca.', 2),
  ('74000000-0000-4000-8000-000000000099', '63000000-0000-4000-8000-000000000025', 'A categoria de desempenho, que trata exclusivamente da velocidade de resposta de aplicacoes web.', false, 'Incorreta. A categoria de desempenho foca em velocidade e eficiencia, nao especificamente em vulnerabilidades de seguranca.', 3),
  ('74000000-0000-4000-8000-000000000100', '63000000-0000-4000-8000-000000000025', 'A categoria de custo, que trata exclusivamente de oportunidades de economia financeira.', false, 'Incorreta. A categoria de custo foca em economia financeira, e nao diretamente em vulnerabilidades de seguranca.', 4),
  ('74000000-0000-4000-8000-000000000101', '63000000-0000-4000-8000-000000000026', 'A categoria de custo, ja que distribuir a aplicacao entre zonas de disponibilidade reduz diretamente as despesas mensais.', false, 'Incorreta. Embora possa ter algum impacto de custo, essa recomendacao especifica esta mais relacionada a resiliencia do que a economia financeira.', 1),
  ('74000000-0000-4000-8000-000000000102', '63000000-0000-4000-8000-000000000026', 'A categoria de confiabilidade, ja que distribuir a aplicacao entre multiplas zonas de disponibilidade aumenta sua resiliencia a falhas.', true, 'Correta. Recomendacoes relacionadas a distribuicao entre zonas de disponibilidade, visando reduzir risco de indisponibilidade, pertencem a categoria de confiabilidade.', 2),
  ('74000000-0000-4000-8000-000000000103', '63000000-0000-4000-8000-000000000026', 'A categoria de excelencia operacional, ja que trata exclusivamente da nomenclatura de recursos utilizados.', false, 'Incorreta. A categoria de excelencia operacional trata de boas praticas de gerenciamento, nao especificamente de resiliencia a falhas.', 3),
  ('74000000-0000-4000-8000-000000000104', '63000000-0000-4000-8000-000000000026', 'A categoria de seguranca, ja que a distribuicao entre zonas de disponibilidade impede ataques ciberneticos externos.', false, 'Incorreta. A distribuicao entre zonas de disponibilidade esta relacionada a resiliencia, e nao especificamente a protecao contra ataques ciberneticos.', 4),
  ('74000000-0000-4000-8000-000000000105', '63000000-0000-4000-8000-000000000027', 'O Azure Advisor sempre substitui integralmente qualquer necessidade de analise humana especializada, em qualquer cenario.', false, 'Incorreta. Embora util, o Azure Advisor nao substitui integralmente a analise humana especializada em todos os cenarios possiveis.', 1),
  ('74000000-0000-4000-8000-000000000106', '63000000-0000-4000-8000-000000000027', 'O Azure Advisor e mais caro do que contratar uma equipe de consultoria externa para realizar auditorias manuais.', false, 'Incorreta. O Azure Advisor e um servico gratuito, ao contrario de auditorias manuais realizadas por consultorias externas, que geralmente tem custo.', 2),
  ('74000000-0000-4000-8000-000000000107', '63000000-0000-4000-8000-000000000027', 'O Azure Advisor analisa continuamente os recursos da assinatura de forma automatizada, oferecendo recomendacoes atualizadas sem a necessidade de agendar auditorias pontuais.', true, 'Correta. O Azure Advisor oferece analise continua e automatizada dos recursos, ao contrario de auditorias pontuais que dependem de agendamento manual.', 3),
  ('74000000-0000-4000-8000-000000000108', '63000000-0000-4000-8000-000000000027', 'O Azure Advisor so pode ser utilizado uma unica vez por assinatura, nao oferecendo qualquer atualizacao continua.', false, 'Incorreta. O Azure Advisor realiza analises continuas, e nao apenas uma unica vez por assinatura.', 4),
  ('74000000-0000-4000-8000-000000000109', '63000000-0000-4000-8000-000000000028', 'Substituir totalmente qualquer necessidade de revisar as recomendacoes detalhadas em cada categoria especifica.', false, 'Incorreta. A pontuacao resume o progresso geral, mas nao substitui a analise das recomendacoes detalhadas em cada categoria.', 1),
  ('74000000-0000-4000-8000-000000000110', '63000000-0000-4000-8000-000000000028', 'Determinar automaticamente o valor da fatura mensal da assinatura do Azure.', false, 'Incorreta. A pontuacao do Azure Advisor nao determina o valor da fatura mensal; ela mede a adesao a boas praticas recomendadas.', 2),
  ('74000000-0000-4000-8000-000000000111', '63000000-0000-4000-8000-000000000028', 'Garantir que nenhum novo recurso possa ser criado enquanto a pontuacao estiver abaixo de um valor minimo.', false, 'Incorreta. A criacao de novos recursos nao e bloqueada pela pontuacao do Azure Advisor Score.', 3),
  ('74000000-0000-4000-8000-000000000112', '63000000-0000-4000-8000-000000000028', 'Permitir acompanhar ao longo do tempo o progresso da adocao das recomendacoes do Azure Advisor, servindo como um indicador resumido da maturidade da configuracao dos recursos.', true, 'Correta. O Azure Advisor Score resume numericamente a adesao as recomendacoes, permitindo acompanhar o progresso da equipe ao longo do tempo.', 4),
  ('74000000-0000-4000-8000-000000000113', '63000000-0000-4000-8000-000000000029', 'Avaliar o impacto potencial de cada recomendacao, priorizando aquelas relacionadas a riscos de seguranca criticos e a oportunidades significativas de economia, antes de tratar recomendacoes de menor impacto.', true, 'Correta. Avaliar o impacto potencial e priorizar recomendacoes criticas de seguranca e economia significativa e a abordagem mais equilibrada diante de recursos limitados.', 1),
  ('74000000-0000-4000-8000-000000000114', '63000000-0000-4000-8000-000000000029', 'Implementar todas as recomendacoes simultaneamente, independentemente do impacto ou da complexidade de cada uma.', false, 'Incorreta. Implementar tudo simultaneamente, sem priorizacao, pode sobrecarregar a equipe e nao considerar o impacto relativo de cada recomendacao.', 2),
  ('74000000-0000-4000-8000-000000000115', '63000000-0000-4000-8000-000000000029', 'Ignorar completamente todas as recomendacoes, ja que implementa-las exigiria tempo da equipe.', false, 'Incorreta. Ignorar completamente as recomendacoes pode deixar a organizacao exposta a riscos de seguranca, custo ou confiabilidade evitaveis.', 3),
  ('74000000-0000-4000-8000-000000000116', '63000000-0000-4000-8000-000000000029', 'Escolher aleatoriamente quais recomendacoes implementar, sem qualquer criterio tecnico ou financeiro.', false, 'Incorreta. Escolher aleatoriamente, sem criterio, pode levar a negligenciar recomendacoes criticas em favor de itens de menor impacto.', 4),
  ('74000000-0000-4000-8000-000000000117', '63000000-0000-4000-8000-000000000030', 'O Azure Advisor garante protecao completa contra qualquer tipo de incidente de seguranca, tornando impossivel a ocorrencia desse cenario.', false, 'Incorreta. O Azure Advisor nao garante protecao completa contra todo tipo de incidente; ele oferece recomendacoes baseadas em padroes conhecidos, mas nao substitui uma estrategia de seguranca abrangente.', 1),
  ('74000000-0000-4000-8000-000000000118', '63000000-0000-4000-8000-000000000030', 'O Azure Advisor e uma ferramenta valiosa de recomendacoes baseadas em padroes conhecidos, mas nao substitui uma estrategia abrangente de seguranca, incluindo revisoes especializadas e monitoramento continuo alem de suas recomendacoes automatizadas.', true, 'Correta. O Azure Advisor e valioso, mas suas recomendacoes automatizadas nao substituem uma estrategia de seguranca mais ampla e revisoes especializadas complementares.', 2),
  ('74000000-0000-4000-8000-000000000119', '63000000-0000-4000-8000-000000000030', 'O Azure Advisor deve ser totalmente descartado, ja que nao ofereceu nenhum valor para a seguranca da organizacao nesse caso.', false, 'Incorreta. Mesmo diante desse incidente, o Azure Advisor pode ter contribuido para mitigar outros riscos; descartar completamente a ferramenta nao e uma conclusao adequada.', 3),
  ('74000000-0000-4000-8000-000000000120', '63000000-0000-4000-8000-000000000030', 'O incidente ocorreu exclusivamente por culpa do provedor de nuvem, sem qualquer relacao com as praticas de configuracao da organizacao.', false, 'Incorreta. O cenario indica que o incidente foi causado por uma pratica de configuracao especifica da organizacao, nao exclusivamente pelo provedor de nuvem.', 4),
  ('74000000-0000-4000-8000-000000000121', '63000000-0000-4000-8000-000000000031', 'Um servico de armazenamento de arquivos exclusivo para ambientes totalmente hospedados na nuvem publica do Azure.', false, 'Incorreta. Azure Arc nao e um servico de armazenamento; ele e voltado ao gerenciamento de recursos em diferentes ambientes.', 1),
  ('74000000-0000-4000-8000-000000000122', '63000000-0000-4000-8000-000000000031', 'Uma ferramenta exclusiva para criacao de contas de usuario no Microsoft Entra ID.', false, 'Incorreta. Criacao de contas de usuario e funcao de servicos de identidade, nao do Azure Arc.', 2),
  ('74000000-0000-4000-8000-000000000123', '63000000-0000-4000-8000-000000000031', 'Um servico que estende o gerenciamento do Azure a recursos localizados fora do Azure, incluindo servidores on-premises, outras nuvens e ambientes de borda.', true, 'Correta. O Azure Arc estende as capacidades de gerenciamento do Azure a recursos hibridos e multicloud, permitindo gerencia-los de forma unificada.', 3),
  ('74000000-0000-4000-8000-000000000124', '63000000-0000-4000-8000-000000000031', 'Um aplicativo de videoconferencia integrado ao Microsoft Teams.', false, 'Incorreta. O Azure Arc nao e um aplicativo de videoconferencia; e um servico de gerenciamento de recursos hibridos.', 4),
  ('74000000-0000-4000-8000-000000000125', '63000000-0000-4000-8000-000000000032', 'Eliminar completamente a necessidade de qualquer infraestrutura on-premises em qualquer organizacao.', false, 'Incorreta. O Azure Arc nao elimina a infraestrutura on-premises; ele permite gerencia-la de forma integrada com o Azure.', 1),
  ('74000000-0000-4000-8000-000000000126', '63000000-0000-4000-8000-000000000032', 'Substituir totalmente o uso de qualquer ferramenta de linha de comando, como o Azure CLI.', false, 'Incorreta. O Azure Arc nao substitui ferramentas de linha de comando; ele pode, inclusive, ser gerenciado por meio delas.', 2),
  ('74000000-0000-4000-8000-000000000127', '63000000-0000-4000-8000-000000000032', 'Restringir o uso de recursos do Azure exclusivamente a uma unica regiao geografica especifica.', false, 'Incorreta. O Azure Arc nao restringe recursos a uma unica regiao; pelo contrario, permite gerenciar recursos distribuidos geograficamente.', 3),
  ('74000000-0000-4000-8000-000000000128', '63000000-0000-4000-8000-000000000032', 'Fornecer um unico ponto de gerenciamento e governanca para recursos distribuidos em ambientes hibridos e multicloud.', true, 'Correta. Um dos principais objetivos do Azure Arc e fornecer um ponto centralizado de gerenciamento e governanca para recursos em diferentes ambientes.', 4),
  ('74000000-0000-4000-8000-000000000129', '63000000-0000-4000-8000-000000000033', 'Servidores fisicos ou virtuais on-premises, maquinas virtuais em outras nuvens e clusters Kubernetes em diferentes ambientes.', true, 'Correta. O Azure Arc permite estender o gerenciamento do Azure a servidores on-premises, maquinas virtuais em outras nuvens e clusters Kubernetes distribuidos.', 1),
  ('74000000-0000-4000-8000-000000000130', '63000000-0000-4000-8000-000000000033', 'Apenas maquinas virtuais hospedadas exclusivamente dentro do proprio Azure.', false, 'Incorreta. O Azure Arc e voltado justamente a recursos que nao estao hospedados diretamente no Azure, e nao apenas a recursos internos.', 2),
  ('74000000-0000-4000-8000-000000000131', '63000000-0000-4000-8000-000000000033', 'Exclusivamente impressoras e scanners conectados a rede corporativa de uma empresa.', false, 'Incorreta. Impressoras e scanners nao sao o foco do Azure Arc, que se concentra em servidores, maquinas virtuais e clusters Kubernetes.', 3),
  ('74000000-0000-4000-8000-000000000132', '63000000-0000-4000-8000-000000000033', 'Apenas contas de e-mail corporativo hospedadas no Microsoft 365.', false, 'Incorreta. Contas de e-mail corporativo nao sao o tipo de recurso gerenciado pelo Azure Arc.', 4),
  ('74000000-0000-4000-8000-000000000133', '63000000-0000-4000-8000-000000000034', 'Azure Files, pois permite compartilhar arquivos entre diferentes ambientes de forma centralizada.', false, 'Incorreta. Azure Files e um servico de armazenamento de arquivos, nao uma ferramenta de governanca unificada entre ambientes hibridos e multicloud.', 1),
  ('74000000-0000-4000-8000-000000000134', '63000000-0000-4000-8000-000000000034', 'Azure Arc, pois estende as capacidades de gerenciamento e governanca do Azure a recursos on-premises e em outras nuvens.', true, 'Correta. O Azure Arc permite aplicar politicas de governanca e monitoramento de forma consistente em recursos distribuidos em diferentes ambientes.', 2),
  ('74000000-0000-4000-8000-000000000135', '63000000-0000-4000-8000-000000000034', 'Azure DNS, pois gerencia exclusivamente a resolucao de nomes de dominio para aplicacoes web.', false, 'Incorreta. Azure DNS e voltado a resolucao de nomes de dominio, sem relacao direta com governanca unificada de recursos hibridos.', 3),
  ('74000000-0000-4000-8000-000000000136', '63000000-0000-4000-8000-000000000034', 'Azure Functions, pois permite executar codigo sem a necessidade de gerenciar servidores.', false, 'Incorreta. Azure Functions e um servico de computacao serverless, sem relacao direta com governanca unificada de ambientes hibridos.', 4),
  ('74000000-0000-4000-8000-000000000137', '63000000-0000-4000-8000-000000000035', 'Migrar fisicamente todos os servidores on-premises para dentro do datacenter do Azure, eliminando a infraestrutura propria.', false, 'Incorreta. Nao e necessario migrar fisicamente os servidores; o Azure Arc permite gerenciar recursos on-premises sem migra-los fisicamente.', 1),
  ('74000000-0000-4000-8000-000000000138', '63000000-0000-4000-8000-000000000035', 'Criar politicas de conformidade completamente separadas e independentes para cada ambiente, sem qualquer integracao entre elas.', false, 'Incorreta. Criar politicas completamente separadas contraria o objetivo de aplicar a mesma politica de forma consistente entre os ambientes.', 2),
  ('74000000-0000-4000-8000-000000000139', '63000000-0000-4000-8000-000000000035', 'Registrar os servidores on-premises no Azure Arc, permitindo aplicar as mesmas politicas de governanca do Azure Policy tambem a esses servidores.', true, 'Correta. Registrar servidores on-premises no Azure Arc permite aplicar politicas de governanca do Azure, como o Azure Policy, tambem a esses recursos.', 3),
  ('74000000-0000-4000-8000-000000000140', '63000000-0000-4000-8000-000000000035', 'Desativar completamente o uso de servidores fisicos on-premises, migrando tudo exclusivamente para maquinas virtuais no Azure.', false, 'Incorreta. Desativar servidores on-premises nao e necessario; o Azure Arc permite gerencia-los de forma integrada com o Azure.', 4),
  ('74000000-0000-4000-8000-000000000141', '63000000-0000-4000-8000-000000000036', 'A possibilidade de eliminar completamente a necessidade de servidores locais nas lojas fisicas.', false, 'Incorreta. O Azure Arc nao elimina a necessidade de servidores locais; ele permite gerencia-los de forma integrada com o Azure.', 1),
  ('74000000-0000-4000-8000-000000000142', '63000000-0000-4000-8000-000000000036', 'A garantia de que as lojas fisicas nunca mais precisarao de conexao com a internet para funcionar.', false, 'Incorreta. O Azure Arc nao elimina a necessidade de conectividade; alguns recursos de gerenciamento dependem de comunicacao com o Azure.', 2),
  ('74000000-0000-4000-8000-000000000143', '63000000-0000-4000-8000-000000000036', 'A eliminacao total de qualquer necessidade de monitoramento de desempenho dos servidores locais das lojas.', false, 'Incorreta. O Azure Arc nao elimina a necessidade de monitoramento; pelo contrario, ele facilita a aplicacao de ferramentas de monitoramento do Azure a esses servidores.', 3),
  ('74000000-0000-4000-8000-000000000144', '63000000-0000-4000-8000-000000000036', 'A capacidade de gerenciar de forma unificada tanto os servidores locais das lojas quanto os recursos na nuvem, utilizando as mesmas ferramentas e politicas do Azure.', true, 'Correta. O Azure Arc permite gerenciar de forma unificada servidores locais e recursos na nuvem, utilizando as mesmas ferramentas e politicas do Azure.', 4),
  ('74000000-0000-4000-8000-000000000145', '63000000-0000-4000-8000-000000000037', 'O Azure Arc permite aplicar de forma consistente politicas, monitoramento e outras ferramentas do Azure a recursos on-premises, algo mais dificil de alcancar com ferramentas locais isoladas e desconectadas entre si.', true, 'Correta. O Azure Arc facilita a aplicacao consistente de politicas e ferramentas do Azure a recursos on-premises, superando as limitacoes de ferramentas locais isoladas.', 1),
  ('74000000-0000-4000-8000-000000000146', '63000000-0000-4000-8000-000000000037', 'O gerenciamento tradicional com ferramentas locais isoladas sempre oferece maior consistencia de politicas do que o Azure Arc.', false, 'Incorreta. Ferramentas locais isoladas tendem a dificultar a consistencia de politicas entre diferentes ambientes, ao contrario do Azure Arc.', 2),
  ('74000000-0000-4000-8000-000000000147', '63000000-0000-4000-8000-000000000037', 'Nao ha qualquer diferenca pratica entre utilizar o Azure Arc ou ferramentas locais isoladas para gerenciar servidores on-premises.', false, 'Incorreta. Ha diferencas praticas significativas, especialmente em relacao a consistencia de politicas e integracao com o ecossistema do Azure.', 3),
  ('74000000-0000-4000-8000-000000000148', '63000000-0000-4000-8000-000000000037', 'O Azure Arc so pode ser utilizado em servidores on-premises que ja estejam fisicamente localizados dentro de um datacenter do Azure.', false, 'Incorreta. O Azure Arc e utilizado justamente em servidores que nao estao fisicamente localizados dentro de um datacenter do Azure.', 4),
  ('74000000-0000-4000-8000-000000000149', '63000000-0000-4000-8000-000000000038', 'Migrar fisicamente o cluster Kubernetes para dentro de um datacenter do Azure antes de aplicar qualquer politica.', false, 'Incorreta. Nao e necessario migrar fisicamente o cluster; o Azure Arc permite gerenciar politicas sem exigir essa migracao.', 1),
  ('74000000-0000-4000-8000-000000000150', '63000000-0000-4000-8000-000000000038', 'Registrar o cluster Kubernetes externo como um recurso Arc-enabled Kubernetes, permitindo aplicar politicas do Azure Policy e outras ferramentas de governanca de forma consistente com os clusters nativos do Azure.', true, 'Correta. Registrar o cluster como Arc-enabled Kubernetes permite aplicar politicas do Azure Policy e outras ferramentas de forma consistente entre clusters dentro e fora do Azure.', 2),
  ('74000000-0000-4000-8000-000000000151', '63000000-0000-4000-8000-000000000038', 'Recriar o cluster do zero utilizando exclusivamente o Azure Kubernetes Service (AKS).', false, 'Incorreta. Recriar o cluster do zero no AKS nao e necessario; o Azure Arc permite gerenciar o cluster existente onde ele ja esta.', 3),
  ('74000000-0000-4000-8000-000000000152', '63000000-0000-4000-8000-000000000038', 'Desativar completamente o uso de Kubernetes fora do Azure, consolidando tudo em uma unica plataforma nativa.', false, 'Incorreta. Desativar o uso de Kubernetes fora do Azure nao e a solucao; o Azure Arc justamente permite gerenciar esses ambientes de forma unificada.', 4),
  ('74000000-0000-4000-8000-000000000153', '63000000-0000-4000-8000-000000000039', 'Ignorar os recursos fora do Azure, aplicando a politica de seguranca apenas aos recursos nativos da nuvem publica do Azure.', false, 'Incorreta. Ignorar recursos fora do Azure deixaria uma parte significativa da infraestrutura sem a aplicacao da politica de seguranca desejada.', 1),
  ('74000000-0000-4000-8000-000000000154', '63000000-0000-4000-8000-000000000039', 'Migrar fisicamente todos os datacenters proprios e recursos do outro provedor de nuvem para dentro do Azure antes de aplicar qualquer politica.', false, 'Incorreta. Nao e necessario migrar fisicamente os recursos; o Azure Arc permite gerenciar politicas sem exigir essa migracao completa.', 2),
  ('74000000-0000-4000-8000-000000000155', '63000000-0000-4000-8000-000000000039', 'Registrar os recursos elegiveis de outros provedores de nuvem e dos datacenters proprios no Azure Arc, permitindo aplicar politicas do Azure Policy e obter visibilidade centralizada de conformidade em todos os ambientes.', true, 'Correta. Registrar os recursos elegiveis no Azure Arc permite aplicar politicas de seguranca de forma centralizada e obter visibilidade unificada de conformidade.', 3),
  ('74000000-0000-4000-8000-000000000156', '63000000-0000-4000-8000-000000000039', 'Criar equipes de TI completamente separadas para cada ambiente, sem qualquer integracao ou visibilidade centralizada entre elas.', false, 'Incorreta. Criar equipes completamente separadas contraria o objetivo de obter visibilidade centralizada de conformidade entre os ambientes.', 4),
  ('74000000-0000-4000-8000-000000000157', '63000000-0000-4000-8000-000000000040', 'Registrar os servidores no Azure Arc elimina completamente qualquer necessidade de seguranca adicional, tornando-os automaticamente protegidos contra qualquer ataque.', false, 'Incorreta. Registrar no Azure Arc nao elimina a necessidade de praticas de seguranca adicionais; a conectividade estabelecida tambem deve ser protegida adequadamente.', 1),
  ('74000000-0000-4000-8000-000000000158', '63000000-0000-4000-8000-000000000040', 'Servidores on-premises criticos nunca podem ser registrados no Azure Arc, independentemente de qualquer analise de beneficios ou riscos.', false, 'Incorreta. Nao ha uma restricao absoluta que impeca o registro de servidores criticos no Azure Arc; a decisao deve ser baseada em uma analise de beneficios e riscos.', 2),
  ('74000000-0000-4000-8000-000000000159', '63000000-0000-4000-8000-000000000040', 'A decisao deve ser tomada exclusivamente com base na cor do logotipo utilizado pela equipe de TI da empresa.', false, 'Incorreta. Aspectos esteticos como o logotipo da equipe nao tem qualquer relacao com essa decisao tecnica de arquitetura e seguranca.', 3),
  ('74000000-0000-4000-8000-000000000160', '63000000-0000-4000-8000-000000000040', 'A equipe deve avaliar os beneficios de gerenciamento unificado proporcionados pelo Azure Arc frente as implicacoes de conectividade e seguranca envolvidas em conectar servidores criticos ao Azure, aplicando controles adequados para proteger essa comunicacao.', true, 'Correta. E necessario avaliar os beneficios de gerenciamento unificado frente as implicacoes de conectividade e seguranca, aplicando controles adequados para essa integracao.', 4),
  ('74000000-0000-4000-8000-000000000161', '63000000-0000-4000-8000-000000000041', 'Uma ferramenta de linha de comando multiplataforma utilizada para criar e gerenciar recursos do Azure por meio de comandos digitados.', true, 'Correta. O Azure CLI e uma ferramenta de linha de comando multiplataforma que permite criar e gerenciar recursos do Azure por meio de comandos.', 1),
  ('74000000-0000-4000-8000-000000000162', '63000000-0000-4000-8000-000000000041', 'Uma interface grafica exclusiva para visualizacao de graficos de custo no portal do Azure.', false, 'Incorreta. O Azure CLI nao e uma interface grafica; e uma ferramenta de linha de comando para interagir com o Azure.', 2),
  ('74000000-0000-4000-8000-000000000163', '63000000-0000-4000-8000-000000000041', 'Um servico exclusivo de armazenamento de backups de bancos de dados relacionais.', false, 'Incorreta. Armazenamento de backups de bancos de dados nao e a funcao do Azure CLI, que e uma ferramenta de gerenciamento de recursos.', 3),
  ('74000000-0000-4000-8000-000000000164', '63000000-0000-4000-8000-000000000041', 'Um aplicativo de design grafico para criacao de diagramas de arquitetura do Azure.', false, 'Incorreta. O Azure CLI nao e uma ferramenta de design grafico; e uma ferramenta de linha de comando para gerenciamento de recursos.', 4),
  ('74000000-0000-4000-8000-000000000165', '63000000-0000-4000-8000-000000000042', 'Exclusivamente em sistemas operacionais Windows, sem suporte a outras plataformas.', false, 'Incorreta. O Azure CLI nao e exclusivo do Windows; ele tambem oferece suporte a outras plataformas.', 1),
  ('74000000-0000-4000-8000-000000000166', '63000000-0000-4000-8000-000000000042', 'O Azure CLI e multiplataforma, podendo ser utilizado em Windows, macOS e Linux.', true, 'Correta. O Azure CLI e uma ferramenta multiplataforma, com suporte para Windows, macOS e Linux.', 2),
  ('74000000-0000-4000-8000-000000000167', '63000000-0000-4000-8000-000000000042', 'Exclusivamente em dispositivos moveis com sistema operacional Android.', false, 'Incorreta. O Azure CLI nao e voltado a dispositivos moveis com Android; ele e utilizado em computadores com sistemas operacionais de desktop ou servidor.', 3),
  ('74000000-0000-4000-8000-000000000168', '63000000-0000-4000-8000-000000000042', 'Apenas em maquinas virtuais criadas exclusivamente dentro do Azure, sem uso local.', false, 'Incorreta. O Azure CLI pode ser instalado e utilizado tanto localmente quanto em maquinas virtuais no Azure, nao sendo restrito a este ultimo caso.', 4),
  ('74000000-0000-4000-8000-000000000169', '63000000-0000-4000-8000-000000000043', 'A eliminacao completa da necessidade de qualquer tipo de autenticacao para acessar recursos do Azure.', false, 'Incorreta. O uso do Azure CLI ainda exige autenticacao adequada para acessar e gerenciar recursos do Azure.', 1),
  ('74000000-0000-4000-8000-000000000170', '63000000-0000-4000-8000-000000000043', 'A garantia de que nenhum erro de digitacao podera ocorrer ao executar comandos no terminal.', false, 'Incorreta. Erros de digitacao podem, sim, ocorrer ao utilizar uma ferramenta de linha de comando como o Azure CLI.', 2),
  ('74000000-0000-4000-8000-000000000171', '63000000-0000-4000-8000-000000000043', 'A possibilidade de automatizar tarefas repetitivas por meio de scripts, executando varios comandos de forma sequencial e programada.', true, 'Correta. Uma das principais vantagens do Azure CLI e permitir a automatizacao de tarefas repetitivas por meio de scripts, algo mais dificil de fazer apenas com o portal grafico.', 3),
  ('74000000-0000-4000-8000-000000000172', '63000000-0000-4000-8000-000000000043', 'A impossibilidade de utilizar o Azure CLI em conjunto com scripts de automacao ou pipelines de implantacao.', false, 'Incorreta. O Azure CLI e amplamente utilizado justamente em conjunto com scripts de automacao e pipelines de implantacao.', 4),
  ('74000000-0000-4000-8000-000000000173', '63000000-0000-4000-8000-000000000044', 'Criar cada maquina virtual manualmente pelo portal grafico do Azure, uma de cada vez, sem qualquer automacao.', false, 'Incorreta. Criar manualmente dezenas de maquinas virtuais uma a uma pelo portal grafico e ineficiente e sujeito a erros para um cenario de automacao.', 1),
  ('74000000-0000-4000-8000-000000000174', '63000000-0000-4000-8000-000000000044', 'Solicitar que cada membro da equipe crie manualmente algumas maquinas virtuais, sem qualquer padronizacao entre elas.', false, 'Incorreta. Criacao manual sem padronizacao aumenta o risco de inconsistencias entre as maquinas virtuais criadas por diferentes membros da equipe.', 2),
  ('74000000-0000-4000-8000-000000000175', '63000000-0000-4000-8000-000000000044', 'Aguardar que o Azure crie automaticamente as maquinas virtuais necessarias, sem qualquer intervencao ou comando da equipe.', false, 'Incorreta. O Azure nao cria automaticamente recursos sem que algum comando, script ou acao seja executado pela equipe.', 3),
  ('74000000-0000-4000-8000-000000000176', '63000000-0000-4000-8000-000000000044', 'Utilizar scripts com o Azure CLI para automatizar a criacao das maquinas virtuais de forma consistente e repetivel dentro do pipeline de implantacao.', true, 'Correta. Utilizar scripts com o Azure CLI permite automatizar a criacao de multiplas maquinas virtuais de forma consistente dentro de um pipeline de implantacao.', 4),
  ('74000000-0000-4000-8000-000000000177', '63000000-0000-4000-8000-000000000045', 'Executar um comando simples do Azure CLI diretamente no terminal ou no Azure Cloud Shell, sem necessidade de criar um script complexo.', true, 'Correta. Para uma tarefa pontual e simples, executar um comando direto do Azure CLI e suficiente, sem necessidade de automacao complexa.', 1),
  ('74000000-0000-4000-8000-000000000178', '63000000-0000-4000-8000-000000000045', 'Escrever um pipeline de implantacao completo, com dezenas de etapas, apenas para listar os grupos de recursos existentes.', false, 'Incorreta. Criar um pipeline completo e desproporcional para uma consulta pontual e simples como listar grupos de recursos.', 2),
  ('74000000-0000-4000-8000-000000000179', '63000000-0000-4000-8000-000000000045', 'Contratar uma equipe de consultoria externa exclusivamente para listar os grupos de recursos da assinatura.', false, 'Incorreta. Contratar uma consultoria externa e desproporcional para uma tarefa simples que pode ser realizada diretamente com o Azure CLI.', 3),
  ('74000000-0000-4000-8000-000000000180', '63000000-0000-4000-8000-000000000045', 'Reconstruir toda a assinatura do Azure do zero apenas para obter a lista atualizada de grupos de recursos.', false, 'Incorreta. Reconstruir toda a assinatura e uma acao extrema e desnecessaria para uma simples consulta de listagem.', 4),
  ('74000000-0000-4000-8000-000000000181', '63000000-0000-4000-8000-000000000046', 'Permitir que cada ambiente seja configurado manualmente por uma pessoa diferente, sem qualquer script ou documentacao compartilhada.', false, 'Incorreta. Configuracao manual e independente por diferentes pessoas aumenta o risco de divergencias entre os ambientes, o oposto do objetivo desejado.', 1),
  ('74000000-0000-4000-8000-000000000182', '63000000-0000-4000-8000-000000000046', 'Criar scripts de automacao com o Azure CLI, versionados em um repositorio de codigo, que sejam executados de forma consistente em cada ambiente.', true, 'Correta. Criar scripts de automacao versionados garante que a criacao de recursos siga os mesmos passos de forma consistente em diferentes ambientes.', 2),
  ('74000000-0000-4000-8000-000000000183', '63000000-0000-4000-8000-000000000046', 'Proibir completamente qualquer criacao de novos recursos no Azure, independentemente do ambiente.', false, 'Incorreta. Proibir a criacao de recursos impediria a propria operacao da infraestrutura, nao sendo uma solucao pratica.', 3),
  ('74000000-0000-4000-8000-000000000184', '63000000-0000-4000-8000-000000000046', 'Trocar de provedor de nuvem a cada novo ambiente criado, para simplificar o processo.', false, 'Incorreta. Trocar de provedor de nuvem a cada ambiente aumentaria a complexidade e nao resolveria o problema de consistencia dentro do proprio Azure.', 4),
  ('74000000-0000-4000-8000-000000000185', '63000000-0000-4000-8000-000000000047', 'O portal grafico e sempre mais eficiente do que o Azure CLI para qualquer tipo de tarefa, incluindo tarefas repetitivas em grande escala.', false, 'Incorreta. Para tarefas repetitivas e em grande escala, o Azure CLI tende a ser mais eficiente do que a execucao manual repetida pelo portal grafico.', 1),
  ('74000000-0000-4000-8000-000000000186', '63000000-0000-4000-8000-000000000047', 'Nao existe qualquer diferenca de eficiencia entre utilizar o Azure CLI ou o portal grafico para tarefas repetitivas em grande escala.', false, 'Incorreta. Ha uma diferenca relevante de eficiencia, especialmente para tarefas repetitivas em grande escala, favorecendo a automacao via Azure CLI.', 2),
  ('74000000-0000-4000-8000-000000000187', '63000000-0000-4000-8000-000000000047', 'O Azure CLI permite automatizar tarefas repetitivas por meio de scripts, tornando-o geralmente mais eficiente do que repetir manualmente as mesmas acoes no portal grafico.', true, 'Correta. O Azure CLI, por permitir automacao via scripts, tende a ser mais eficiente do que repetir manualmente acoes semelhantes no portal grafico.', 3),
  ('74000000-0000-4000-8000-000000000188', '63000000-0000-4000-8000-000000000047', 'O Azure CLI so pode ser utilizado para tarefas de leitura, sem qualquer capacidade de criar ou modificar recursos.', false, 'Incorreta. O Azure CLI e amplamente utilizado tambem para criar, modificar e excluir recursos, e nao apenas para leitura.', 4),
  ('74000000-0000-4000-8000-000000000189', '63000000-0000-4000-8000-000000000048', 'A impossibilidade de qualquer tipo de formatacao diferente da exibicao padrao em texto simples no terminal.', false, 'Incorreta. O Azure CLI oferece, sim, opcoes de formatacao de saida alem do texto simples padrao exibido no terminal.', 1),
  ('74000000-0000-4000-8000-000000000190', '63000000-0000-4000-8000-000000000048', 'A obrigatoriedade de converter manualmente cada resposta do terminal para outro formato, sem qualquer suporte nativo da ferramenta.', false, 'Incorreta. O Azure CLI oferece suporte nativo a formatos estruturados, sem exigir conversao manual de cada resposta pelo usuario.', 2),
  ('74000000-0000-4000-8000-000000000191', '63000000-0000-4000-8000-000000000048', 'A necessidade de utilizar exclusivamente o portal grafico do Azure para obter dados em formato estruturado.', false, 'Incorreta. Nao e necessario utilizar o portal grafico para obter dados estruturados; o proprio Azure CLI oferece essa capacidade diretamente no terminal.', 3),
  ('74000000-0000-4000-8000-000000000192', '63000000-0000-4000-8000-000000000048', 'A possibilidade de formatar a saida dos comandos em formatos estruturados, como JSON, facilitando o processamento automatizado por outros scripts e ferramentas.', true, 'Correta. O Azure CLI permite formatar a saida dos comandos em formatos estruturados, como JSON, facilitando a integracao com outros scripts e ferramentas de automacao.', 4),
  ('74000000-0000-4000-8000-000000000193', '63000000-0000-4000-8000-000000000049', 'Para um cenario com dezenas de ambientes semelhantes provisionados regularmente, investir em scripts de Azure CLI tende a reduzir erros manuais e tempo total gasto, apesar do investimento inicial necessario para cria-los e mante-los.', true, 'Correta. Para provisionamento repetido em escala, scripts de Azure CLI tendem a reduzir erros e tempo total, compensando o investimento inicial em sua criacao.', 1),
  ('74000000-0000-4000-8000-000000000194', '63000000-0000-4000-8000-000000000049', 'O portal grafico deve ser sempre escolhido, independentemente da quantidade de ambientes ou da frequencia de provisionamento, por ser mais simples visualmente.', false, 'Incorreta. Para dezenas de ambientes provisionados regularmente, a simplicidade visual do portal nao compensa a falta de automacao e o risco de inconsistencias.', 2),
  ('74000000-0000-4000-8000-000000000195', '63000000-0000-4000-8000-000000000049', 'Scripts de Azure CLI nunca devem ser utilizados em nenhum cenario, independentemente da escala ou repeticao das tarefas envolvidas.', false, 'Incorreta. Scripts de Azure CLI sao particularmente uteis justamente em cenarios de escala e repeticao, como o descrito na questao.', 3),
  ('74000000-0000-4000-8000-000000000196', '63000000-0000-4000-8000-000000000049', 'A decisao deve ser tomada exclusivamente com base na preferencia pessoal de um unico membro da equipe, sem qualquer analise tecnica.', false, 'Incorreta. Uma decisao tecnica dessa natureza deve considerar fatores como escala, repeticao e consistencia, e nao apenas preferencia pessoal isolada.', 4),
  ('74000000-0000-4000-8000-000000000197', '63000000-0000-4000-8000-000000000050', 'Executar sempre comandos criticos, como exclusao de recursos, diretamente em producao, sem qualquer validacao previa ou ambiente de teste.', false, 'Incorreta. Executar comandos criticos diretamente em producao, sem validacao previa, aumenta o risco de incidentes como o descrito, em vez de preveni-lo.', 1),
  ('74000000-0000-4000-8000-000000000198', '63000000-0000-4000-8000-000000000050', 'Adotar praticas como testar comandos criticos em ambientes de nao producao antes de executa-los em producao, utilizar parametros de confirmacao e restringir permissoes de exclusao a poucas pessoas autorizadas.', true, 'Correta. Testar comandos criticos previamente, usar confirmacoes e restringir permissoes de exclusao sao praticas que ajudam a prevenir incidentes como o descrito.', 2),
  ('74000000-0000-4000-8000-000000000199', '63000000-0000-4000-8000-000000000050', 'Nunca utilizar o Azure CLI para qualquer tipo de tarefa, retornando exclusivamente ao uso do portal grafico para todas as operacoes.', false, 'Incorreta. Abandonar completamente o Azure CLI elimina os beneficios de automacao, sem necessariamente resolver a causa raiz do incidente, que esta relacionada a falta de controles adequados.', 3),
  ('74000000-0000-4000-8000-000000000200', '63000000-0000-4000-8000-000000000050', 'Compartilhar as credenciais de administrador com toda a equipe, para que qualquer pessoa possa corrigir rapidamente qualquer problema.', false, 'Incorreta. Compartilhar credenciais de administrador com toda a equipe aumenta o risco de novos incidentes, em vez de preveni-los.', 4),
  ('74000000-0000-4000-8000-000000000201', '63000000-0000-4000-8000-000000000051', 'Um servico de armazenamento de arquivos exclusivo para backups de longo prazo.', false, 'Incorreta. Armazenamento de arquivos para backups de longo prazo nao e a funcao do Azure Cloud Shell, que e um ambiente de linha de comando.', 1),
  ('74000000-0000-4000-8000-000000000202', '63000000-0000-4000-8000-000000000051', 'Uma ferramenta exclusiva para design de interfaces graficas de aplicativos web.', false, 'Incorreta. O Azure Cloud Shell nao e uma ferramenta de design de interfaces; e um ambiente de linha de comando.', 2),
  ('74000000-0000-4000-8000-000000000203', '63000000-0000-4000-8000-000000000051', 'Um ambiente de shell interativo, acessivel pelo navegador, que permite gerenciar recursos do Azure sem precisar instalar ferramentas localmente.', true, 'Correta. O Azure Cloud Shell e um ambiente de shell interativo, acessivel diretamente pelo navegador, para gerenciar recursos do Azure sem instalacao local.', 3),
  ('74000000-0000-4000-8000-000000000204', '63000000-0000-4000-8000-000000000051', 'Um aplicativo de videoconferencia integrado ao portal do Azure.', false, 'Incorreta. O Azure Cloud Shell nao e um aplicativo de videoconferencia; e um ambiente de linha de comando baseado em navegador.', 4),
  ('74000000-0000-4000-8000-000000000205', '63000000-0000-4000-8000-000000000052', 'Apenas uma linguagem de programacao voltada exclusivamente a desenvolvimento de jogos digitais.', false, 'Incorreta. O Azure Cloud Shell nao e voltado a desenvolvimento de jogos; ele oferece ambientes de linha de comando para gerenciamento de recursos.', 1),
  ('74000000-0000-4000-8000-000000000206', '63000000-0000-4000-8000-000000000052', 'Exclusivamente uma linguagem proprietaria, disponivel apenas para clientes corporativos de grande porte.', false, 'Incorreta. O Azure Cloud Shell nao utiliza uma linguagem proprietaria restrita; ele oferece Bash e PowerShell, amplamente conhecidos.', 2),
  ('74000000-0000-4000-8000-000000000207', '63000000-0000-4000-8000-000000000052', 'Apenas comandos em portugues, sem suporte a comandos em ingles ou outros idiomas de programacao.', false, 'Incorreta. Os comandos do Azure Cloud Shell seguem a sintaxe padrao do Bash ou PowerShell, e nao um idioma especifico como o portugues.', 3),
  ('74000000-0000-4000-8000-000000000208', '63000000-0000-4000-8000-000000000052', 'Bash e PowerShell, permitindo que o usuario escolha o ambiente de linha de comando com o qual esta mais familiarizado.', true, 'Correta. O Azure Cloud Shell oferece suporte tanto a Bash quanto a PowerShell, permitindo escolher o ambiente preferido.', 4),
  ('74000000-0000-4000-8000-000000000209', '63000000-0000-4000-8000-000000000053', 'O Azure Cloud Shell ja vem com ferramentas como Azure CLI e Azure PowerShell pre-instaladas, dispensando a necessidade de configuracao manual do ambiente local.', true, 'Correta. O Azure Cloud Shell oferece um ambiente pronto para uso, com ferramentas como Azure CLI e PowerShell ja pre-instaladas.', 1),
  ('74000000-0000-4000-8000-000000000210', '63000000-0000-4000-8000-000000000053', 'E necessario instalar manualmente o Azure CLI e outras ferramentas antes de poder utilizar o Azure Cloud Shell pela primeira vez.', false, 'Incorreta. O Azure Cloud Shell ja vem com ferramentas como o Azure CLI pre-instaladas, nao exigindo instalacao manual previa pelo usuario.', 2),
  ('74000000-0000-4000-8000-000000000211', '63000000-0000-4000-8000-000000000053', 'O Azure Cloud Shell exige a compra de uma licenca adicional separada para ser utilizado pela primeira vez.', false, 'Incorreta. O Azure Cloud Shell nao exige uma licenca adicional separada para ser utilizado por usuarios com uma assinatura do Azure.', 3),
  ('74000000-0000-4000-8000-000000000212', '63000000-0000-4000-8000-000000000053', 'O Azure Cloud Shell funciona exclusivamente offline, sem qualquer necessidade de conexao com a internet.', false, 'Incorreta. O Azure Cloud Shell e um servico baseado em navegador, exigindo conexao com a internet para ser utilizado.', 4),
  ('74000000-0000-4000-8000-000000000213', '63000000-0000-4000-8000-000000000054', 'Uma instalacao local do Azure CLI, que precisa ser configurada manualmente antes de qualquer uso.', false, 'Incorreta. Instalar o Azure CLI localmente exigiria permissao de instalacao no computador, o que nao esta disponivel nesse cenario.', 1),
  ('74000000-0000-4000-8000-000000000214', '63000000-0000-4000-8000-000000000054', 'O Azure Cloud Shell, pois pode ser acessado diretamente pelo navegador, sem exigir instalacao de qualquer ferramenta no computador utilizado.', true, 'Correta. O Azure Cloud Shell pode ser acessado diretamente pelo navegador, sem exigir instalacao local, sendo ideal para um computador sem permissao de instalacao.', 2),
  ('74000000-0000-4000-8000-000000000215', '63000000-0000-4000-8000-000000000054', 'Um aplicativo de desktop exclusivo para Windows, que precisa ser baixado e instalado antes do primeiro uso.', false, 'Incorreta. Um aplicativo de desktop que exige instalacao nao seria adequado para um computador publico sem permissao de instalacao.', 3),
  ('74000000-0000-4000-8000-000000000216', '63000000-0000-4000-8000-000000000054', 'Um dispositivo fisico USB fornecido exclusivamente pela Microsoft para gerenciamento de recursos do Azure.', false, 'Incorreta. Nao existe um dispositivo fisico USB especifico fornecido pela Microsoft para essa finalidade de gerenciamento de recursos.', 4),
  ('74000000-0000-4000-8000-000000000217', '63000000-0000-4000-8000-000000000055', 'A impossibilidade de utilizar mais de um tipo de shell dentro de uma unica sessao do Azure Cloud Shell.', false, 'Incorreta. O Azure Cloud Shell permite alternar entre Bash e PowerShell, contrariando a ideia de que apenas um tipo de shell pode ser utilizado.', 1),
  ('74000000-0000-4000-8000-000000000218', '63000000-0000-4000-8000-000000000055', 'A exigencia de reiniciar completamente o computador cada vez que a equipe deseja trocar de tipo de shell utilizado.', false, 'Incorreta. Nao e necessario reiniciar o computador para alternar entre os ambientes de shell disponiveis no Azure Cloud Shell.', 2),
  ('74000000-0000-4000-8000-000000000219', '63000000-0000-4000-8000-000000000055', 'A possibilidade de alternar entre os ambientes Bash e PowerShell diretamente dentro do Azure Cloud Shell, sem necessidade de configurar ambientes separados localmente.', true, 'Correta. O Azure Cloud Shell permite alternar entre Bash e PowerShell dentro da mesma sessao, sem exigir configuracao de ambientes locais separados.', 3),
  ('74000000-0000-4000-8000-000000000220', '63000000-0000-4000-8000-000000000055', 'A necessidade de contratar uma licenca adicional especifica para cada tipo de shell utilizado pela equipe.', false, 'Incorreta. Nao e necessaria uma licenca adicional especifica para utilizar Bash ou PowerShell dentro do Azure Cloud Shell.', 4),
  ('74000000-0000-4000-8000-000000000221', '63000000-0000-4000-8000-000000000056', 'Exigir que cada novo funcionario instale manualmente o Azure CLI em seu computador corporativo antes de poder executar qualquer comando.', false, 'Incorreta. Essa abordagem exigiria a configuracao completa do computador antes de qualquer comando, o que contraria a necessidade descrita no cenario.', 1),
  ('74000000-0000-4000-8000-000000000222', '63000000-0000-4000-8000-000000000056', 'Impedir que novos funcionarios executem qualquer comando de gerenciamento do Azure durante seus primeiros seis meses de trabalho.', false, 'Incorreta. Impedir totalmente a execucao de comandos por seis meses nao atende a necessidade de produtividade imediata descrita no cenario.', 2),
  ('74000000-0000-4000-8000-000000000223', '63000000-0000-4000-8000-000000000056', 'Solicitar que os novos funcionarios utilizem exclusivamente o computador pessoal, sem qualquer relacao com a infraestrutura corporativa.', false, 'Incorreta. Utilizar exclusivamente o computador pessoal, sem relacao com a infraestrutura corporativa, nao e uma pratica adequada nem segura.', 3),
  ('74000000-0000-4000-8000-000000000224', '63000000-0000-4000-8000-000000000056', 'Orientar os novos funcionarios a acessar o Azure Cloud Shell pelo navegador, permitindo que executem comandos de gerenciamento do Azure mesmo antes de terem o computador totalmente configurado.', true, 'Correta. O Azure Cloud Shell permite que novos funcionarios executem comandos pelo navegador, sem depender da configuracao completa do computador corporativo.', 4),
  ('74000000-0000-4000-8000-000000000225', '63000000-0000-4000-8000-000000000057', 'O Azure Cloud Shell tende a ser mais portavel, pois pode ser acessado de qualquer dispositivo com navegador e conexao a internet, sem depender de uma instalacao especifica em um unico computador.', true, 'Correta. O Azure Cloud Shell oferece maior portabilidade por ser acessivel de qualquer dispositivo com navegador, sem depender de instalacao local especifica.', 1),
  ('74000000-0000-4000-8000-000000000226', '63000000-0000-4000-8000-000000000057', 'A instalacao local do Azure CLI e sempre mais portavel do que o Azure Cloud Shell, em qualquer cenario.', false, 'Incorreta. E o Azure Cloud Shell, e nao a instalacao local, que costuma oferecer maior portabilidade, ja que pode ser acessado de qualquer navegador.', 2),
  ('74000000-0000-4000-8000-000000000227', '63000000-0000-4000-8000-000000000057', 'Nao ha qualquer diferenca de portabilidade entre o Azure Cloud Shell e uma instalacao local do Azure CLI.', false, 'Incorreta. Ha uma diferenca relevante de portabilidade entre os dois, especialmente ao considerar o acesso a partir de diferentes dispositivos.', 3),
  ('74000000-0000-4000-8000-000000000228', '63000000-0000-4000-8000-000000000057', 'O Azure Cloud Shell so pode ser acessado a partir de um unico computador especifico, previamente autorizado pela Microsoft.', false, 'Incorreta. O Azure Cloud Shell pode ser acessado de qualquer dispositivo com navegador e conexao a internet, autenticado com a conta do usuario.', 4),
  ('74000000-0000-4000-8000-000000000229', '63000000-0000-4000-8000-000000000058', 'A memoria temporaria do navegador utilizado para acessar o Cloud Shell, que mantem os arquivos apenas enquanto a aba estiver aberta.', false, 'Incorreta. A memoria temporaria do navegador nao persiste os arquivos entre sessoes; o Cloud Shell utiliza um armazenamento persistente proprio para isso.', 1),
  ('74000000-0000-4000-8000-000000000230', '63000000-0000-4000-8000-000000000058', 'O uso de um compartilhamento do Azure Files, montado automaticamente na primeira configuracao do Cloud Shell, que armazena os arquivos de forma persistente entre diferentes sessoes.', true, 'Correta. O Azure Cloud Shell utiliza um compartilhamento do Azure Files montado automaticamente para armazenar arquivos de forma persistente entre diferentes sessoes do usuario.', 2),
  ('74000000-0000-4000-8000-000000000231', '63000000-0000-4000-8000-000000000058', 'A necessidade de reenviar manualmente os arquivos a cada nova sessao, ja que o Cloud Shell nao oferece qualquer persistencia nativa.', false, 'Incorreta. O Cloud Shell oferece persistencia nativa de arquivos entre sessoes, nao exigindo reenvio manual a cada novo acesso.', 3),
  ('74000000-0000-4000-8000-000000000232', '63000000-0000-4000-8000-000000000058', 'Um servico de e-mail que envia automaticamente uma copia dos arquivos criados ao usuario apos cada sessao.', false, 'Incorreta. O Cloud Shell nao utiliza envio de e-mail para persistir arquivos; ele utiliza um compartilhamento do Azure Files montado automaticamente.', 4),
  ('74000000-0000-4000-8000-000000000233', '63000000-0000-4000-8000-000000000059', 'O Azure Cloud Shell e sempre a melhor opcao para qualquer tipo de automacao, incluindo pipelines agendados sem intervencao humana, sem qualquer ressalva.', false, 'Incorreta. O Azure Cloud Shell e uma ferramenta interativa acessada por sessao no navegador, o que pode nao ser o mecanismo mais adequado para pipelines totalmente agendados e sem intervencao humana.', 1),
  ('74000000-0000-4000-8000-000000000234', '63000000-0000-4000-8000-000000000059', 'O Azure Cloud Shell deve ser completamente abandonado, mesmo para tarefas pontuais e interativas de gerenciamento de recursos.', false, 'Incorreta. O Azure Cloud Shell continua sendo uma ferramenta valiosa para tarefas pontuais e interativas, mesmo que nao seja ideal para pipelines totalmente automatizados e agendados.', 2),
  ('74000000-0000-4000-8000-000000000235', '63000000-0000-4000-8000-000000000059', 'Para pipelines de implantacao continuos e agendados, sem intervencao humana, ferramentas de automacao dedicadas, como pipelines de CI/CD que utilizam o Azure CLI ou SDKs, tendem a ser mais adequadas do que depender de sessoes interativas do Azure Cloud Shell.', true, 'Correta. Para automacao continua e agendada, sem intervencao humana, pipelines de CI/CD dedicados tendem a ser mais adequados do que sessoes interativas do Azure Cloud Shell.', 3),
  ('74000000-0000-4000-8000-000000000236', '63000000-0000-4000-8000-000000000059', 'Nao existe qualquer diferenca entre o Azure Cloud Shell e ferramentas de automacao dedicadas para pipelines de implantacao continuos.', false, 'Incorreta. Ha diferencas relevantes entre uma sessao interativa de shell e ferramentas de automacao dedicadas para pipelines continuos e agendados.', 4),
  ('74000000-0000-4000-8000-000000000237', '63000000-0000-4000-8000-000000000060', 'Impedir completamente o uso do Azure Cloud Shell por qualquer funcionario da organizacao, independentemente de seu cargo ou necessidade.', false, 'Incorreta. Impedir completamente o uso do Azure Cloud Shell eliminaria beneficios legitimos da ferramenta, sem necessariamente resolver o problema de permissoes amplas.', 1),
  ('74000000-0000-4000-8000-000000000238', '63000000-0000-4000-8000-000000000060', 'Compartilhar uma unica conta de administrador entre todos os funcionarios, para simplificar o controle de acesso ao Azure Cloud Shell.', false, 'Incorreta. Compartilhar uma unica conta de administrador aumenta o risco de acoes indevidas, em vez de mitiga-lo.', 2),
  ('74000000-0000-4000-8000-000000000239', '63000000-0000-4000-8000-000000000060', 'Permitir que qualquer funcionario, independentemente do cargo, tenha acesso irrestrito a todos os recursos da organizacao pelo Azure Cloud Shell.', false, 'Incorreta. Permitir acesso irrestrito a todos os recursos aumentaria ainda mais o risco de acoes indevidas em recursos criticos.', 3),
  ('74000000-0000-4000-8000-000000000240', '63000000-0000-4000-8000-000000000060', 'Aplicar o principio de menor privilegio, concedendo aos funcionarios apenas as permissoes de acesso estritamente necessarias para suas funcoes, independentemente de estarem utilizando o Azure Cloud Shell ou outra ferramenta.', true, 'Correta. Aplicar o principio de menor privilegio, concedendo apenas as permissoes necessarias, e a medida mais adequada para mitigar o risco de acoes indevidas.', 4),
  ('74000000-0000-4000-8000-000000000241', '63000000-0000-4000-8000-000000000061', 'O tipo de recurso contratado, como maquina virtual, banco de dados ou armazenamento, e sua configuracao especifica.', true, 'Correta. O tipo de recurso e sua configuracao especifica, como tamanho e desempenho, sao fatores que influenciam diretamente o custo no Azure.', 1),
  ('74000000-0000-4000-8000-000000000242', '63000000-0000-4000-8000-000000000061', 'A cor escolhida para o icone do recurso dentro do portal do Azure.', false, 'Incorreta. A cor do icone do recurso no portal e um detalhe visual, sem qualquer relacao com o custo do recurso contratado.', 2),
  ('74000000-0000-4000-8000-000000000243', '63000000-0000-4000-8000-000000000061', 'O nome que o administrador decide dar ao grupo de recursos criado.', false, 'Incorreta. O nome do grupo de recursos e uma escolha organizacional, sem impacto direto no custo dos recursos contidos nele.', 3),
  ('74000000-0000-4000-8000-000000000244', '63000000-0000-4000-8000-000000000061', 'A quantidade de abas abertas no navegador utilizado para acessar o portal do Azure.', false, 'Incorreta. A quantidade de abas abertas no navegador do usuario nao tem qualquer relacao com o custo dos recursos no Azure.', 4),
  ('74000000-0000-4000-8000-000000000245', '63000000-0000-4000-8000-000000000062', 'A regiao geografica nunca influencia o custo de um recurso, sendo o preco sempre identico em qualquer regiao do mundo.', false, 'Incorreta. O preco de recursos no Azure pode variar entre regioes geograficas, devido a fatores como custos operacionais locais e impostos.', 1),
  ('74000000-0000-4000-8000-000000000246', '63000000-0000-4000-8000-000000000062', 'O custo de recursos semelhantes pode variar entre diferentes regioes geograficas, devido a fatores como custos operacionais locais, impostos e demanda.', true, 'Correta. O custo de recursos semelhantes pode variar conforme a regiao geografica, devido a fatores como custos operacionais locais e impostos.', 2),
  ('74000000-0000-4000-8000-000000000247', '63000000-0000-4000-8000-000000000062', 'A regiao geografica influencia exclusivamente a cor da interface do portal do Azure exibida ao usuario.', false, 'Incorreta. A regiao geografica nao influencia a cor da interface do portal; ela pode influenciar o preco dos recursos contratados.', 3),
  ('74000000-0000-4000-8000-000000000248', '63000000-0000-4000-8000-000000000062', 'O custo de recursos e determinado exclusivamente pelo numero de feriados nacionais da regiao escolhida.', false, 'Incorreta. O numero de feriados nacionais de uma regiao nao e um fator que determina o custo dos recursos no Azure.', 4),
  ('74000000-0000-4000-8000-000000000249', '63000000-0000-4000-8000-000000000063', 'O trafego de rede nunca gera qualquer tipo de custo adicional, independentemente do volume de dados transferidos.', false, 'Incorreta. O volume de dados transferidos, especialmente saidas de dados (egress), pode gerar custos adicionais dependendo do cenario.', 1),
  ('74000000-0000-4000-8000-000000000250', '63000000-0000-4000-8000-000000000063', 'O trafego de rede e cobrado exclusivamente com base no numero de funcionarios que acessam a aplicacao.', false, 'Incorreta. O numero de funcionarios que acessam a aplicacao nao e o fator determinante para o custo de trafego de rede.', 2),
  ('74000000-0000-4000-8000-000000000251', '63000000-0000-4000-8000-000000000063', 'O volume de dados transferidos, especialmente a saida de dados de uma regiao para a internet ou entre regioes, pode gerar custos adicionais conforme o consumo.', true, 'Correta. A saida de dados (egress), especialmente entre regioes ou para a internet, pode gerar custos adicionais proporcionais ao volume transferido.', 3),
  ('74000000-0000-4000-8000-000000000252', '63000000-0000-4000-8000-000000000063', 'O volume de dados transferidos influencia exclusivamente o tempo de carregamento da pagina, sem qualquer relacao com custos.', false, 'Incorreta. Alem de poder influenciar o desempenho, o volume de dados transferidos tambem pode gerar custos financeiros no Azure.', 4),
  ('74000000-0000-4000-8000-000000000253', '63000000-0000-4000-8000-000000000064', 'Um erro de sistema no portal do Azure, que exibe precos aleatorios sem qualquer logica associada.', false, 'Incorreta. As diferencas de preco entre regioes nao sao um erro de sistema; elas refletem fatores reais como custos operacionais e impostos locais.', 1),
  ('74000000-0000-4000-8000-000000000254', '63000000-0000-4000-8000-000000000064', 'A cor do tema escolhido pelo usuario no portal do Azure durante a consulta de precos.', false, 'Incorreta. O tema visual escolhido pelo usuario no portal nao tem qualquer relacao com os precos reais dos recursos.', 2),
  ('74000000-0000-4000-8000-000000000255', '63000000-0000-4000-8000-000000000064', 'O numero de vezes que o usuario atualizou a pagina de precos durante a consulta.', false, 'Incorreta. O numero de atualizacoes da pagina pelo usuario nao influencia os precos reais dos recursos do Azure.', 3),
  ('74000000-0000-4000-8000-000000000256', '63000000-0000-4000-8000-000000000064', 'Diferencas nos custos operacionais, impostos e infraestrutura locais entre as regioes, que influenciam o preco final cobrado ao cliente.', true, 'Correta. Diferencas nos custos operacionais, impostos e infraestrutura entre regioes sao fatores reais que influenciam o preco final dos recursos.', 4),
  ('74000000-0000-4000-8000-000000000257', '63000000-0000-4000-8000-000000000065', 'Um aumento no custo mensal, ja que configuracoes com mais recursos de processamento e memoria tendem a ser mais caras do que configuracoes basicas.', true, 'Correta. Configuracoes de maquinas virtuais com mais recursos, como processamento e memoria, tendem a gerar um custo mensal mais elevado.', 1),
  ('74000000-0000-4000-8000-000000000258', '63000000-0000-4000-8000-000000000065', 'Nenhum impacto, ja que o custo de maquinas virtuais no Azure e sempre fixo, independentemente da configuracao escolhida.', false, 'Incorreta. O custo de maquinas virtuais no Azure normalmente varia conforme a configuracao escolhida, como numero de nucleos e quantidade de memoria.', 2),
  ('74000000-0000-4000-8000-000000000259', '63000000-0000-4000-8000-000000000065', 'Uma reducao automatica no custo mensal, ja que configuracoes de maior desempenho sempre recebem descontos proporcionais.', false, 'Incorreta. Configuracoes de maior desempenho geralmente aumentam, e nao reduzem, o custo mensal em comparacao a configuracoes basicas.', 3),
  ('74000000-0000-4000-8000-000000000260', '63000000-0000-4000-8000-000000000065', 'Um impacto exclusivamente na velocidade de processamento, sem qualquer relacao com o custo mensal do servico.', false, 'Incorreta. Alem de impactar a velocidade de processamento, a escolha de uma configuracao de maior desempenho tambem impacta diretamente o custo mensal.', 4),
  ('74000000-0000-4000-8000-000000000261', '63000000-0000-4000-8000-000000000066', 'O fator de custo relacionado ao numero de licencas de software instaladas nos servidores da aplicacao.', false, 'Incorreta. Licencas de software instaladas nos servidores nao sao o fator relacionado ao cenario de transferencia de dados para a internet.', 1),
  ('74000000-0000-4000-8000-000000000262', '63000000-0000-4000-8000-000000000066', 'O fator de custo relacionado a saida de dados (egress) da regiao do Azure para a internet, que geralmente gera cobranca proporcional ao volume transferido.', true, 'Correta. A saida de dados (egress) de uma regiao do Azure para a internet e o fator de custo diretamente relacionado ao cenario descrito.', 2),
  ('74000000-0000-4000-8000-000000000263', '63000000-0000-4000-8000-000000000066', 'O fator de custo relacionado exclusivamente ao numero de administradores cadastrados na assinatura do Azure.', false, 'Incorreta. O numero de administradores cadastrados na assinatura nao esta relacionado ao custo de transferencia de dados para a internet.', 3),
  ('74000000-0000-4000-8000-000000000264', '63000000-0000-4000-8000-000000000066', 'O fator de custo relacionado ao tamanho da tela dos dispositivos utilizados pelos usuarios finais para acessar a aplicacao.', false, 'Incorreta. O tamanho da tela dos dispositivos dos usuarios finais nao tem qualquer relacao com o custo de transferencia de dados.', 4),
  ('74000000-0000-4000-8000-000000000265', '63000000-0000-4000-8000-000000000067', 'O custo e sempre identico entre os dois cenarios, independentemente do tempo em que os recursos permanecem ativos.', false, 'Incorreta. O tempo em que os recursos permanecem ativos geralmente influencia diretamente o custo total, contrariando a ideia de que o custo seria sempre identico.', 1),
  ('74000000-0000-4000-8000-000000000266', '63000000-0000-4000-8000-000000000067', 'Manter recursos ativos apenas durante o horario comercial sempre aumenta o custo total, em comparacao a mante-los ativos 24 horas por dia.', false, 'Incorreta. Reduzir o tempo de atividade dos recursos geralmente reduz, e nao aumenta, o custo total em comparacao a mante-los sempre ativos.', 2),
  ('74000000-0000-4000-8000-000000000267', '63000000-0000-4000-8000-000000000067', 'Manter recursos ativos apenas durante o horario comercial, com desligamento programado fora desse periodo, tende a reduzir o custo total em comparacao a mante-los ativos continuamente 24 horas por dia.', true, 'Correta. Reduzir o tempo de atividade dos recursos, desligando-os fora do horario necessario, tende a reduzir o custo total em comparacao a mante-los sempre ativos.', 3),
  ('74000000-0000-4000-8000-000000000268', '63000000-0000-4000-8000-000000000067', 'O tempo de atividade dos recursos nunca influencia o custo total no Azure, que depende exclusivamente do tipo de recurso contratado.', false, 'Incorreta. O tempo de atividade dos recursos e, sim, um fator relevante que influencia o custo total, alem do tipo de recurso contratado.', 4),
  ('74000000-0000-4000-8000-000000000269', '63000000-0000-4000-8000-000000000068', 'A reducao automatica e gratuita do preco de qualquer maquina virtual apos um ano de uso continuo, sem qualquer compromisso previo.', false, 'Incorreta. Nao ha uma reducao automatica e gratuita de preco apenas pelo tempo de uso continuo, sem um compromisso de reserva previamente assumido.', 1),
  ('74000000-0000-4000-8000-000000000270', '63000000-0000-4000-8000-000000000068', 'A eliminacao completa de qualquer custo de maquina virtual apos o terceiro ano de utilizacao continua.', false, 'Incorreta. Nao existe eliminacao total do custo apos um determinado periodo de uso continuo, mesmo com compromissos de longo prazo assumidos.', 2),
  ('74000000-0000-4000-8000-000000000271', '63000000-0000-4000-8000-000000000068', 'A obrigatoriedade de trocar de provedor de nuvem a cada ano para obter descontos progressivos.', false, 'Incorreta. Trocar de provedor de nuvem nao e um mecanismo de desconto do Azure; instancias reservadas sao o mecanismo especifico para esse tipo de economia.', 3),
  ('74000000-0000-4000-8000-000000000272', '63000000-0000-4000-8000-000000000068', 'A utilizacao de instancias reservadas, em que a empresa se compromete a utilizar determinada capacidade por um periodo predefinido em troca de um desconto significativo em relacao ao preco pago sob demanda.', true, 'Correta. Instancias reservadas oferecem descontos significativos em troca de um compromisso de uso por um periodo predefinido, sendo adequadas para cargas de trabalho previsiveis de longo prazo.', 4),
  ('74000000-0000-4000-8000-000000000273', '63000000-0000-4000-8000-000000000069', 'Analisar de forma combinada todos os fatores relevantes, como tipo de recurso, regiao, volume esperado de transferencia de dados e tempo de atividade, utilizando ferramentas de estimativa de custo disponibilizadas pelo Azure.', true, 'Correta. Analisar de forma combinada todos os fatores relevantes, com o apoio de ferramentas de estimativa, e a abordagem mais adequada para uma estimativa realista de custo.', 1),
  ('74000000-0000-4000-8000-000000000274', '63000000-0000-4000-8000-000000000069', 'Considerar apenas o preco de lista de um unico tipo de recurso, ignorando completamente fatores como regiao, transferencia de dados e tempo de atividade.', false, 'Incorreta. Considerar apenas o preco de lista de um unico fator, ignorando os demais, resulta em uma estimativa incompleta e pouco realista do custo total.', 2),
  ('74000000-0000-4000-8000-000000000275', '63000000-0000-4000-8000-000000000069', 'Escolher aleatoriamente um valor mensal fixo, sem qualquer analise dos fatores especificos que influenciam o custo da aplicacao.', false, 'Incorreta. Escolher um valor aleatorio, sem analise dos fatores especificos, nao oferece uma estimativa confiavel do custo real da aplicacao.', 3),
  ('74000000-0000-4000-8000-000000000276', '63000000-0000-4000-8000-000000000069', 'Ignorar completamente qualquer estimativa de custo antes de lancar a aplicacao, avaliando os gastos somente apos o primeiro ano de operacao.', false, 'Incorreta. Ignorar qualquer estimativa previa de custo pode gerar surpresas financeiras significativas apos o lancamento da aplicacao.', 4),
  ('74000000-0000-4000-8000-000000000277', '63000000-0000-4000-8000-000000000070', 'Assumir que o custo das duas opcoes sera sempre identico, ja que ambas utilizam o Azure como provedor de nuvem.', false, 'Incorreta. O custo das duas opcoes tende a ser diferente, especialmente devido ao volume adicional de trafego de dados entre regioes na segunda opcao.', 1),
  ('74000000-0000-4000-8000-000000000278', '63000000-0000-4000-8000-000000000070', 'Avaliar o custo adicional de transferencia de dados entre regioes na segunda opcao frente aos beneficios de resiliencia ou desempenho que a distribuicao geografica pode trazer, comparando com o cenario mais simples e de menor trafego da primeira opcao.', true, 'Correta. E necessario avaliar o custo adicional de transferencia de dados entre regioes frente aos beneficios de resiliencia ou desempenho, comparando com a opcao mais simples.', 2),
  ('74000000-0000-4000-8000-000000000279', '63000000-0000-4000-8000-000000000070', 'Escolher automaticamente a opcao que distribui os componentes entre multiplas regioes, independentemente do custo adicional de transferencia de dados envolvido.', false, 'Incorreta. Escolher automaticamente a opcao mais distribuida, sem considerar o custo adicional envolvido, nao e uma analise financeira criteriosa.', 3),
  ('74000000-0000-4000-8000-000000000280', '63000000-0000-4000-8000-000000000070', 'Ignorar completamente qualquer analise de custo, decidindo a arquitetura exclusivamente com base em preferencias pessoais da equipe.', false, 'Incorreta. Ignorar a analise de custo em uma decisao de arquitetura relevante pode levar a escolhas financeiramente inadequadas para a organizacao.', 4),
  ('74000000-0000-4000-8000-000000000281', '63000000-0000-4000-8000-000000000071', 'Um servico exclusivo para criacao de novas contas de e-mail corporativo.', false, 'Incorreta. Criacao de contas de e-mail corporativo nao e a funcao do Azure Cost Management, que e voltado ao controle de custos.', 1),
  ('74000000-0000-4000-8000-000000000282', '63000000-0000-4000-8000-000000000071', 'Uma ferramenta de design grafico para criacao de logotipos de empresas.', false, 'Incorreta. O Azure Cost Management nao e uma ferramenta de design grafico; ele e voltado ao gerenciamento de custos na nuvem.', 2),
  ('74000000-0000-4000-8000-000000000283', '63000000-0000-4000-8000-000000000071', 'Um conjunto de ferramentas do Azure voltado a monitorar, analisar e controlar os gastos com recursos da nuvem.', true, 'Correta. O Azure Cost Management e um conjunto de ferramentas voltado a monitorar, analisar e controlar os gastos com recursos do Azure.', 3),
  ('74000000-0000-4000-8000-000000000284', '63000000-0000-4000-8000-000000000071', 'Um aplicativo de videoconferencia integrado ao Microsoft Teams.', false, 'Incorreta. O Azure Cost Management nao e um aplicativo de videoconferencia; ele e uma ferramenta de gerenciamento financeiro de recursos.', 4),
  ('74000000-0000-4000-8000-000000000285', '63000000-0000-4000-8000-000000000072', 'Um relatorio fixo que nao pode ser configurado ou ajustado pelo usuario apos sua criacao inicial.', false, 'Incorreta. Orcamentos no Azure Cost Management podem ser configurados e ajustados pelo usuario conforme necessario.', 1),
  ('74000000-0000-4000-8000-000000000286', '63000000-0000-4000-8000-000000000072', 'Uma ferramenta exclusiva para calcular impostos sobre servicos de nuvem em diferentes paises.', false, 'Incorreta. Calculo de impostos e uma funcao diferente, nao sendo o conceito central de um orcamento no Azure Cost Management.', 2),
  ('74000000-0000-4000-8000-000000000287', '63000000-0000-4000-8000-000000000072', 'Um documento fisico impresso, entregue mensalmente pela Microsoft aos clientes corporativos.', false, 'Incorreta. Um orcamento no Azure Cost Management e uma configuracao digital dentro da plataforma, e nao um documento fisico impresso.', 3),
  ('74000000-0000-4000-8000-000000000288', '63000000-0000-4000-8000-000000000072', 'Um limite de gastos definido pelo usuario para um periodo especifico, que pode disparar alertas quando os gastos se aproximam ou ultrapassam esse limite.', true, 'Correta. Um orcamento e um limite de gastos definido pelo usuario, utilizado para monitorar despesas e disparar alertas quando necessario.', 4),
  ('74000000-0000-4000-8000-000000000289', '63000000-0000-4000-8000-000000000073', 'Relatorios e paineis visuais que detalham os gastos por recurso, grupo de recursos, marca (tag) ou periodo especifico de tempo.', true, 'Correta. O Azure Cost Management oferece relatorios e paineis visuais que detalham os gastos de diferentes formas, ajudando na analise financeira.', 1),
  ('74000000-0000-4000-8000-000000000290', '63000000-0000-4000-8000-000000000073', 'A criacao automatica de novas maquinas virtuais sempre que o orcamento e ultrapassado.', false, 'Incorreta. O Azure Cost Management nao cria automaticamente novas maquinas virtuais; ele oferece ferramentas de analise e controle de custos.', 2),
  ('74000000-0000-4000-8000-000000000291', '63000000-0000-4000-8000-000000000073', 'A exclusao automatica de todos os recursos da assinatura assim que um orcamento e definido.', false, 'Incorreta. Definir um orcamento nao causa a exclusao automatica de recursos; ele apenas monitora e alerta sobre os gastos.', 3),
  ('74000000-0000-4000-8000-000000000292', '63000000-0000-4000-8000-000000000073', 'A alteracao automatica da senha de todos os usuarios cadastrados na assinatura do Azure.', false, 'Incorreta. Alteracao de senhas de usuarios nao e uma funcionalidade do Azure Cost Management, que e voltado a analise financeira.', 4),
  ('74000000-0000-4000-8000-000000000293', '63000000-0000-4000-8000-000000000074', 'A exclusao manual de todos os recursos da assinatura assim que o mes comeca, reiniciando os gastos do zero.', false, 'Incorreta. Excluir manualmente todos os recursos no inicio do mes nao e uma pratica adequada nem viavel para a operacao continua da empresa.', 1),
  ('74000000-0000-4000-8000-000000000294', '63000000-0000-4000-8000-000000000074', 'A criacao de um orcamento (budget) com um alerta configurado para disparar quando os gastos atingirem 80% do valor definido.', true, 'Correta. Configurar um orcamento com um alerta em 80% do valor definido permite que a equipe financeira seja notificada antes de atingir o limite total.', 2),
  ('74000000-0000-4000-8000-000000000295', '63000000-0000-4000-8000-000000000074', 'A alteracao do nome de todos os grupos de recursos da assinatura para incluir a palavra ''orcamento''.', false, 'Incorreta. Alterar o nome dos grupos de recursos nao gera qualquer tipo de alerta automatico sobre os gastos da assinatura.', 3),
  ('74000000-0000-4000-8000-000000000296', '63000000-0000-4000-8000-000000000074', 'A contratacao de uma nova assinatura do Azure a cada vez que o orcamento se aproxima do limite definido.', false, 'Incorreta. Contratar uma nova assinatura nao e a forma adequada de monitorar e ser alertado sobre os gastos de uma assinatura existente.', 4),
  ('74000000-0000-4000-8000-000000000297', '63000000-0000-4000-8000-000000000075', 'Criar uma assinatura completamente nova do Azure para cada projeto, mesmo que isso complique significativamente a gestao geral dos recursos.', false, 'Incorreta. Criar novas assinaturas para cada projeto e uma solucao possivel, mas nao e a pratica mais direta relacionada ao Azure Cost Management para esse cenario especifico.', 1),
  ('74000000-0000-4000-8000-000000000298', '63000000-0000-4000-8000-000000000075', 'Ignorar completamente a necessidade de detalhamento por projeto, analisando apenas o total geral gasto pela assinatura.', false, 'Incorreta. Ignorar o detalhamento por projeto nao atende a necessidade especifica da empresa de entender os gastos individuais de cada projeto.', 2),
  ('74000000-0000-4000-8000-000000000299', '63000000-0000-4000-8000-000000000075', 'Aplicar marcas (tags) consistentes nos recursos de cada projeto, permitindo filtrar e analisar os gastos por projeto diretamente nos relatorios do Azure Cost Management.', true, 'Correta. Aplicar marcas (tags) consistentes nos recursos permite filtrar e analisar os gastos por projeto diretamente nos relatorios do Azure Cost Management.', 3),
  ('74000000-0000-4000-8000-000000000300', '63000000-0000-4000-8000-000000000075', 'Solicitar que cada equipe de projeto anote manualmente seus gastos em uma planilha separada, sem qualquer integracao com o Azure.', false, 'Incorreta. Anotar manualmente em planilhas separadas, sem integracao com o Azure, e uma abordagem menos eficiente do que utilizar as marcas (tags) diretamente na plataforma.', 4),
  ('74000000-0000-4000-8000-000000000301', '63000000-0000-4000-8000-000000000076', 'Ignorar completamente o aumento identificado, assumindo que ele nao tem qualquer causa investigavel.', false, 'Incorreta. Ignorar um aumento significativo de custo, sem investigar a causa, pode levar a gastos desnecessarios continuados.', 1),
  ('74000000-0000-4000-8000-000000000302', '63000000-0000-4000-8000-000000000076', 'Excluir imediatamente todo o grupo de recursos, sem qualquer investigacao previa sobre a causa do aumento de custo.', false, 'Incorreta. Excluir todo o grupo de recursos sem investigacao previa pode causar interrupcoes indesejadas em servicos que ainda sao necessarios.', 2),
  ('74000000-0000-4000-8000-000000000303', '63000000-0000-4000-8000-000000000076', 'Trocar de provedor de nuvem imediatamente, sem investigar a causa especifica do aumento de custo identificado.', false, 'Incorreta. Trocar de provedor de nuvem e uma decisao extrema e desproporcional para investigar um aumento especifico de custo em um grupo de recursos.', 3),
  ('74000000-0000-4000-8000-000000000304', '63000000-0000-4000-8000-000000000076', 'Utilizar os relatorios detalhados de analise de custos para identificar quais recursos especificos dentro do grupo contribuiram para o aumento observado, comparando periodos anteriores.', true, 'Correta. Utilizar relatorios detalhados de analise de custos permite identificar quais recursos especificos contribuiram para o aumento, comparando periodos anteriores.', 4),
  ('74000000-0000-4000-8000-000000000305', '63000000-0000-4000-8000-000000000077', 'Orcamentos com alertas automaticos tendem a detectar gastos inesperados de forma mais rapida, ja que notificam a equipe assim que um limite predefinido e atingido, sem depender de uma revisao manual periodica.', true, 'Correta. Orcamentos com alertas automaticos notificam a equipe assim que um limite e atingido, permitindo uma deteccao mais rapida do que a analise manual periodica.', 1),
  ('74000000-0000-4000-8000-000000000306', '63000000-0000-4000-8000-000000000077', 'A analise manual periodica de faturas e sempre mais rapida do que orcamentos com alertas automaticos para detectar gastos inesperados.', false, 'Incorreta. Orcamentos com alertas automaticos tendem a detectar gastos inesperados mais rapidamente do que uma analise manual periodica.', 2),
  ('74000000-0000-4000-8000-000000000307', '63000000-0000-4000-8000-000000000077', 'Nao ha qualquer diferenca de velocidade entre os dois metodos para detectar gastos inesperados em uma assinatura do Azure.', false, 'Incorreta. Ha uma diferenca relevante de velocidade de deteccao entre os dois metodos, favorecendo os alertas automaticos de orcamento.', 3),
  ('74000000-0000-4000-8000-000000000308', '63000000-0000-4000-8000-000000000077', 'Orcamentos com alertas automaticos so podem ser configurados uma unica vez por ano, tornando a analise manual sempre necessaria.', false, 'Incorreta. Orcamentos podem ser configurados e ajustados a qualquer momento, e nao apenas uma unica vez por ano.', 4),
  ('74000000-0000-4000-8000-000000000309', '63000000-0000-4000-8000-000000000078', 'Criar uma assinatura totalmente nova do Azure a cada mes, exclusivamente para fins de chargeback interno entre departamentos.', false, 'Incorreta. Criar uma nova assinatura a cada mes e uma abordagem desnecessariamente complexa; marcas (tags) sao a pratica mais direta para esse fim.', 1),
  ('74000000-0000-4000-8000-000000000310', '63000000-0000-4000-8000-000000000078', 'Aplicar marcas (tags) consistentes indicando o departamento responsavel em cada recurso, permitindo gerar relatorios de custo segmentados por departamento para fins de chargeback interno.', true, 'Correta. Aplicar marcas (tags) consistentes por departamento permite segmentar os relatorios de custo do Azure Cost Management, viabilizando o chargeback interno.', 2),
  ('74000000-0000-4000-8000-000000000311', '63000000-0000-4000-8000-000000000078', 'Dividir igualmente o valor total da fatura entre todos os departamentos, independentemente do uso real de cada um.', false, 'Incorreta. Dividir o valor igualmente, sem considerar o uso real, nao reflete corretamente o consumo de cada departamento.', 3),
  ('74000000-0000-4000-8000-000000000312', '63000000-0000-4000-8000-000000000078', 'Impedir que mais de um departamento utilize recursos dentro da mesma assinatura do Azure.', false, 'Incorreta. Impedir o compartilhamento da assinatura entre departamentos nao e necessario nem pratico; marcas (tags) permitem segmentar os custos mesmo com uso compartilhado.', 4),
  ('74000000-0000-4000-8000-000000000313', '63000000-0000-4000-8000-000000000079', 'Um unico orcamento global e sempre suficiente, independentemente do numero de projetos ou da complexidade da assinatura da empresa.', false, 'Incorreta. Um unico orcamento global pode nao oferecer visibilidade suficiente sobre onde exatamente os gastos estao ocorrendo em assinaturas complexas com varios projetos.', 1),
  ('74000000-0000-4000-8000-000000000314', '63000000-0000-4000-8000-000000000079', 'Orcamentos, sejam globais ou segmentados, nunca oferecem qualquer beneficio pratico para o controle financeiro de uma organizacao.', false, 'Incorreta. Orcamentos, especialmente quando bem estruturados, oferecem beneficios praticos significativos para o controle financeiro da organizacao.', 2),
  ('74000000-0000-4000-8000-000000000315', '63000000-0000-4000-8000-000000000079', 'Multiplos orcamentos segmentados por grupo de recursos ou projeto tendem a oferecer maior visibilidade e permitem identificar mais rapidamente qual area especifica esta gerando gastos acima do esperado, em comparacao a um unico orcamento global.', true, 'Correta. Orcamentos segmentados por grupo de recursos ou projeto oferecem maior visibilidade, permitindo identificar mais rapidamente a origem de gastos acima do esperado.', 3),
  ('74000000-0000-4000-8000-000000000316', '63000000-0000-4000-8000-000000000079', 'A decisao deve ser tomada exclusivamente com base na preferencia visual da equipe de TI em relacao aos graficos exibidos no portal.', false, 'Incorreta. Uma decisao sobre estrutura de orcamentos deve considerar a complexidade organizacional e a necessidade de visibilidade, nao apenas preferencias visuais.', 4),
  ('74000000-0000-4000-8000-000000000317', '63000000-0000-4000-8000-000000000080', 'O Azure Cost Management e uma ferramenta ineficaz e deve ser completamente abandonado pela organizacao.', false, 'Incorreta. A ferramenta esta cumprindo sua funcao de gerar alertas; o problema esta na ausencia de acao por parte da equipe responsavel, nao na ferramenta em si.', 1),
  ('74000000-0000-4000-8000-000000000318', '63000000-0000-4000-8000-000000000080', 'Alertas de orcamento nunca devem ser configurados, ja que eles nao tem qualquer capacidade de gerar mudancas de comportamento nas equipes.', false, 'Incorreta. Alertas de orcamento podem, sim, gerar mudancas de comportamento quando acompanhados de um processo organizacional adequado para trata-los.', 2),
  ('74000000-0000-4000-8000-000000000319', '63000000-0000-4000-8000-000000000080', 'A unica solucao possivel e reduzir automaticamente a capacidade de todos os recursos assim que um alerta e disparado, sem qualquer intervencao humana.', false, 'Incorreta. Reduzir automaticamente a capacidade de todos os recursos, sem intervencao humana, pode causar problemas operacionais inesperados, alem de nao ser a unica solucao possivel.', 3),
  ('74000000-0000-4000-8000-000000000320', '63000000-0000-4000-8000-000000000080', 'O problema nao esta na ferramenta em si, que esta cumprindo sua funcao de notificar sobre o orcamento ultrapassado, mas sim na ausencia de um processo organizacional que garanta que essas notificacoes gerem acoes concretas por parte da equipe responsavel.', true, 'Correta. O problema esta na ausencia de um processo organizacional que transforme os alertas em acoes concretas, e nao na eficacia da propria ferramenta de alertas.', 4),
  ('74000000-0000-4000-8000-000000000321', '63000000-0000-4000-8000-000000000081', 'Um conjunto de datacenters implantados dentro de um perimetro de latencia definido e conectados por uma rede dedicada de baixa latencia.', true, 'Correta. Uma regiao do Azure e composta por um conjunto de datacenters implantados dentro de um perimetro de latencia, conectados por uma rede dedicada.', 1),
  ('74000000-0000-4000-8000-000000000322', '63000000-0000-4000-8000-000000000081', 'Um unico servidor fisico isolado, sem qualquer conexao com outros datacenters do Azure.', false, 'Incorreta. Uma regiao nao e um unico servidor isolado; ela e composta por um ou mais datacenters interconectados dentro de uma area geografica.', 2),
  ('74000000-0000-4000-8000-000000000323', '63000000-0000-4000-8000-000000000081', 'Uma unica sala de servidores localizada dentro do escritorio central da Microsoft.', false, 'Incorreta. Uma regiao nao e uma unica sala de servidores; ela e composta por multiplos datacenters distribuidos geograficamente.', 3),
  ('74000000-0000-4000-8000-000000000324', '63000000-0000-4000-8000-000000000081', 'Uma rede social exclusiva para desenvolvedores trocarem experiencias sobre o uso do Azure.', false, 'Incorreta. Uma rede social para desenvolvedores nao tem qualquer relacao com o conceito de regiao na infraestrutura fisica do Azure.', 4),
  ('74000000-0000-4000-8000-000000000325', '63000000-0000-4000-8000-000000000082', 'Um recurso exclusivo de armazenamento de arquivos, sem qualquer relacao com a infraestrutura fisica do Azure.', false, 'Incorreta. Zonas de disponibilidade nao sao um recurso de armazenamento; elas fazem parte da infraestrutura fisica de datacenters do Azure.', 1),
  ('74000000-0000-4000-8000-000000000326', '63000000-0000-4000-8000-000000000082', 'Locais fisicos unicos e isolados dentro de uma regiao, cada um com energia, refrigeracao e rede independentes, protegendo contra falhas localizadas.', true, 'Correta. Zonas de disponibilidade sao locais fisicos distintos dentro de uma regiao, cada um com infraestrutura independente, protegendo contra falhas localizadas.', 2),
  ('74000000-0000-4000-8000-000000000327', '63000000-0000-4000-8000-000000000082', 'Uma ferramenta de linha de comando utilizada para gerenciar recursos dentro de uma unica regiao.', false, 'Incorreta. Zonas de disponibilidade nao sao uma ferramenta de linha de comando; sao um conceito de infraestrutura fisica do Azure.', 3),
  ('74000000-0000-4000-8000-000000000328', '63000000-0000-4000-8000-000000000082', 'Um conjunto de politicas de seguranca aplicadas exclusivamente a contas de usuario administrativas.', false, 'Incorreta. Zonas de disponibilidade nao estao relacionadas a politicas de seguranca de contas de usuario; sao um conceito de infraestrutura fisica.', 4),
  ('74000000-0000-4000-8000-000000000329', '63000000-0000-4000-8000-000000000083', 'Duas regioes escolhidas aleatoriamente pelo cliente, sem qualquer criterio geografico ou tecnico definido pela Microsoft.', false, 'Incorreta. Pares de regioes nao sao escolhidos aleatoriamente pelo cliente; sao definidos previamente pela Microsoft, geralmente dentro da mesma geografia.', 1),
  ('74000000-0000-4000-8000-000000000330', '63000000-0000-4000-8000-000000000083', 'Um par de contas de usuario administrativas criadas exclusivamente para gerenciar uma regiao especifica.', false, 'Incorreta. Um par de regioes nao esta relacionado a contas de usuario administrativas; e um conceito de infraestrutura geografica do Azure.', 2),
  ('74000000-0000-4000-8000-000000000331', '63000000-0000-4000-8000-000000000083', 'Duas regioes dentro da mesma geografia, associadas pela Microsoft, geralmente utilizadas para replicacao de dados e recuperacao de desastres.', true, 'Correta. Pares de regioes sao duas regioes dentro da mesma geografia, associadas pela Microsoft, frequentemente utilizadas para replicacao de dados entre regioes.', 3),
  ('74000000-0000-4000-8000-000000000332', '63000000-0000-4000-8000-000000000083', 'Um conjunto de duas maquinas virtuais localizadas na mesma zona de disponibilidade.', false, 'Incorreta. Um par de regioes refere-se a duas regioes geograficas distintas, e nao a duas maquinas virtuais na mesma zona de disponibilidade.', 4),
  ('74000000-0000-4000-8000-000000000333', '63000000-0000-4000-8000-000000000084', 'A concentracao de toda a aplicacao em um unico datacenter, priorizando a simplicidade da arquitetura.', false, 'Incorreta. Concentrar a aplicacao em um unico datacenter aumenta, e nao reduz, o risco de indisponibilidade em caso de falha localizada.', 1),
  ('74000000-0000-4000-8000-000000000334', '63000000-0000-4000-8000-000000000084', 'A criacao de uma nova regiao geografica exclusiva, construida especificamente para essa aplicacao pela propria empresa.', false, 'Incorreta. Empresas clientes nao constroem novas regioes geograficas exclusivas; as regioes sao infraestrutura fornecida pela Microsoft.', 2),
  ('74000000-0000-4000-8000-000000000335', '63000000-0000-4000-8000-000000000084', 'A reducao do numero de usuarios que podem acessar a aplicacao simultaneamente, para simplificar sua arquitetura.', false, 'Incorreta. Reduzir o numero de usuarios nao aumenta a resiliencia da aplicacao contra a falha de um datacenter especifico.', 3),
  ('74000000-0000-4000-8000-000000000336', '63000000-0000-4000-8000-000000000084', 'A utilizacao de multiplas zonas de disponibilidade dentro da mesma regiao, distribuindo a aplicacao entre locais fisicos distintos com infraestrutura independente.', true, 'Correta. Distribuir a aplicacao entre multiplas zonas de disponibilidade dentro da mesma regiao protege contra a falha de um unico datacenter, sem exigir distribuicao entre regioes distantes.', 4),
  ('74000000-0000-4000-8000-000000000337', '63000000-0000-4000-8000-000000000085', 'A escolha cuidadosa da regiao do Azure onde os recursos serao hospedados, considerando a proximidade geografica com os clientes europeus.', true, 'Correta. Escolher uma regiao do Azure geograficamente proxima aos clientes europeus ajuda a atender requisitos de latencia e, possivelmente, de residencia de dados.', 1),
  ('74000000-0000-4000-8000-000000000338', '63000000-0000-4000-8000-000000000085', 'A escolha do idioma padrao configurado no portal do Azure utilizado pela equipe de TI da organizacao.', false, 'Incorreta. O idioma configurado no portal do Azure para a equipe de TI nao tem relacao com a localizacao fisica dos dados dos clientes.', 2),
  ('74000000-0000-4000-8000-000000000339', '63000000-0000-4000-8000-000000000085', 'A quantidade de licencas de software adquiridas pela organizacao para seus funcionarios internos.', false, 'Incorreta. A quantidade de licencas de software para funcionarios internos nao esta relacionada a proximidade geografica dos dados dos clientes.', 3),
  ('74000000-0000-4000-8000-000000000340', '63000000-0000-4000-8000-000000000085', 'O numero de contas de e-mail corporativo criadas para a equipe de suporte ao cliente.', false, 'Incorreta. O numero de contas de e-mail da equipe de suporte nao tem relacao com a decisao de onde hospedar os dados dos clientes.', 4),
  ('74000000-0000-4000-8000-000000000341', '63000000-0000-4000-8000-000000000086', 'A utilizacao exclusiva de uma unica zona de disponibilidade dentro de uma unica regiao, sem qualquer replicacao adicional.', false, 'Incorreta. Uma unica zona de disponibilidade dentro de uma unica regiao nao protege contra uma falha que afete toda a regiao.', 1),
  ('74000000-0000-4000-8000-000000000342', '63000000-0000-4000-8000-000000000086', 'O uso de pares de regioes (region pairs), que permitem estrategias de replicacao de dados entre regioes distintas dentro da mesma geografia.', true, 'Correta. O uso de pares de regioes permite estrategias de replicacao de dados entre regioes distintas, apoiando planos de recuperacao de desastres em caso de falha regional.', 2),
  ('74000000-0000-4000-8000-000000000343', '63000000-0000-4000-8000-000000000086', 'A reducao do numero de datacenters utilizados pela aplicacao, para simplificar a estrategia de recuperacao de desastres.', false, 'Incorreta. Reduzir o numero de datacenters utilizados nao contribui para uma estrategia robusta de recuperacao de desastres entre regioes.', 3),
  ('74000000-0000-4000-8000-000000000344', '63000000-0000-4000-8000-000000000086', 'A escolha de um unico fornecedor de energia eletrica para todos os datacenters utilizados pela aplicacao.', false, 'Incorreta. A escolha de um fornecedor de energia eletrica nao e um conceito relevante para a estrategia de recuperacao de desastres entre regioes do Azure.', 4),
  ('74000000-0000-4000-8000-000000000345', '63000000-0000-4000-8000-000000000087', 'As duas abordagens oferecem exatamente o mesmo tipo e nivel de protecao contra qualquer tipo de falha, sem qualquer diferenca relevante.', false, 'Incorreta. As duas abordagens protegem contra tipos diferentes de falha, nao oferecendo exatamente o mesmo nivel e tipo de protecao.', 1),
  ('74000000-0000-4000-8000-000000000346', '63000000-0000-4000-8000-000000000087', 'A distribuicao entre regioes geograficas distintas nunca oferece qualquer beneficio adicional em comparacao a distribuicao entre zonas de disponibilidade.', false, 'Incorreta. A distribuicao entre regioes oferece um beneficio adicional relevante: protecao contra falhas que afetem uma regiao inteira, o que zonas de disponibilidade sozinhas nao cobrem.', 2),
  ('74000000-0000-4000-8000-000000000347', '63000000-0000-4000-8000-000000000087', 'A distribuicao entre zonas de disponibilidade protege principalmente contra falhas localizadas em um unico datacenter, enquanto a distribuicao entre regioes protege tambem contra falhas que afetem uma regiao inteira, como desastres naturais.', true, 'Correta. Zonas de disponibilidade protegem contra falhas localizadas em um datacenter, enquanto a distribuicao entre regioes protege tambem contra falhas regionais completas.', 3),
  ('74000000-0000-4000-8000-000000000348', '63000000-0000-4000-8000-000000000087', 'Apenas a distribuicao entre zonas de disponibilidade e reconhecida como uma pratica valida pela Microsoft, sendo a distribuicao entre regioes desnecessaria.', false, 'Incorreta. A distribuicao entre regioes e uma pratica reconhecida e recomendada pela Microsoft para cenarios que exigem protecao contra falhas regionais completas.', 4),
  ('74000000-0000-4000-8000-000000000349', '63000000-0000-4000-8000-000000000088', 'A escolha do tema visual (claro ou escuro) utilizado pela equipe de TI no portal do Azure.', false, 'Incorreta. O tema visual do portal utilizado pela equipe de TI nao tem qualquer relacao com a localizacao fisica de armazenamento dos dados.', 1),
  ('74000000-0000-4000-8000-000000000350', '63000000-0000-4000-8000-000000000088', 'O numero de administradores cadastrados na assinatura do Azure utilizada pela empresa.', false, 'Incorreta. O numero de administradores cadastrados na assinatura nao esta relacionado a exigencia de residencia de dados dentro de uma geografia especifica.', 2),
  ('74000000-0000-4000-8000-000000000351', '63000000-0000-4000-8000-000000000088', 'A quantidade de licencas de software adquiridas para os computadores dos funcionarios da empresa.', false, 'Incorreta. A quantidade de licencas de software para os computadores dos funcionarios nao tem relacao com a localizacao fisica de armazenamento dos dados.', 3),
  ('74000000-0000-4000-8000-000000000352', '63000000-0000-4000-8000-000000000088', 'A escolha cuidadosa da regiao do Azure onde os dados serao armazenados, garantindo que ela esteja localizada dentro da geografia exigida pela legislacao aplicavel.', true, 'Correta. Escolher cuidadosamente a regiao do Azure, garantindo que esteja dentro da geografia exigida pela legislacao, e a decisao mais relevante para atender requisitos de residencia de dados.', 4),
  ('74000000-0000-4000-8000-000000000353', '63000000-0000-4000-8000-000000000089', 'A empresa deve avaliar o nivel de risco que esta disposta a tolerar: multiplas zonas de disponibilidade protegem contra falhas de um unico datacenter, enquanto multiplas regioes protegem tambem contra falhas regionais completas, cada opcao envolvendo diferentes niveis de complexidade e custo.', true, 'Correta. A escolha deve considerar o nivel de risco tolerado, os beneficios de resiliencia de cada abordagem e a complexidade e o custo associados a cada uma delas.', 1),
  ('74000000-0000-4000-8000-000000000354', '63000000-0000-4000-8000-000000000089', 'A opcao de hospedar em uma unica zona de disponibilidade e sempre suficiente para qualquer aplicacao critica, independentemente do nivel de risco tolerado pela empresa.', false, 'Incorreta. Uma unica zona de disponibilidade representa um ponto de falha localizado, o que pode nao ser adequado para uma aplicacao financeira critica com baixa tolerancia a risco.', 2),
  ('74000000-0000-4000-8000-000000000355', '63000000-0000-4000-8000-000000000089', 'A distribuicao entre multiplas regioes geograficas distintas deve ser sempre evitada, independentemente do nivel de criticidade da aplicacao financeira.', false, 'Incorreta. Para aplicacoes criticas com baixa tolerancia a risco, a distribuicao entre multiplas regioes pode ser justamente a opcao mais adequada, e nao algo a ser sempre evitado.', 3),
  ('74000000-0000-4000-8000-000000000356', '63000000-0000-4000-8000-000000000089', 'A decisao deve ser tomada exclusivamente com base no numero de funcionarios que compoem a equipe de desenvolvimento da aplicacao.', false, 'Incorreta. O numero de funcionarios da equipe de desenvolvimento nao e o criterio tecnico relevante para essa decisao de arquitetura de resiliencia.', 4),
  ('74000000-0000-4000-8000-000000000357', '63000000-0000-4000-8000-000000000090', 'Nao ha qualquer consideracao adicional a se fazer, ja que qualquer combinacao de regioes do Azure e sempre equivalente para fins de recuperacao de desastres.', false, 'Incorreta. Nem toda combinacao de regioes oferece as mesmas garantias e recursos de recuperacao de desastres associados aos pares de regioes oficiais definidos pela Microsoft.', 1),
  ('74000000-0000-4000-8000-000000000358', '63000000-0000-4000-8000-000000000090', 'A equipe deve verificar se determinados recursos e garantias de recuperacao de desastres associados a pares de regioes oficiais, definidos pela Microsoft, estarao disponiveis ou nao para essa combinacao especifica de regioes escolhida.', true, 'Correta. E importante verificar se recursos e garantias associados a pares de regioes oficiais estarao disponiveis para a combinacao especifica de regioes escolhida pela equipe.', 2),
  ('74000000-0000-4000-8000-000000000359', '63000000-0000-4000-8000-000000000090', 'A unica consideracao relevante e o custo de licenciamento de software utilizado pela aplicacao, sem qualquer relacao com a escolha das regioes.', false, 'Incorreta. O custo de licenciamento de software nao e a consideracao central relacionada a escolha de regioes para fins de recuperacao de desastres.', 3),
  ('74000000-0000-4000-8000-000000000360', '63000000-0000-4000-8000-000000000090', 'A equipe deve automaticamente cancelar a decisao, ja que o Azure nunca permite distribuir aplicacoes entre regioes que nao formam um par oficial.', false, 'Incorreta. O Azure permite distribuir aplicacoes entre diversas combinacoes de regioes; a questao esta em avaliar quais garantias especificas estarao disponiveis nessa escolha.', 4),
  ('74000000-0000-4000-8000-000000000361', '63000000-0000-4000-8000-000000000091', 'Um servico exclusivo para criacao de maquinas virtuais com sistema operacional Linux.', false, 'Incorreta. Criacao de maquinas virtuais Linux e funcao de outros servicos de computo, nao do Azure DNS, que e voltado a resolucao de nomes.', 1),
  ('74000000-0000-4000-8000-000000000362', '63000000-0000-4000-8000-000000000091', 'Uma ferramenta de design grafico para criacao de sites institucionais.', false, 'Incorreta. O Azure DNS nao e uma ferramenta de design grafico; ele e um servico de hospedagem e resolucao de nomes de dominio.', 2),
  ('74000000-0000-4000-8000-000000000363', '63000000-0000-4000-8000-000000000091', 'Um servico de hospedagem de dominios que permite hospedar e gerenciar registros DNS utilizando a infraestrutura do Azure.', true, 'Correta. O Azure DNS e um servico de hospedagem de dominios que permite gerenciar registros DNS utilizando a infraestrutura global do Azure.', 3),
  ('74000000-0000-4000-8000-000000000364', '63000000-0000-4000-8000-000000000091', 'Um aplicativo de videoconferencia disponivel exclusivamente para clientes corporativos.', false, 'Incorreta. O Azure DNS nao e um aplicativo de videoconferencia; ele e um servico relacionado a resolucao de nomes de dominio.', 4),
  ('74000000-0000-4000-8000-000000000365', '63000000-0000-4000-8000-000000000092', 'Armazenar backups completos de bancos de dados relacionais utilizados por aplicacoes web.', false, 'Incorreta. Armazenamento de backups de bancos de dados nao e a funcao de um sistema DNS, que e voltado a resolucao de nomes.', 1),
  ('74000000-0000-4000-8000-000000000366', '63000000-0000-4000-8000-000000000092', 'Criptografar todo o trafego de rede entre dois servidores localizados em regioes diferentes.', false, 'Incorreta. Criptografia de trafego de rede e uma funcao diferente, relacionada a seguranca de rede, e nao a funcao basica de um sistema DNS.', 2),
  ('74000000-0000-4000-8000-000000000367', '63000000-0000-4000-8000-000000000092', 'Gerenciar exclusivamente as permissoes de acesso de usuarios a arquivos armazenados na nuvem.', false, 'Incorreta. Gerenciamento de permissoes de acesso a arquivos e uma funcao de servicos de armazenamento e identidade, nao do DNS.', 3),
  ('74000000-0000-4000-8000-000000000368', '63000000-0000-4000-8000-000000000092', 'Traduzir nomes de dominio amigaveis, como exemplo.com, em enderecos IP que os computadores utilizam para se comunicar na rede.', true, 'Correta. A funcao basica de um sistema DNS e traduzir nomes de dominio amigaveis em enderecos IP utilizados na comunicacao de rede.', 4),
  ('74000000-0000-4000-8000-000000000369', '63000000-0000-4000-8000-000000000093', 'A possibilidade de gerenciar os registros DNS utilizando as mesmas ferramentas, credenciais e faturamento ja utilizados para outros recursos do Azure.', true, 'Correta. Utilizar o Azure DNS permite gerenciar os registros DNS de forma integrada as ferramentas, credenciais e faturamento ja utilizados para outros recursos do Azure.', 1),
  ('74000000-0000-4000-8000-000000000370', '63000000-0000-4000-8000-000000000093', 'A eliminacao completa da necessidade de qualquer tipo de nome de dominio para acessar aplicacoes web.', false, 'Incorreta. O Azure DNS nao elimina a necessidade de nomes de dominio; pelo contrario, ele e utilizado justamente para gerenciar esses nomes.', 2),
  ('74000000-0000-4000-8000-000000000371', '63000000-0000-4000-8000-000000000093', 'A garantia de que o dominio da organizacao nunca podera ser transferido para outro provedor no futuro.', false, 'Incorreta. E possivel, em geral, transferir a gestao de um dominio entre diferentes provedores, incluindo o Azure DNS, conforme as politicas aplicaveis.', 3),
  ('74000000-0000-4000-8000-000000000372', '63000000-0000-4000-8000-000000000093', 'A eliminacao total da necessidade de qualquer configuracao de rede para aplicacoes hospedadas no Azure.', false, 'Incorreta. O Azure DNS nao elimina a necessidade de configuracao de rede; ele e um componente especifico relacionado a resolucao de nomes.', 4),
  ('74000000-0000-4000-8000-000000000373', '63000000-0000-4000-8000-000000000094', 'Azure Files, pois permite compartilhar arquivos entre diferentes servidores da aplicacao.', false, 'Incorreta. Azure Files e um servico de armazenamento de arquivos, sem relacao direta com a resolucao de nomes de dominio.', 1),
  ('74000000-0000-4000-8000-000000000374', '63000000-0000-4000-8000-000000000094', 'Azure DNS, pois permite hospedar e gerenciar os registros de dominio, direcionando o nome amigavel do site para o endereco IP correto da aplicacao no Azure.', true, 'Correta. O Azure DNS permite gerenciar os registros de dominio, garantindo que o nome amigavel do site direcione corretamente para o endereco IP da aplicacao.', 2),
  ('74000000-0000-4000-8000-000000000375', '63000000-0000-4000-8000-000000000094', 'Azure Functions, pois permite executar pequenos trechos de codigo sem gerenciar servidores.', false, 'Incorreta. Azure Functions e um servico de computacao serverless, sem relacao direta com a configuracao de registros de dominio.', 3),
  ('74000000-0000-4000-8000-000000000376', '63000000-0000-4000-8000-000000000094', 'Azure Advisor, pois oferece recomendacoes personalizadas sobre custo e seguranca dos recursos.', false, 'Incorreta. Azure Advisor e uma ferramenta de recomendacoes, sem relacao direta com a configuracao de registros DNS de um dominio.', 4),
  ('74000000-0000-4000-8000-000000000377', '63000000-0000-4000-8000-000000000095', 'Criar um unico registro DNS generico, que direcione automaticamente todos os subdominios para o mesmo endereco IP, independentemente do servico.', false, 'Incorreta. Direcionar todos os subdominios para o mesmo endereco IP, independentemente do servico, nao atenderia a necessidade de apontar para servicos diferentes.', 1),
  ('74000000-0000-4000-8000-000000000378', '63000000-0000-4000-8000-000000000095', 'Eliminar completamente o uso de subdominios, utilizando apenas o dominio principal para todos os servicos da empresa.', false, 'Incorreta. Eliminar os subdominios nao atende a necessidade de organizar diferentes servicos sob nomes distintos e reconheciveis.', 2),
  ('74000000-0000-4000-8000-000000000379', '63000000-0000-4000-8000-000000000095', 'Criar registros DNS especificos para cada subdominio dentro da zona DNS gerenciada pelo Azure DNS, direcionando cada um deles para o servico correspondente.', true, 'Correta. Criar registros DNS especificos para cada subdominio permite direcionar cada um deles corretamente para o servico correspondente no Azure.', 3),
  ('74000000-0000-4000-8000-000000000380', '63000000-0000-4000-8000-000000000095', 'Contratar um dominio completamente separado e independente para cada subdominio existente na empresa.', false, 'Incorreta. Contratar dominios completamente separados para cada subdominio e desnecessario, ja que o Azure DNS permite gerenciar subdominios dentro da mesma zona.', 4),
  ('74000000-0000-4000-8000-000000000381', '63000000-0000-4000-8000-000000000096', 'Um erro permanente e irreversivel na configuracao do Azure DNS, que nunca sera corrigido automaticamente.', false, 'Incorreta. O comportamento descrito e temporario e esperado, relacionado ao tempo de propagacao do DNS, e nao um erro permanente e irreversivel.', 1),
  ('74000000-0000-4000-8000-000000000382', '63000000-0000-4000-8000-000000000096', 'Uma falha de seguranca no Azure DNS, que expoe indevidamente o endereco IP antigo da aplicacao aos usuarios.', false, 'Incorreta. O comportamento descrito nao e uma falha de seguranca; e um efeito esperado do funcionamento de cache do sistema DNS.', 2),
  ('74000000-0000-4000-8000-000000000383', '63000000-0000-4000-8000-000000000096', 'Um problema exclusivo de conexao de internet dos usuarios afetados, sem qualquer relacao com o funcionamento do DNS.', false, 'Incorreta. O comportamento esta diretamente relacionado ao funcionamento do DNS e ao tempo de cache dos registros, e nao apenas a conexao de internet dos usuarios.', 3),
  ('74000000-0000-4000-8000-000000000384', '63000000-0000-4000-8000-000000000096', 'O tempo de vida (TTL) dos registros DNS em cache, que faz com que sistemas e provedores de internet armazenem temporariamente a resolucao antiga ate que o cache expire.', true, 'Correta. O tempo de vida (TTL) dos registros DNS em cache explica por que alguns usuarios podem continuar sendo direcionados temporariamente para o endereco IP antigo apos uma alteracao.', 4),
  ('74000000-0000-4000-8000-000000000385', '63000000-0000-4000-8000-000000000097', 'Utilizar o Azure DNS pode oferecer maior integracao com outras ferramentas e recursos do Azure, como faturamento e controle de acesso unificados, em comparacao a depender de um provedor de DNS completamente externo.', true, 'Correta. O Azure DNS pode oferecer maior integracao com outras ferramentas do Azure, como faturamento e controle de acesso, em comparacao a um provedor externo separado.', 1),
  ('74000000-0000-4000-8000-000000000386', '63000000-0000-4000-8000-000000000097', 'O uso de um provedor de DNS externo e sempre obrigatorio, sendo tecnicamente impossivel hospedar registros de dominio dentro do proprio Azure.', false, 'Incorreta. Nao ha impedimento tecnico; o Azure DNS permite hospedar registros de dominio diretamente dentro do proprio Azure.', 2),
  ('74000000-0000-4000-8000-000000000387', '63000000-0000-4000-8000-000000000097', 'Nao ha qualquer diferenca pratica entre utilizar o Azure DNS ou um provedor de DNS externo, independentemente do cenario.', false, 'Incorreta. Ha diferencas praticas relevantes, especialmente em relacao a integracao com outras ferramentas e processos do Azure.', 3),
  ('74000000-0000-4000-8000-000000000388', '63000000-0000-4000-8000-000000000097', 'Um provedor de DNS externo sempre oferece melhor desempenho de resolucao de nomes do que o Azure DNS, em qualquer cenario.', false, 'Incorreta. Nao e correto afirmar que um provedor externo sempre oferece melhor desempenho; isso depende de diversos fatores especificos de cada provedor.', 4),
  ('74000000-0000-4000-8000-000000000389', '63000000-0000-4000-8000-000000000098', 'A alteracao do nome de exibicao da assinatura do Azure para o nome exato do dominio a ser verificado.', false, 'Incorreta. Alterar o nome de exibicao da assinatura do Azure nao tem relacao com a comprovacao de propriedade de um dominio perante um servico externo.', 1),
  ('74000000-0000-4000-8000-000000000390', '63000000-0000-4000-8000-000000000098', 'A criacao de um registro DNS do tipo TXT, contendo um valor especifico fornecido pelo servico externo, que comprova o controle sobre o dominio.', true, 'Correta. Registros DNS do tipo TXT, contendo um valor especifico fornecido pelo servico externo, sao comumente utilizados para comprovar a propriedade e o controle sobre um dominio.', 2),
  ('74000000-0000-4000-8000-000000000391', '63000000-0000-4000-8000-000000000098', 'A criacao de uma nova maquina virtual, nomeada exatamente como o dominio que se deseja verificar.', false, 'Incorreta. Criar uma maquina virtual com o nome do dominio nao comprova a propriedade do dominio perante servicos externos.', 3),
  ('74000000-0000-4000-8000-000000000392', '63000000-0000-4000-8000-000000000098', 'O envio de um e-mail para o suporte da Microsoft solicitando a verificacao manual do dominio pela propria empresa.', false, 'Incorreta. A verificacao de propriedade de dominio geralmente e feita por meio de registros DNS especificos, e nao por solicitacao manual de e-mail ao suporte.', 4),
  ('74000000-0000-4000-8000-000000000393', '63000000-0000-4000-8000-000000000099', 'Alterar todos os registros DNS de uma unica vez, sem qualquer planejamento previo, confiando que a transicao ocorrera de forma instantanea e sem impacto.', false, 'Incorreta. Alterar tudo de uma vez, sem planejamento, ignora o efeito do tempo de propagacao do DNS e pode causar inconsistencias temporarias para os usuarios.', 1),
  ('74000000-0000-4000-8000-000000000394', '63000000-0000-4000-8000-000000000099', 'Desativar completamente o acesso dos usuarios aos servicos online durante todo o periodo de migracao, independentemente da duracao necessaria.', false, 'Incorreta. Desativar completamente o acesso dos usuarios e uma medida extrema e desnecessaria diante de um planejamento adequado de migracao de DNS.', 2),
  ('74000000-0000-4000-8000-000000000395', '63000000-0000-4000-8000-000000000099', 'Planejar a migracao considerando o tempo de vida (TTL) dos registros DNS existentes, reduzindo-o previamente para acelerar a propagacao, e validando cuidadosamente os novos registros no Azure DNS antes de finalizar a transicao.', true, 'Correta. Planejar a migracao considerando o TTL dos registros e validando cuidadosamente os novos registros antes da transicao final e a abordagem mais adequada para minimizar impactos.', 3),
  ('74000000-0000-4000-8000-000000000396', '63000000-0000-4000-8000-000000000099', 'Ignorar completamente qualquer teste previo dos novos registros DNS, aplicando as alteracoes diretamente em producao sem validacao.', false, 'Incorreta. Ignorar testes previos aumenta significativamente o risco de erros de configuracao impactarem os usuarios durante a migracao.', 4),
  ('74000000-0000-4000-8000-000000000397', '63000000-0000-4000-8000-000000000100', 'A correcao aplicada pela equipe de TI foi tecnicamente invalida, mesmo que parecesse correta no momento da alteracao.', false, 'Incorreta. O cenario nao indica que a correcao foi tecnicamente invalida; o problema esta relacionado ao comportamento de cache do sistema DNS.', 1),
  ('74000000-0000-4000-8000-000000000398', '63000000-0000-4000-8000-000000000100', 'O Azure DNS possui uma falha estrutural permanente que impede corrigir registros incorretos de forma definitiva em qualquer cenario.', false, 'Incorreta. Nao ha uma falha estrutural permanente do Azure DNS que impeca correcoes; o comportamento observado esta relacionado ao cache e ao TTL configurado.', 2),
  ('74000000-0000-4000-8000-000000000399', '63000000-0000-4000-8000-000000000100', 'A persistencia do problema nao tem qualquer relacao com o funcionamento do sistema DNS, sendo causada exclusivamente pela conexao de internet dos usuarios.', false, 'Incorreta. A persistencia do problema esta diretamente relacionada ao funcionamento do DNS e ao tempo de cache, e nao apenas a conexao de internet dos usuarios.', 3),
  ('74000000-0000-4000-8000-000000000400', '63000000-0000-4000-8000-000000000100', 'O tempo de vida (TTL) configurado previamente para o registro DNS incorreto pode ter feito com que sistemas e provedores de internet mantivessem em cache a informacao incorreta por um periodo, mesmo apos a correcao ser aplicada no Azure DNS.', true, 'Correta. O TTL configurado previamente pode fazer com que a informacao incorreta permaneca em cache por um periodo, mesmo apos a correcao ser aplicada.', 4),
  ('74000000-0000-4000-8000-000000000401', '63000000-0000-4000-8000-000000000101', 'Um servico de compartilhamento de arquivos totalmente gerenciado na nuvem, acessivel por meio do protocolo SMB, entre outros, a partir de diferentes locais.', true, 'Correta. O Azure Files e um servico de compartilhamento de arquivos totalmente gerenciado, acessivel via protocolos como SMB a partir de diferentes locais e sistemas.', 1),
  ('74000000-0000-4000-8000-000000000402', '63000000-0000-4000-8000-000000000101', 'Uma ferramenta de linha de comando exclusiva para criar maquinas virtuais no Azure.', false, 'Incorreta. Criacao de maquinas virtuais via linha de comando e funcao do Azure CLI, nao do Azure Files, que e um servico de armazenamento de arquivos.', 2),
  ('74000000-0000-4000-8000-000000000403', '63000000-0000-4000-8000-000000000101', 'Um servico de monitoramento de desempenho de aplicacoes hospedadas no Azure.', false, 'Incorreta. Monitoramento de desempenho de aplicacoes e funcao do Application Insights, nao do Azure Files.', 3),
  ('74000000-0000-4000-8000-000000000404', '63000000-0000-4000-8000-000000000101', 'Um aplicativo de videoconferencia integrado ao portal de gerenciamento do Azure.', false, 'Incorreta. O Azure Files nao e um aplicativo de videoconferencia; e um servico de armazenamento de arquivos compartilhados.', 4),
  ('74000000-0000-4000-8000-000000000405', '63000000-0000-4000-8000-000000000102', 'Um protocolo exclusivo e proprietario, criado especificamente pela Microsoft, sem qualquer compatibilidade com sistemas operacionais tradicionais.', false, 'Incorreta. O Azure Files utiliza protocolos amplamente conhecidos e compativeis com sistemas operacionais tradicionais, nao um protocolo exclusivo incompativel.', 1),
  ('74000000-0000-4000-8000-000000000406', '63000000-0000-4000-8000-000000000102', 'O protocolo SMB (Server Message Block), amplamente utilizado e compativel com sistemas operacionais Windows, Linux e macOS.', true, 'Correta. O Azure Files utiliza o protocolo SMB, amplamente compativel com diferentes sistemas operacionais, para acessar os compartilhamentos de arquivos.', 2),
  ('74000000-0000-4000-8000-000000000407', '63000000-0000-4000-8000-000000000102', 'Um protocolo utilizado exclusivamente para transmissao de video em tempo real entre servidores.', false, 'Incorreta. Protocolos de transmissao de video em tempo real nao sao a forma padrao de acessar compartilhamentos de arquivos do Azure Files.', 3),
  ('74000000-0000-4000-8000-000000000408', '63000000-0000-4000-8000-000000000102', 'Um protocolo utilizado exclusivamente para envio de mensagens instantaneas entre usuarios corporativos.', false, 'Incorreta. Protocolos de mensagens instantaneas nao tem relacao com o acesso a compartilhamentos de arquivos do Azure Files.', 4),
  ('74000000-0000-4000-8000-000000000409', '63000000-0000-4000-8000-000000000103', 'Substituir completamente qualquer necessidade de banco de dados relacional utilizado pela aplicacao.', false, 'Incorreta. Substituir bancos de dados relacionais nao e a funcao do Azure Files, que e voltado ao compartilhamento de arquivos, nao ao armazenamento estruturado de dados relacionais.', 1),
  ('74000000-0000-4000-8000-000000000410', '63000000-0000-4000-8000-000000000103', 'Hospedar exclusivamente paginas web estaticas sem qualquer necessidade de compartilhamento entre servidores.', false, 'Incorreta. Hospedagem de paginas web estaticas e mais tipicamente associada a outros servicos, e nao ao proposito principal do Azure Files.', 2),
  ('74000000-0000-4000-8000-000000000411', '63000000-0000-4000-8000-000000000103', 'Compartilhar arquivos entre multiplas maquinas virtuais ou servidores on-premises, substituindo servidores de arquivos tradicionais mantidos localmente.', true, 'Correta. Um cenario tipico do Azure Files e substituir servidores de arquivos tradicionais, permitindo compartilhamento de arquivos entre multiplas maquinas.', 3),
  ('74000000-0000-4000-8000-000000000412', '63000000-0000-4000-8000-000000000103', 'Executar exclusivamente pequenos trechos de codigo sem gerenciamento de servidores, como no modelo serverless.', false, 'Incorreta. Executar codigo sem gerenciar servidores e a funcao do Azure Functions, e nao do Azure Files.', 4),
  ('74000000-0000-4000-8000-000000000413', '63000000-0000-4000-8000-000000000104', 'Azure Functions, pois permite executar codigo sob demanda sem gerenciar servidores.', false, 'Incorreta. Azure Functions e um servico de computacao serverless, sem relacao direta com compartilhamento de arquivos entre computadores dos funcionarios.', 1),
  ('74000000-0000-4000-8000-000000000414', '63000000-0000-4000-8000-000000000104', 'Azure DNS, pois gerencia a resolucao de nomes de dominio para aplicacoes web hospedadas na nuvem.', false, 'Incorreta. Azure DNS e voltado a resolucao de nomes de dominio, sem relacao direta com compartilhamento de arquivos entre funcionarios.', 2),
  ('74000000-0000-4000-8000-000000000415', '63000000-0000-4000-8000-000000000104', 'Azure Advisor, pois oferece recomendacoes personalizadas sobre custo, seguranca e desempenho dos recursos.', false, 'Incorreta. Azure Advisor e uma ferramenta de recomendacoes, sem relacao direta com a funcionalidade de compartilhamento de arquivos.', 3),
  ('74000000-0000-4000-8000-000000000416', '63000000-0000-4000-8000-000000000104', 'Azure Files, pois oferece compartilhamento de arquivos totalmente gerenciado, compativel com o protocolo SMB amplamente utilizado por sistemas operacionais tradicionais.', true, 'Correta. O Azure Files oferece compartilhamento de arquivos totalmente gerenciado, compativel com o protocolo SMB, atendendo diretamente a necessidade de migracao descrita.', 4),
  ('74000000-0000-4000-8000-000000000417', '63000000-0000-4000-8000-000000000105', 'Criar um compartilhamento de arquivos no Azure Files e montar esse compartilhamento em todas as maquinas virtuais que precisam acessar os arquivos de configuracao, garantindo uma unica fonte de verdade.', true, 'Correta. Criar um compartilhamento de arquivos no Azure Files e monta-lo em todas as maquinas virtuais garante que todas acessem a mesma versao atualizada dos arquivos, evitando inconsistencias.', 1),
  ('74000000-0000-4000-8000-000000000418', '63000000-0000-4000-8000-000000000105', 'Copiar manualmente os arquivos de configuracao para cada maquina virtual individualmente, sempre que uma alteracao for necessaria.', false, 'Incorreta. Copiar manualmente os arquivos para cada maquina aumenta o risco de inconsistencias entre versoes diferentes dos arquivos em cada maquina.', 2),
  ('74000000-0000-4000-8000-000000000419', '63000000-0000-4000-8000-000000000105', 'Armazenar os arquivos de configuracao exclusivamente no disco local de uma unica maquina virtual, sem qualquer compartilhamento.', false, 'Incorreta. Armazenar os arquivos apenas no disco local de uma unica maquina impede que as demais maquinas acessem a mesma versao atualizada dos arquivos.', 3),
  ('74000000-0000-4000-8000-000000000420', '63000000-0000-4000-8000-000000000105', 'Enviar os arquivos de configuracao por e-mail para cada membro da equipe, sempre que houver uma alteracao necessaria.', false, 'Incorreta. Enviar arquivos por e-mail e um processo manual e propenso a erros, alem de nao garantir uma unica fonte de verdade atualizada.', 4),
  ('74000000-0000-4000-8000-000000000421', '63000000-0000-4000-8000-000000000106', 'A garantia de que os funcionarios nunca mais precisarao de treinamento para utilizar o novo sistema de arquivos.', false, 'Incorreta. Ainda pode ser necessario algum treinamento para os funcionarios se adaptarem a nova forma de acessar os arquivos, mesmo com o Azure Files.', 1),
  ('74000000-0000-4000-8000-000000000422', '63000000-0000-4000-8000-000000000106', 'A eliminacao da necessidade de gerenciar a infraestrutura fisica subjacente, ja que o Azure Files e um servico totalmente gerenciado pela Microsoft.', true, 'Correta. Como o Azure Files e um servico totalmente gerenciado, a empresa elimina a necessidade de gerenciar a infraestrutura fisica subjacente, reduzindo tarefas de manutencao.', 2),
  ('74000000-0000-4000-8000-000000000423', '63000000-0000-4000-8000-000000000106', 'A eliminacao total da necessidade de qualquer tipo de controle de acesso aos arquivos compartilhados.', false, 'Incorreta. O controle de acesso continua sendo necessario e configuravel no Azure Files, e nao e eliminado pelo uso do servico.', 3),
  ('74000000-0000-4000-8000-000000000424', '63000000-0000-4000-8000-000000000106', 'A garantia de que o custo mensal sera sempre zero, independentemente do volume de dados armazenados.', false, 'Incorreta. O Azure Files e um servico pago, com custos proporcionais ao volume de dados armazenados e utilizados, e nao gratuito.', 4),
  ('74000000-0000-4000-8000-000000000425', '63000000-0000-4000-8000-000000000107', 'Um disco gerenciado anexado a uma unica maquina virtual permite que multiplas maquinas acessem os mesmos arquivos simultaneamente, assim como o Azure Files.', false, 'Incorreta. Um disco gerenciado tradicional geralmente e anexado a uma unica maquina virtual por vez, nao permitindo acesso simultaneo por multiplas maquinas da mesma forma que o Azure Files.', 1),
  ('74000000-0000-4000-8000-000000000426', '63000000-0000-4000-8000-000000000107', 'Nao ha qualquer diferenca entre os dois servicos em relacao ao compartilhamento simultaneo de arquivos entre multiplas maquinas.', false, 'Incorreta. Ha uma diferenca relevante entre os dois servicos exatamente em relacao ao compartilhamento simultaneo entre multiplas maquinas.', 2),
  ('74000000-0000-4000-8000-000000000427', '63000000-0000-4000-8000-000000000107', 'O Azure Files foi projetado especificamente para permitir que multiplas maquinas acessem e compartilhem os mesmos arquivos simultaneamente, o que geralmente nao e o caso de um disco gerenciado tradicional anexado a uma unica maquina virtual.', true, 'Correta. O Azure Files foi projetado para compartilhamento simultaneo entre multiplas maquinas, diferente de um disco gerenciado tradicional, tipicamente anexado a uma unica maquina virtual.', 3),
  ('74000000-0000-4000-8000-000000000428', '63000000-0000-4000-8000-000000000107', 'Discos gerenciados sao sempre a opcao recomendada para qualquer cenario de compartilhamento de arquivos entre multiplas maquinas virtuais.', false, 'Incorreta. Para cenarios de compartilhamento entre multiplas maquinas, o Azure Files tende a ser mais adequado do que um disco gerenciado tradicional.', 4),
  ('74000000-0000-4000-8000-000000000429', '63000000-0000-4000-8000-000000000108', 'O Azure DNS, que gerencia exclusivamente a resolucao de nomes de dominio para aplicacoes web hospedadas na nuvem.', false, 'Incorreta. O Azure DNS e voltado a resolucao de nomes de dominio, sem qualquer relacao com backup e restauracao de arquivos.', 1),
  ('74000000-0000-4000-8000-000000000430', '63000000-0000-4000-8000-000000000108', 'O Azure Functions, que permite executar pequenos trechos de codigo em resposta a eventos especificos.', false, 'Incorreta. O Azure Functions e um servico de computacao serverless, sem relacao direta com backup e restauracao de arquivos compartilhados.', 2),
  ('74000000-0000-4000-8000-000000000431', '63000000-0000-4000-8000-000000000108', 'O Azure Advisor, que oferece recomendacoes personalizadas sobre custo, seguranca e desempenho dos recursos.', false, 'Incorreta. O Azure Advisor oferece recomendacoes gerais sobre os recursos, mas nao realiza diretamente copias de seguranca ou restauracao de arquivos.', 3),
  ('74000000-0000-4000-8000-000000000432', '63000000-0000-4000-8000-000000000108', 'O Azure Backup, que pode ser configurado para realizar copias de seguranca periodicas dos compartilhamentos do Azure Files, permitindo restaurar versoes anteriores dos arquivos quando necessario.', true, 'Correta. O Azure Backup pode ser configurado para realizar copias de seguranca periodicas dos compartilhamentos do Azure Files, permitindo restaurar versoes anteriores dos arquivos quando necessario.', 4),
  ('74000000-0000-4000-8000-000000000433', '63000000-0000-4000-8000-000000000109', 'A empresa deve considerar uma abordagem hibrida, com cache local sincronizado, especialmente se a conexao de internet do escritorio for limitada, avaliando o equilibrio entre simplicidade da migracao completa e desempenho percebido pelos funcionarios.', true, 'Correta. Diante de conexao de internet limitada, avaliar uma abordagem hibrida com cache local sincronizado pode equilibrar melhor simplicidade e desempenho percebido pelos funcionarios.', 1),
  ('74000000-0000-4000-8000-000000000434', '63000000-0000-4000-8000-000000000109', 'A migracao completa para o Azure Files e sempre a melhor opcao, independentemente da qualidade da conexao de internet disponivel no escritorio.', false, 'Incorreta. Em cenarios com conexao de internet limitada, uma migracao completa sem qualquer cache local pode gerar latencia perceptivel para os funcionarios ao acessar arquivos frequentemente utilizados.', 2),
  ('74000000-0000-4000-8000-000000000435', '63000000-0000-4000-8000-000000000109', 'Nenhuma das duas abordagens e viavel, sendo obrigatorio manter o servidor de arquivos totalmente on-premises, sem qualquer uso do Azure Files.', false, 'Incorreta. Manter o servidor totalmente on-premises nao e a unica opcao viavel; tanto a migracao completa quanto a abordagem hibrida sao possibilidades reais.', 3),
  ('74000000-0000-4000-8000-000000000436', '63000000-0000-4000-8000-000000000109', 'A decisao deve ser tomada exclusivamente com base na cor do logotipo da empresa, sem qualquer relacao com a qualidade da conexao de internet.', false, 'Incorreta. Aspectos esteticos como o logotipo da empresa nao tem qualquer relacao tecnica com essa decisao de arquitetura de armazenamento.', 4),
  ('74000000-0000-4000-8000-000000000437', '63000000-0000-4000-8000-000000000110', 'O Azure Files e uma tecnologia falha, que nunca deveria ser utilizada por nenhuma organizacao, independentemente do tipo de aplicativo envolvido.', false, 'Incorreta. O Azure Files funciona adequadamente para a grande maioria dos cenarios de compartilhamento de arquivos; o problema descrito e especifico de aplicativos legados com dependencias muito particulares.', 1),
  ('74000000-0000-4000-8000-000000000438', '63000000-0000-4000-8000-000000000110', 'E possivel que determinados aplicativos legados, dependentes de recursos muito especificos de sistemas de arquivos locais tradicionais, exijam avaliacao cuidadosa de compatibilidade antes da migracao, podendo necessitar de ajustes ou de uma abordagem alternativa para esses casos especificos.', true, 'Correta. Aplicativos legados com dependencias muito especificas podem exigir avaliacao cuidadosa de compatibilidade antes da migracao, podendo necessitar de ajustes ou solucoes alternativas para esses casos pontuais.', 2),
  ('74000000-0000-4000-8000-000000000439', '63000000-0000-4000-8000-000000000110', 'O problema ocorreu exclusivamente por uma falha de conexao de internet da organizacao, sem qualquer relacao com as caracteristicas dos aplicativos legados.', false, 'Incorreta. O cenario indica claramente que o problema esta relacionado a dependencias especificas dos aplicativos legados, e nao apenas a conexao de internet.', 3),
  ('74000000-0000-4000-8000-000000000440', '63000000-0000-4000-8000-000000000110', 'A unica solucao possivel e reverter completamente a migracao, retornando ao servidor de arquivos on-premises para toda a organizacao.', false, 'Incorreta. Reverter completamente a migracao para toda a organizacao e uma medida extrema; uma abordagem mais equilibrada seria avaliar solucoes especificas para os aplicativos legados afetados.', 4),
  ('74000000-0000-4000-8000-000000000441', '63000000-0000-4000-8000-000000000111', 'Um servico de armazenamento de arquivos compartilhados, acessivel por meio do protocolo SMB.', false, 'Incorreta. Armazenamento de arquivos compartilhados e a funcao do Azure Files, e nao do Azure Functions, que e um servico de computacao.', 1),
  ('74000000-0000-4000-8000-000000000442', '63000000-0000-4000-8000-000000000111', 'Uma ferramenta de design grafico para criacao de diagramas de fluxo de processos empresariais.', false, 'Incorreta. O Azure Functions nao e uma ferramenta de design grafico; e um servico de execucao de codigo sob demanda.', 2),
  ('74000000-0000-4000-8000-000000000443', '63000000-0000-4000-8000-000000000111', 'Um servico de computacao serverless que permite executar pequenos trechos de codigo em resposta a eventos, sem a necessidade de gerenciar servidores.', true, 'Correta. O Azure Functions e um servico de computacao serverless que executa codigo em resposta a eventos, sem exigir que o cliente gerencie servidores.', 3),
  ('74000000-0000-4000-8000-000000000444', '63000000-0000-4000-8000-000000000111', 'Um aplicativo de videoconferencia disponivel exclusivamente para desenvolvedores de software.', false, 'Incorreta. O Azure Functions nao e um aplicativo de videoconferencia; e um servico de computacao serverless para execucao de codigo.', 4),
  ('74000000-0000-4000-8000-000000000445', '63000000-0000-4000-8000-000000000112', 'Com base no numero de funcionarios que compoem a equipe de desenvolvimento da aplicacao.', false, 'Incorreta. O numero de funcionarios da equipe de desenvolvimento nao e o criterio utilizado para cobranca do Azure Functions.', 1),
  ('74000000-0000-4000-8000-000000000446', '63000000-0000-4000-8000-000000000112', 'Com uma taxa fixa unica, paga uma unica vez no momento da criacao da funcao, sem qualquer cobranca adicional posterior.', false, 'Incorreta. O modelo de consumo do Azure Functions nao envolve uma taxa fixa unica; a cobranca esta relacionada ao uso real ao longo do tempo.', 2),
  ('74000000-0000-4000-8000-000000000447', '63000000-0000-4000-8000-000000000112', 'Exclusivamente com base no numero de linhas de codigo escritas dentro da funcao criada.', false, 'Incorreta. O numero de linhas de codigo nao e o criterio de cobranca utilizado pelo Azure Functions.', 3),
  ('74000000-0000-4000-8000-000000000448', '63000000-0000-4000-8000-000000000112', 'Com base na execucao real das funcoes, considerando fatores como numero de execucoes e tempo de processamento, no modelo de consumo.', true, 'Correta. No modelo de consumo, o Azure Functions cobra com base na execucao real das funcoes, considerando numero de execucoes e tempo de processamento.', 4),
  ('74000000-0000-4000-8000-000000000449', '63000000-0000-4000-8000-000000000113', 'Uma requisicao HTTP recebida, a chegada de uma nova mensagem em uma fila ou a adicao de um novo arquivo em um servico de armazenamento.', true, 'Correta. Requisicoes HTTP, mensagens em filas e adicao de arquivos em armazenamento sao exemplos tipicos de gatilhos que podem acionar funcoes no Azure Functions.', 1),
  ('74000000-0000-4000-8000-000000000450', '63000000-0000-4000-8000-000000000113', 'A troca manual da senha de um usuario administrativo da assinatura do Azure.', false, 'Incorreta. A troca de senha de um usuario administrativo nao e um exemplo tipico de gatilho utilizado para acionar funcoes no Azure Functions.', 2),
  ('74000000-0000-4000-8000-000000000451', '63000000-0000-4000-8000-000000000113', 'A alteracao do nome de exibicao de um grupo de recursos dentro do portal do Azure.', false, 'Incorreta. Alterar o nome de exibicao de um grupo de recursos nao e um gatilho tipico utilizado para acionar funcoes no Azure Functions.', 3),
  ('74000000-0000-4000-8000-000000000452', '63000000-0000-4000-8000-000000000113', 'A instalacao de um novo sistema operacional em uma maquina virtual do Azure.', false, 'Incorreta. A instalacao de um sistema operacional em uma maquina virtual nao e um exemplo de gatilho relacionado ao Azure Functions.', 4),
  ('74000000-0000-4000-8000-000000000453', '63000000-0000-4000-8000-000000000114', 'Manter uma maquina virtual dedicada e sempre ligada, verificando continuamente se novos arquivos foram adicionados ao armazenamento.', false, 'Incorreta. Manter uma maquina virtual sempre ligada para verificar continuamente geraria custo desnecessario durante os longos periodos sem novos envios.', 1),
  ('74000000-0000-4000-8000-000000000454', '63000000-0000-4000-8000-000000000114', 'Criar uma funcao no Azure Functions configurada com um gatilho de armazenamento, que sera acionada automaticamente sempre que um novo arquivo for adicionado, processando a imagem apenas nesse momento.', true, 'Correta. Uma funcao com gatilho de armazenamento e acionada automaticamente apenas quando um novo arquivo e adicionado, atendendo diretamente ao cenario de eventos esporadicos.', 2),
  ('74000000-0000-4000-8000-000000000455', '63000000-0000-4000-8000-000000000114', 'Contratar uma equipe para verificar manualmente, a cada hora, se novos arquivos foram adicionados ao armazenamento.', false, 'Incorreta. Verificacao manual periodica e ineficiente e sujeita a atrasos, alem de nao aproveitar as capacidades de automacao do Azure Functions.', 3),
  ('74000000-0000-4000-8000-000000000456', '63000000-0000-4000-8000-000000000114', 'Construir um servidor fisico dedicado exclusivamente ao processamento de imagens enviadas pelos usuarios.', false, 'Incorreta. Construir um servidor fisico dedicado para uma funcao esporadica e imprevisivel seria um investimento desproporcional e ineficiente.', 4),
  ('74000000-0000-4000-8000-000000000457', '63000000-0000-4000-8000-000000000115', 'Criar e gerenciar manualmente uma maquina virtual dedicada exclusivamente para hospedar esse pequeno endpoint de API.', false, 'Incorreta. Criar e gerenciar uma maquina virtual dedicada contraria o objetivo de evitar a complexidade de gerenciamento de servidores para uma funcionalidade pequena e ocasional.', 1),
  ('74000000-0000-4000-8000-000000000458', '63000000-0000-4000-8000-000000000115', 'Construir um datacenter fisico proprio exclusivamente para hospedar esse pequeno endpoint de API.', false, 'Incorreta. Construir um datacenter fisico proprio e uma solucao extremamente desproporcional para um pequeno endpoint com trafego ocasional.', 2),
  ('74000000-0000-4000-8000-000000000459', '63000000-0000-4000-8000-000000000115', 'Utilizar o Azure Functions com um gatilho HTTP, permitindo que o codigo do endpoint seja executado automaticamente em resposta as requisicoes recebidas, sem a necessidade de gerenciar servidores.', true, 'Correta. Utilizar o Azure Functions com gatilho HTTP permite executar o codigo do endpoint automaticamente, sem exigir gerenciamento de servidores, adequado para trafego ocasional.', 3),
  ('74000000-0000-4000-8000-000000000460', '63000000-0000-4000-8000-000000000115', 'Contratar uma equipe de suporte externa para atender manualmente cada requisicao recebida pelo endpoint.', false, 'Incorreta. Atender manualmente cada requisicao nao e uma solucao escalavel nem eficiente para um endpoint de API.', 4),
  ('74000000-0000-4000-8000-000000000461', '63000000-0000-4000-8000-000000000116', 'Duplicar manualmente as mesmas configuracoes dentro do codigo de cada funcao individualmente, sem qualquer centralizacao.', false, 'Incorreta. Duplicar manualmente as configuracoes em cada funcao aumenta o risco de inconsistencias caso uma configuracao precise ser atualizada no futuro.', 1),
  ('74000000-0000-4000-8000-000000000462', '63000000-0000-4000-8000-000000000116', 'Enviar as configuracoes por e-mail para cada desenvolvedor responsavel por uma funcao especifica, sempre que houver uma atualizacao.', false, 'Incorreta. Enviar configuracoes por e-mail e um processo manual, propenso a erros e inconsistencias entre as diferentes funcoes.', 2),
  ('74000000-0000-4000-8000-000000000463', '63000000-0000-4000-8000-000000000116', 'Criar uma nova assinatura do Azure para cada funcao individual, apenas para armazenar suas proprias configuracoes separadamente.', false, 'Incorreta. Criar assinaturas separadas para cada funcao e uma abordagem desnecessariamente complexa e desproporcional para o problema descrito.', 3),
  ('74000000-0000-4000-8000-000000000464', '63000000-0000-4000-8000-000000000116', 'Utilizar as configuracoes de aplicativo (application settings) do aplicativo de funcoes, definidas de forma centralizada e acessiveis por todas as funcoes que fazem parte do mesmo aplicativo.', true, 'Correta. Utilizar as configuracoes de aplicativo centralizadas permite que todas as funcoes do mesmo aplicativo acessem as mesmas informacoes compartilhadas de forma consistente.', 4),
  ('74000000-0000-4000-8000-000000000465', '63000000-0000-4000-8000-000000000117', 'O Azure Functions, no modelo de consumo, tende a ser mais economico para rotinas que executam poucas vezes por dia, ja que a cobranca esta associada a execucao real, enquanto uma maquina virtual dedicada geralmente gera custo mesmo quando ociosa.', true, 'Correta. O Azure Functions no modelo de consumo tende a ser mais economico para rotinas esporadicas, ja que a maquina virtual dedicada gera custo mesmo durante a ociosidade.', 1),
  ('74000000-0000-4000-8000-000000000466', '63000000-0000-4000-8000-000000000117', 'Uma maquina virtual dedicada sempre tera um custo menor do que o Azure Functions, independentemente da frequencia de execucao da rotina.', false, 'Incorreta. Para rotinas que executam poucas vezes por dia, manter uma maquina virtual dedicada e ligada continuamente tende a gerar custo maior do que utilizar o Azure Functions.', 2),
  ('74000000-0000-4000-8000-000000000467', '63000000-0000-4000-8000-000000000117', 'Nao ha qualquer diferenca de custo entre as duas abordagens, independentemente da frequencia de execucao da rotina.', false, 'Incorreta. Ha uma diferenca relevante de custo entre as duas abordagens, especialmente para rotinas que executam com pouca frequencia ao longo do dia.', 3),
  ('74000000-0000-4000-8000-000000000468', '63000000-0000-4000-8000-000000000117', 'O custo do Azure Functions e sempre fixo, independentemente do numero de execucoes ou do tempo de processamento utilizado.', false, 'Incorreta. No modelo de consumo, o custo do Azure Functions varia conforme o numero de execucoes e o tempo de processamento, e nao e um valor fixo.', 4),
  ('74000000-0000-4000-8000-000000000469', '63000000-0000-4000-8000-000000000118', 'O plano de consumo padrao, que sempre inicializa novas instancias instantaneamente, sem qualquer atraso perceptivel em qualquer cenario.', false, 'Incorreta. O plano de consumo padrao pode apresentar atrasos de inicializacao em instancias ociosas, o que e justamente o problema que a empresa deseja evitar.', 1),
  ('74000000-0000-4000-8000-000000000470', '63000000-0000-4000-8000-000000000118', 'O plano Premium do Azure Functions, que mantem instancias pre-aquecidas prontas para responder rapidamente, reduzindo o impacto do tempo de inicializacao em comparacao ao plano de consumo padrao.', true, 'Correta. O plano Premium do Azure Functions mantem instancias pre-aquecidas, reduzindo significativamente o impacto do tempo de inicializacao em cenarios sensiveis a latencia.', 2),
  ('74000000-0000-4000-8000-000000000471', '63000000-0000-4000-8000-000000000118', 'A remocao completa de qualquer gatilho (trigger) configurado na funcao, simplificando sua execucao.', false, 'Incorreta. Remover o gatilho da funcao impediria seu proprio funcionamento, nao resolvendo o problema de tempo de inicializacao.', 3),
  ('74000000-0000-4000-8000-000000000472', '63000000-0000-4000-8000-000000000118', 'A reducao do tamanho do codigo da funcao para poucas linhas, independentemente do plano de hospedagem escolhido.', false, 'Incorreta. Apenas reduzir o tamanho do codigo, sem alterar o plano de hospedagem, nao resolve de forma confiavel o problema de tempo de inicializacao em cenarios sensiveis a latencia.', 4),
  ('74000000-0000-4000-8000-000000000473', '63000000-0000-4000-8000-000000000119', 'O Azure Functions e sempre a melhor opcao para qualquer tipo de carga de trabalho, independentemente do padrao de uso ao longo do tempo.', false, 'Incorreta. Para cargas de trabalho constantes e previsiveis, o Azure Functions no modelo de consumo pode nao ser a opcao mais economica em comparacao a outras abordagens.', 1),
  ('74000000-0000-4000-8000-000000000474', '63000000-0000-4000-8000-000000000119', 'O Azure Functions nunca pode ser utilizado para processar grandes volumes de dados, independentemente do cenario ou padrao de uso.', false, 'Incorreta. O Azure Functions pode, sim, ser utilizado para processar grandes volumes de dados; a questao esta relacionada a eficiencia de custo para um padrao de uso continuo e constante.', 2),
  ('74000000-0000-4000-8000-000000000475', '63000000-0000-4000-8000-000000000119', 'Para uma carga de trabalho constante e previsivel, o custo do Azure Functions no modelo de consumo pode ser proporcionalmente maior do que o de outras opcoes de computo dimensionadas para uso continuo, sendo importante comparar o custo total de cada abordagem.', true, 'Correta. Para cargas constantes e previsiveis, e importante comparar o custo total do Azure Functions com outras opcoes de computo dimensionadas para uso continuo, ja que o modelo de consumo pode nao ser o mais economico nesse cenario.', 3),
  ('74000000-0000-4000-8000-000000000476', '63000000-0000-4000-8000-000000000119', 'A decisao deve ser tomada exclusivamente com base na linguagem de programacao preferida pela equipe de desenvolvimento.', false, 'Incorreta. A preferencia de linguagem de programacao nao e o criterio tecnico central para essa decisao relacionada a padrao de uso e custo.', 4),
  ('74000000-0000-4000-8000-000000000477', '63000000-0000-4000-8000-000000000120', 'Um aumento significativo e inevitavel na complexidade geral do sistema, sem qualquer beneficio pratico relacionado a manutencao ou escalabilidade.', false, 'Incorreta. Embora arquiteturas baseadas em funcoes independentes possam introduzir alguma complexidade adicional, elas tambem tendem a trazer beneficios relevantes de manutencao e escalabilidade.', 1),
  ('74000000-0000-4000-8000-000000000478', '63000000-0000-4000-8000-000000000120', 'A eliminacao total e definitiva de qualquer necessidade de testes automatizados para o sistema como um todo.', false, 'Incorreta. A necessidade de testes automatizados nao e eliminada pela adocao de uma arquitetura baseada em funcoes independentes; ela continua sendo uma boa pratica recomendada.', 2),
  ('74000000-0000-4000-8000-000000000479', '63000000-0000-4000-8000-000000000120', 'A garantia absoluta de que o sistema nunca mais apresentara qualquer tipo de falha ou erro de execucao.', false, 'Incorreta. Nenhuma arquitetura, incluindo uma baseada em Azure Functions, garante ausencia total de falhas ou erros de execucao.', 3),
  ('74000000-0000-4000-8000-000000000480', '63000000-0000-4000-8000-000000000120', 'A possibilidade de desenvolver, implantar e escalar cada funcao de forma independente, conforme a demanda especifica de cada tarefa, alem de facilitar a manutencao isolada de cada componente do sistema.', true, 'Correta. A abordagem baseada em funcoes independentes permite desenvolver, implantar e escalar cada componente de forma independente, alem de facilitar a manutencao isolada de cada parte do sistema.', 4);

do $$
declare invalid_slugs text;
begin
  select string_agg(invalid.lesson_slug, ', ' order by invalid.lesson_slug)
  into invalid_slugs
  from (
    select seed.lesson_slug
    from imported_question_batch2_seed seed
    left join public.lessons lesson on lesson.slug = seed.lesson_slug
    group by seed.lesson_slug
    having count(distinct lesson.id) <> 1
  ) invalid;
  if invalid_slugs is not null then
    raise exception 'A importação contém lesson_slug ausente ou ambíguo: %', invalid_slugs;
  end if;
end
$$;

with resolved_seed as (
  select
    seed.*,
    lesson.id as lesson_id,
    topic.id as topic_id,
    domain.id as domain_id,
    domain.certification_id
  from imported_question_batch2_seed seed
  join public.lessons lesson on lesson.slug = seed.lesson_slug
  join public.topics topic on topic.id = lesson.topic_id
  join public.domains domain on domain.id = topic.domain_id
),
new_seed as (
  select resolved.*
  from resolved_seed resolved
  where not exists (
    select 1
    from public.questions existing
    where existing.id = resolved.id
       or (
         existing.lesson_id = resolved.lesson_id
         and lower(trim(existing.question_text)) = lower(trim(resolved.question_text))
       )
  )
),
ordered_seed as (
  select
    new_seed.*,
    row_number() over (partition by new_seed.lesson_id order by new_seed.source_order)::integer as lesson_offset
  from new_seed
),
existing_order as (
  select
    lesson.id as lesson_id,
    coalesce(max(question.display_order), 0) as max_display_order
  from (select distinct lesson_id as id from ordered_seed) lesson
  left join public.questions question on question.lesson_id = lesson.id
  group by lesson.id
)
insert into public.questions (
  id, certification_id, domain_id, topic_id, lesson_id, question_text,
  question_type, difficulty, explanation, is_published, display_order
)
select
  ordered.id, ordered.certification_id, ordered.domain_id, ordered.topic_id,
  ordered.lesson_id, ordered.question_text, ordered.question_type, ordered.difficulty,
  ordered.explanation, ordered.is_published,
  existing.max_display_order + ordered.lesson_offset
from ordered_seed ordered
join existing_order existing on existing.lesson_id = ordered.lesson_id
order by ordered.source_order
on conflict (id) do nothing;

insert into public.question_options (
  id, question_id, option_text, is_correct, explanation, display_order
)
select
  option_seed.id, option_seed.question_id, option_seed.option_text,
  option_seed.is_correct, option_seed.explanation, option_seed.display_order
from imported_question_option_batch2_seed option_seed
join public.questions question on question.id = option_seed.question_id
on conflict (id) do nothing;

do $$
declare
  imported_questions integer;
  imported_options integer;
  imported_lessons integer;
  published_questions integer;
  invalid_option_groups integer;
begin
  select count(*), count(distinct lesson_id), count(*) filter (where is_published)
  into imported_questions, imported_lessons, published_questions
  from public.questions
  where id::text like '63000000-0000-4000-8000-%';

  select count(*) into imported_options
  from public.question_options
  where id::text like '74000000-0000-4000-8000-%';

  select count(*) into invalid_option_groups
  from (
    select question.id
    from public.questions question
    join public.question_options option on option.question_id = question.id
    where question.id::text like '63000000-0000-4000-8000-%'
    group by question.id
    having count(*) <> 4 or count(*) filter (where option.is_correct) <> 1
  ) invalid;

  if imported_questions <> 120 then raise exception 'Validação do lote 2 falhou: esperadas 120 questões, encontradas %.', imported_questions; end if;
  if imported_options <> 480 then raise exception 'Validação do lote 2 falhou: esperadas 480 alternativas, encontradas %.', imported_options; end if;
  if imported_lessons <> 12 then raise exception 'Validação do lote 2 falhou: esperadas 12 lições, encontradas %.', imported_lessons; end if;
  if published_questions <> 120 then raise exception 'Validação do lote 2 falhou: esperadas 120 questões publicadas, encontradas %.', published_questions; end if;
  if invalid_option_groups <> 0 then raise exception 'Validação do lote 2 falhou: % questões possuem alternativas inválidas.', invalid_option_groups; end if;
end
$$;

commit;
